INSERT INTO `tasks` (`id`, `project_id`, `title`, `description`, `status`, `priority`, `owner_agent_id`, `legacy_owner`, `lease_expires_at`, `claim_token_hash`, `claim_reissue_pending`, `branch_name`, `delivery_commit`, `delivery_tests`, `delivery_notes`, `blocked_reason`, `status_reason`, `accepted_by`, `accepted_at`, `version`, `created_at`, `updated_at`) VALUES
  ('TS-001', 1, '兵营兵种挂载', '将兵营与可训练兵种和实际角色生成关联；兵种列表和生成规则待确认。', 'done', 100, 'codex-ts001', 'codex_ts001', NULL, NULL, 0, NULL, 'fd3e52a6cf8f18589aef397d9014c30eae1ca30d', 'PASS: Godot 4.7.2 full import; test_unit_purchase.gd RESULT 0 failures; test_sheep_flock.gd 38 assertions 0 failures; git diff --check. Existing unrelated regressions recorded truthfully: test_worker_collisions 1 failure; test_mining_cycle, test_food_jobs and test_wood_jobs have failures and hang; affected gameplay files were not changed. TS-001 is fulfilled by existing TS-026 implementation commits ccfe277 and 89e8c6b; this delivery adds ADR and traceability only.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:44:05', '2026-09-05 14:44:05'),
  ('TS-002', 1, '兵营兵种接入插件配置', '通过 TinySwordsPM / Godot 插件配置兵营兵种并接入执行逻辑；字段与同步方式待确认。', 'done', 100, 'codex-ts002', 'codex_ts002', NULL, NULL, 0, NULL, '11468547d6c823e5d446f1289c14d0a23d20395b', 'PASS: JSON snapshot schema and cross-reference validation; git diff --check; Godot 4.7.2 test_tiny_swords_pm_config.gd; test_unit_purchase.gd RESULT 0 failures. Snapshot now registers soldier/archer units, barracks/archery training.unit_runtime_ids, project unit bindings and train economy. Invalid references fall back to existing defaults. Existing unrelated dummy-renderer occlusion shader warning remains.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:59:33', '2026-09-05 14:59:33'),
  ('TS-003', 1, '树木复活时间及配置', '增加可配置的树木复活时间；复活位置、触发和占位处理待确认。', 'done', 100, 'codex-ts003', 'codex_ts003', NULL, NULL, 0, NULL, '507c1f0f7a14453474ffe81724a2d14b99776784', 'PASS: finite-forest static contract verifies forest has no respawn timer/regrowth path, felled trees retain stump state, and test_wood_jobs keeps the Trees do not regrow assertion; git diff --check passed. No gameplay code or user map was changed. Decision: TS-003 automatic regrowth is not implemented because the user confirmed standard finite-resource RTS behavior and existing WOOD-008 remains authoritative.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:10:09', '2026-09-05 15:10:09'),
  ('TS-004', 1, '房屋人口上限加成（每房+5，可配置）', '用户反馈（2026-09-05）：房屋建造完成后人口没有上涨。已确认需求：每栋房屋完工时提升人口上限，默认 +5（可叠加多房）；加成数值后期可在 TinySwordsPM 管理端配置（先行以配置常量/快照字段承载，管理端字段化属后续）；事件关联=建筑完工事件（mining_controller._build_after_delay 完工段）接入人口上限提升并刷新 HUD/提示；不改变初始人口，工人训练等人口校验沿用新的上限。注意与 TS-026/TS-030 的完工事件与集结改动共享文件，实施前须同步协调；此任务为原“房屋与人口产生挂载”的确认细化（原范围 construction/population 收紧为 population/house_capacity，避免与 TS-021 占用冲突）。验收目标：建造前后 population_cap 精确 +5、HUD/提示正确、可继续训练工人至新上限、配置值可覆盖默认 5。分类：玩法/人口与建筑；决策记录：实施时建 temp-02/docs/decisions/adr_004_house_population.md。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, '704c8cbba0db8aba8f0bdc38ce2736936318db11', 'test_house_population 18/0 (default +5, once-only, stack +10, override 8, top-bar toast, full-cap refusal, training past old cap); unit_purchase 77/0; idle_worker_rally (TS-030 merged) passed; worker_yield 15/0 incl exhaustion->idle; movement_scaling 13/0; worker_training/crowd/batch/game_hud/building_construction passed per implementer. Integrated on ee1d2c7(TS-030). Legacy mining/food/wood failures unrelated. ADR-004 + POP-001 v1.7.0 recorded.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:57:20', '2026-09-05 14:57:20'),
  ('TS-005', 1, '建造条件及反馈', '无法建造时显示原因；右侧资源不足的建造选项置灰；建造必须选中工人。具体交互待确认。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '1f4f91e62409450cfaf7179d9807af1d42360b24', 'Build conditions 9, construction 29 and HUD passed. Other pre-existing resource regressions not resolved. Worker menu migration follows in TS-012; no manual acceptance yet.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 21:31:34', '2026-09-03 21:31:34'),
  ('TS-006', 1, '羊群等扩展事件选择 UI 断开问题', '用户反馈点击羊群进行事件选择时，展开 UI 仍有部分断开。后续需复现并确认是布局衔接、按钮命中还是菜单保持问题，再修复相关扩展事件入口；原因尚未确认。验收目标：羊群事件菜单显示完整、按钮可连续正常选择。仅登记，待确认后认领。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '38bd58fe08b045d074a3290a23b694950304acc3', 'Menu 13 and real rendering passed; HUD camera batch selection real resources passed; existing food 8 failures and exit resource warnings retained. User accepted.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 16:38:24', '2026-09-03 16:38:24'),
  ('TS-007', 1, '左上地图边界被顶部 UI 遮挡', '用户反馈推拉视角到地图左上角时，顶部 UI 栏仍遮挡左上角地图。后续排查相机边界与可用显示区域的对应关系，复测拖动、缩放后的边界表现。验收目标：保留顶部 UI，同时能将左上边界地图内容完整查看，不被遮挡。仅登记，待确认后认领。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '632fad68f8a0ad28da7b579befabc100cf533b5e', 'Camera actual transform 25 checks and HUD passed. Construction, animation, batch dispatch, real resource cycles, selection, collision, sheep and freed targets passed. Existing mining 10, food 8, wood multiple/empty array and resource exit warnings retained. User accepted.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 16:30:23', '2026-09-03 16:30:23'),
  ('TS-008', 1, '建筑施工工人闪烁', '用户反馈建筑建造过程中工人出现闪烁。后续复现并检查施工动画、状态切换及建筑遮挡等可能原因，不预设根因。验收目标：工人前往施工、持续建造和完工退出过程中显示稳定，不发生异常闪烁。2026-09-03 用户确认施工不再闪烁，视觉验收通过；代码尚待提交及交付归档，状态暂保留 claimed，不绕过 review/done 流程。新反馈的完工站位、底部碰撞及前后遮挡问题归入 TS-010，不视为闪烁问题重新出现。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'a701799466d08e7e33431163007bbe477bb306f6', 'Animation 7 checks, construction, batch dispatch, real resource cycles, selection, collisions, sheep and freed targets passed. Existing mining 10, food 8, wood multiple/empty array and minimap 1 failures retained. User accepted no flicker.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 15:05:30', '2026-09-03 15:05:30'),
  ('TS-009', 1, '鼠标框选无法同时选中多个单位', '用户反馈场景存在多个工人时，鼠标框选无法同时选中多个单位。后续复现并检查框选命中、选中集合及各单位选中标记，不预设根因。验收目标：框住多个可选工人后，这些工人同时保持选中并各自显示选中反馈；保留原有单选行为，单纯选择不得中断已有工作。批量命令、编队和追加选择等规则另行确认，不在本任务登记时默认扩展。仅登记，待确认后认领。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '2d16c939c67035b18a67b335f8d072faca4078b8', 'Multi-selection 14 assertions passed; worker collisions, sheep flock and construction passed. Existing failures: mining 10, food 8, wood multiple plus empty array, minimap 1. Manual visual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:16:49', '2026-09-05 15:16:49'),
  ('TS-010', 1, '新建建筑的碰撞体积与遮挡关系', '2026-09-03 用户结合三张截图明确验收要求：图1（角色显示在屋顶上）：角色从建筑后方经过时，建筑图像应绘制在角色之上并遮住重叠部分，不能呈现踩在屋顶的效果。图2（角色与下部墙体重叠）：建筑底部实际落地占地应有碰撞阻挡；工人从下部经过时不得进入该区域，已有重叠需要排出到占地外，而不只是调整显示层级。图3（完工角色留在建筑内）：建筑完成后，应将占地内的施工工人或其他小兵安全移出至建筑旁可站立地面，不能留在墙体或屋顶图像上；安全落点应可达、不落入其他障碍，也不能困住单位。碰撞偏移、寻路障碍与完工清场使用一致的底部占地范围，不以整张贴图或贴图中心代替实际占地。前后遮挡依据单位脚底与建筑落地点关系：后方被建筑遮住，前方且已在占地外的单位正常显示在建筑前。验收分别覆盖后方遮挡、下部碰撞排除、完工移出三种情况，不能只靠提高建筑图层掩盖碰撞错误。透明或轮廓提示未获要求，不自行添加；施工阶段是否阻挡仍待确认。与 TS-008 协调，但施工闪烁已由用户验收通过。本次仅补充记录，不认领、不实施，待后续执行确认。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'c9d6b3eae2df71d0820fec7b1a575dbc75cc46b4', 'Construction 29 passed incl. arrival gate, bottom collisions, clearance and sorting; animation, batch jobs, real resource cycles, selection, collisions, sheep and freed targets passed. Existing mining 10, food 8, wood/empty array and minimap 1 failures retained; user accepted.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 16:23:10', '2026-09-03 16:23:10'),
  ('TS-011', 1, '左侧事件通知点击定位并选中目标', '点击左侧通知应快速定位对应事件目标。例如用户所述工人限制暂按工人闲置理解，点击后相机定位并选中该工人。通知必须绑定具体目标，目标失效时不能误选其他单位或报错。多工人通知聚合及定位方式待确认；与 TS-007、TS-009 协调，单纯定位选择不得中断现有工作。仅本地登记，不执行。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '68c77497ed00e7ca8597eda514cc9ba397acfa3c', 'Event focus 5, direct commands 6, construction 29, HUD, camera25, menu13, selection, batch, real resources, collisions, sheep38 and freed targets passed. Existing mining10 food8 wood/empty array failures retained; manual acceptance deferred.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 21:31:53', '2026-09-03 21:31:53'),
  ('TS-012', 1, '建筑建造入口迁移至工人菜单', '将建筑建造事件绑定到工人菜单，不再绑定到主建筑菜单。选中工人后显示其建造入口，并关联该施工工人。与 TS-005 的选中工人建造条件共同落实，避免重复实现；多选工人时如何指定施工者待确认。仅本地登记，不执行。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '868336ec0e64b69cc1993624657e973812dc2c4a', 'Build conditions/menu 10, construction 29, HUD and selection passed. Existing resource failures retained; manual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 21:31:39', '2026-09-03 21:31:39'),
  ('TS-013', 1, '主建筑菜单绑定科技树与召唤工人', '主建筑单位菜单负责科技树、召唤工人等事件，与 TS-012 的工人建造菜单区分。核查入口绑定实际功能，不能只是占位显示。本项不默认授权扩展科技内容或改变升级规则，其他主建筑事件待确认；与 TS-014 协调召唤交互。仅本地登记，不执行。', 'done', 100, 'codex-ts013', 'codex_ts013', NULL, NULL, 0, NULL, '5ad81a6d07f739ead854b3c6656a03d5cf1e3776', 'PASS: test_tiny_swords_pm_config.gd; test_technology_tree.gd verifies configured cost, one-time purchase, 20 percent mining/wood speed effect and no duplicate charge; test_unit_purchase.gd RESULT 0 failures; technology JSON contract and git diff --check pass. Existing dummy-renderer occlusion shader warnings remain unrelated.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:10:35', '2026-09-08 07:10:35'),
  ('TS-014', 1, '建造与召唤工人取消菜单二次确认', '点击建筑或召唤工人菜单选项后直接进入下一环节，不再要求额外点击执行确认。建造暂按直接进入地图放置预览、仍由用户选择有效落点确认理解，不自动选择位置；召唤工人暂按条件满足后直接进入现有训练流程理解，不跳过耗时。资源和人口校验、建造取消不扣费、一次操作不重复扣费须保留。与 TS-005、TS-012、TS-013 协调；上述解释待确认。仅本地登记，不执行。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '52f2f91706c68adb45c7c1abf1b4747a689d2041', 'Direct commands 6, build conditions 10, construction 29, HUD and selection passed. Real worker spawned after delay and single payment; no manual acceptance yet.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 21:31:43', '2026-09-03 21:31:43'),
  ('TS-015', 1, '小地图嵌入右侧菜单顶部', '将目前右上角的小地图嵌入右侧菜单的上部，重新安排下方单位与建筑命令内容。保留小地图定位交互，复核面板尺寸、缩放和鼠标命中区域；与 TS-007 的地图可视区域及 TS-011 的事件定位协调，避免新增地图遮挡或位置映射偏差。具体布局尺寸待确认。仅本地登记，不执行。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '812aec5e6b07ed30ee7aa133c4b8a9434fd3e848', 'HUD, camera, sheep menu, direct commands, construction and selection passed; OpenGL preview inspected. Command detail spacing refined after preview; ongoing regression follows. Existing resource failures retained; manual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 21:31:48', '2026-09-03 21:31:48'),
  ('TS-016', 1, '未选中状态下右侧栏显示建议事件', '未选中单位或建筑时，右侧栏展示基于当前事件的操作建议，而不是仅显示空白状态。例如工人闲置时建议重新分配任务，兵营建造完成时建议生产兵种。与左侧通知共用对应事件目标，关联 TS-011 的定位选中流程及 TS-001/TS-002 的兵营生产能力，避免重复实现。建议点击后是先定位选中并打开相应菜单，还是直接进入操作流程，及建议优先级、数量和消失条件待确认；不得因显示建议自动派工、训练或扣费。验收目标：未选中时展示有效建议，进入单位选择后恢复相应菜单，目标失效或条件变化时不保留错误操作入口。仅本地登记，不执行。', 'done', 100, 'codex-ts016', 'codex_ts016', NULL, NULL, 0, NULL, '7c87326c0354f915095dc12747d3350561406734', 'PASS: Godot 4.7.2 import; event_focus 10/0, idle_worker_rally 9/0, build_conditions 10/0, multi_selection 19/0, unit_purchase 0 failures, direct_commands 6/0, batch_dispatch 18/0, sheep_flock 43/0; OpenGL ui_empty_preview visually verified latest idle event selects six workers and shows full worker menu without auto command or camera move. Existing failures retained: worker_collisions 1, mining_cycle 10, food_jobs 8, wood_jobs 9; game_hud related TS-016 assertions pass then pre-existing title layout and missing BodyScroll stop script; dummy shader, log and exit leak warnings remain.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 08:35:16', '2026-09-08 08:35:16'),
  ('TS-017', 1, '扩大鼠标滚轮视野缩放范围', '用户希望滚轮可调整的视野范围再扩大，并希望获得最大值建议。当前本地代码 CAMERA_ZOOM_MIN=0.55、CAMERA_ZOOM_MAX=1.80、每档倍率1.12。注意 Godot zoom 越小看到的地图越多，越大则角色和建筑越大；用户所说调高是拉远范围还是近看倍率仍需确认。建议第一轮试验范围为0.40至2.40：相对当前最远视野，0.40可多看约37.5%的横纵范围、约89%的面积；2.40相对当前最大近看倍率再放大约33%。这些是待确认试验值而非已修改参数，需实测单位辨识、点选、框选及地图大小限制；UI保持固定尺寸，协同 TS-007/TS-015 复核边界遮挡与小地图定位。仅本地登记，不执行。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '15c8095b47594abcee9c42dfaed8f7f0a45af1ec', 'Zoom range0.40-2.40; camera29 selection19 HUD34 passed again with user parameters; server check passed. Collision20 sheep38 passed in previous run; existing mining10 food8 failures, wood45s timeout and exit resource warnings retained. User authorized combined config commit. Manual zoom visual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:18:03', '2026-09-05 15:18:03'),
  ('TS-018', 1, '批量派工与资源目标独占分配', '已确认分配规则：每份掉落货物只允许一名工人拾取，一只羊对应一名工人，一棵树对应一名工人，一个建造任务对应一名工人；批量采矿、伐木、狩猎采集按这些目标容量分配，不能把全部工人派到同一独占目标。金矿允许多工人同时采集。派工时预占目标，而非到达后再争抢；取消、目标失效或工人离开时释放占用，货物只拾取和入库一次，已携带货物不因换任务丢失。用户已确认：工人数超过可用目标时，未分到目标的工人原地等待；同类任务出现可用目标后自动补位，不抢占其他工人的目标。手动改派后退出原等待队列，不得被旧任务自动召回。依赖 TS-009 多选验收；与 TS-005/TS-012 的施工者规则协调。当前是规则确认记录，不等于 TS-009 已验收，也不等于认领、开发或推送授权；仍待执行流程确认。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'ebed647b6376815d9e9002d0e3caaa9edb972222', 'Focused tests passed: batch dispatch 18, real resource cycles 4, multi-selection 14, construction 16, collisions, sheep flock 38, freed targets. Existing failures retained: mining 10, food 8, wood multiple plus empty array, HUD minimap 1; headless exit resource warnings. User explicitly accepted TS-018 on 2026-09-03.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-03 11:44:19', '2026-09-03 11:44:19'),
  ('TS-019', 1, 'Godot 项目控制台一键启动管理服务', '用户已确认并授权本次任务的认领、代码和交付推送。将 temp-02 插件按钮改为启动并打开管理页面，复用健康检查，服务未运行时后台启动 TinySwordsPM，防重复启动，显示路径、Python、端口及启动超时等错误。插件目录及专用测试、使用文档为修改范围；不修改游戏玩法、场景或其他任务代码。', 'done', 100, 'codex-pm-launcher', 'codex_pm_launcher', NULL, NULL, 0, NULL, 'aeff7a30fb18dfb445716d0428a69f497eda90fc', 'Godot 4.7.2 headless editor import passed; 11 launcher integration tests passed, including cold start, reuse, concurrent launch, Chinese/space paths, missing Python/path, server failure, timeout and dock button states. Worker collisions and sheep flock passed. Existing gameplay failures retained: mining 10, food 8; wood 9 assertions plus invalid array access, terminated after 25s timeout. Browser window opening and visual acceptance pending; details in temp-02/docs/pm_service_launcher.md.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:10:40', '2026-09-08 07:10:40'),
  ('TS-020', 1, '放大右栏小地图并将命令标题移到其下方', '用户明确要求右栏顶部小地图放大，工人命令等标题移到小地图下方。保持右栏宽度、地图定位及下方滚动命令可用。本任务不修改工人碰撞；用户已要求碰撞部分先不展开，继续其他任务。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'cac6f6578926888b771eedebea9778f55aa8de45', 'HUD, camera safe bounds, direct commands, event focus and sheep menu passed. Actual OpenGL preview inspected; minimap 236x178 above title. Worker collision unchanged; existing resource test failures and exit warnings remain. Manual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:20:00', '2026-09-05 15:20:00'),
  ('TS-021', 1, '工人互相碰撞与障碍绕行', '用户确认同时处理工人之间不可重叠、与建筑树木等障碍的脚底碰撞；移动需要绕行让位，不能因开启硬碰撞导致多人挖矿、交付或建造堵死。保留独占羊树货物规则，金矿支持多人；检查出生、停靠和拥堵重试，不改变资源产出和费用。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'd9c7d334e9846e18c09479da27d63c3ca73866c4', 'Crowd 5 passed incl ten workers two mining cycles, head-on passage and no overlap; real resources, batch dispatch, static collision, construction29, training, build conditions, selection, HUD, sheep38 and freed targets passed. Existing mining10 food8 wood/empty array failures and exit warnings retained. Manual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:23:15', '2026-09-05 15:23:15'),
  ('TS-022', 1, '矿洞内独立采集与安全出洞', '用户确认：工人到达矿口才隐藏并关闭碰撞，矿洞内不限工作位，各自按原配置独立计时；采完从矿口附近安全出洞恢复碰撞并运输。矿上显示采矿人数。中途改派需安全出洞、不丢已有货物、不结算未完成采集。保留洞外碰撞；5人并行采集不保证运输入库严格5倍。用户已授权本次认领与交付普通推送。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'f9cc3f899a6b700f936b4ff055bc534f6fb242b0', 'Mine interior 18 passed, including five concurrent miners, real blocked exit, no duplicate cargo, safe emergence and cancellation. Crowd five passed incl ten workers two delivery cycles. Batch real resources, dispatch, collisions, construction, direct commands, selection, HUD, sheep38 and freed references passed. OpenGL preview inspected; editor import passed. Existing mining10 food8 wood assertions/empty array failures and exit RID warnings retained; see docs/ts_022_mine_interior.md. Manual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:10:44', '2026-09-08 07:10:44'),
  ('TS-023', 1, '建筑内并行交付与露天金矿对比', '用户确认并授权认领交付推送：工人到城堡入口后隐藏，各自按原交付时间完成入库，安全出门；保留中途取消货物与一次性结算。增加一处露天矿石作为对比，工人在矿石旁可见挥镐，不隐藏、不远距离采集；建筑型金矿保留洞内采集。沿用配置产量时长，不调整地图原始绘制或经济费用。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '028976a5a56e160befd474071d48e4305c2d9995', 'Depot/outdoor integration18 and ore slots6 passed. Mine interior18, ten-worker two-cycle crowd, batch real resources, dispatch, collision, construction, direct commands, multi-selection, HUD, sheep38 and freed references passed. OpenGL comparison inspected; headless editor import and diff check passed. Existing mining10 food8 wood assertion/empty-array failures and exit RID warnings retained; see docs/ts_023_depot_and_outdoor_ore.md. Manual acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:10:49', '2026-09-08 07:10:49'),
  ('TS-024', 1, '矿点工人容量配置与露天采集约束', '用户授权认领、配置代码修改及普通推送。管理页面增加每矿点采集工人数上限，建筑金矿默认5、露天矿石默认2；配置经插件快照实际加载，超额等待且不挥镐不产出，空位释放后补位。检查露天矿石攻击距离和朝向，城堡存放容量不变。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'b205f064ee5f999d3b563d5416198715eb25870c', 'User accepted TS-024. PM unittest18 and server check passed; capacity12 collision20 sheep38 HUD34 depot18 ore slots7 passed. Legacy mining10 food8 failures; wood timed out at45s; exit resource warnings remain. PM code committed separately; docs/ts_024_mining_capacity.md records validation.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-04 12:54:18', '2026-09-04 12:54:18'),
  ('TS-025', 1, '工人局部优先级让路与城堡通道疏通', '用户确认局部请求让路：运输优先于赶路，空闲和等待最低，同级稳定编号决定；低优先级暂存任务侧移，通道腾出后高优先级通过。每次锁定一个请求和落点；新用户命令打断；无安全位置不得穿透。资源耗尽保留任务并在通道外等待。验证六工人六树全部交付、迎面和多人通过、任务货物不丢不重复结算。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '8e90557c5f865ffb0a0f41d28a1db1057cb6ff88', 'Yield15 incl six actual trees all deposited and doorway clear; crowd5 incl ten workers two cycles; final real-resource4 capacity12 passed. Depot18 batch18 collision20 construction29 selection19 HUD34 interior18 sheep38 freed targets passed. Editor import and OpenGL yield15 passed. Legacy mining11 confirmed same failures on pre-change15c8095; food8; wood9 plus invalid array and50s timeout; exit resource warnings remain. Manual acceptance pending; docs/ts_025_worker_yield.md.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:10:59', '2026-09-08 07:10:59'),
  ('TS-026', 1, '兵营/弓箭营购买兵种与出兵集结范围', '用户确认细则：步兵（近战战士）金币50/4秒/人口1，弓箭手金币60/4秒/人口1，与召唤工人对齐、后续可经配置调整；兵营与靶场落成后在门口生成发光购买点，点击即按命令面板样式购买；兵营、主城（城堡）、弓箭营（靶场）出兵后新单位在建筑中心周边64px内集结等待、不超出范围，城堡现有工人训练出兵同样遵循；可继续下达命令。现有基础：temp-02 已配置兵营（木材160/金币60/10秒）与靶场（木材180/金币50/9秒）建造价格，HUD 注明建造后\"解锁步兵/解锁弓手\"；城堡训练仅支持 worker（金币50/4秒），规则 TRAIN-001/002（城堡交付点附近生成工人）；房屋/兵营/塔/靶场建造入口与放置规则见 docs/gameplay_interaction_rules.md（UI-006/UI-007/BUILD-001）；registry 已登记 unit_0001-0003 近战战士数值可作兵种参数来源。待确认（不阻塞开发）：兵种数量上限与后续战斗规则、弓箭手数值具体来源。验收目标：兵营光点可购买步兵、弓箭营光点可购买弓箭手并正确扣费（含资源/人口不足不扣费）与生成；兵营、主城、弓箭营出兵后单位集结于建筑周边64px范围内、不超出范围。兵种选择/移动/战斗与数值插件化属后续任务（TS-001/TS-002 及战斗任务），不在本任务验收范围。分类：玩法/单位生产与集结；决策记录：map-build-temp-01/temp-02/docs/decisions/adr_002_ts026_recruit_rally.md。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, '209c16d6be832b1cc3a6eca36c2d24dab93fe524', 'TS-026 v3 返工（2026-09-05 用户要求圆心=建筑本体）：test_unit_purchase 77 断言通过（兵营占地中心/城堡碰撞中心为允许圆圆心、默认集合点=门口/交付点且在圆内、圆外拒/圆内落、真实输入链路购买、出生≤96 按建筑中心计）；test_movement_scaling13、worker_yield15、crowd5、batch18、game_hud34、worker_training 通过。集成于 TS-028 之上。历史遗留失败类（mining/food/wood）与本任务无关。购买入口仍为门口光点（悬停提示+完工指引）；手动视觉验收待复验。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:57:18', '2026-09-05 14:57:18'),
  ('TS-027', 1, '决策记录规范与移动系统架构决策归档', '用户明确要求将沟通最终方案、问题描述、挂载任务和分类本地留档。建立 docs/decisions 索引、模板和 ADR-001，记录 TS-025 验收反馈、采用分层移动系统的架构方向及实施边界。分类：工程治理/决策追踪；关联实施任务 TS-028。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '36d583eae590bc0c1c1a0fd6f47ff1a779492726', 'Documentation validated: local Markdown links resolve; required problem/final decision/task/category sections present; TS-027 and TS-028 project associations verified; diff check passed. No gameplay code changed. ADR-001 records approved architecture, unconfirmed soft overlap and TS-026 coordination boundary; TS-028 not claimed.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:11:04', '2026-09-08 07:11:04'),
  ('TS-028', 1, '分层单位移动系统与规模性能验证', '用户已同意采用共享地图寻路、局部邻居查询/避障、出入口规则分层及分批计算方向，详见 temp-02/docs/decisions/adr_001_unit_movement.md。问题：TS-025 验收中单位相遇走停，多人时明显；真实画面掉帧与计算耗时尚未测定。分类：架构/单位移动；性能/寻路与局部避障；缺陷/拥挤卡顿。计划100/200/300单位分散、交汇、出口压力原型验证，不宣称现有战斗系统或既定性能。实施边界已收紧：TS-026已交付review，提交ccfe2770；TS-028只读取其64px集结与出生接口，不修改购买、扣费、出生或rally_point规则，不接管TS-026。软重叠未确认，保留物理碰撞。软重叠没有明确确认，保留物理碰撞。用户已确认架构方向并指示同步后认领推进；范围收紧后可执行。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, '617276ff3e83e8f6bd94aba956a0b1fc2eed0660', 'PASS: test_movement_scaling (100/200/300), test_worker_yield, test_freed_resource_targets, test_batch_dispatch, test_unit_purchase. test_worker_crowd first 4 checks passed; long 10-worker mining loop retained as extended regression.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:11:09', '2026-09-08 07:11:09'),
  ('TS-029', 1, '工人超20人全选派发指令卡顿排查与优化', '用户反馈（2026-09-04）：大量训练工人，工人超过约20人时一次性框选全部工人并发送一条指令（右击地面移动/指派），出现明显卡顿。静态代码排查结论（未实测）：主因是点击当帧 N 名工人同步各自执行含全量障碍的可见图 A*（mining_controller _move_selected_group 先算一次可达性即弃、command_move/_travel 路径请求再算一遍=路径双算；每请求 _find_worker_path 触发 _refresh_navigation 全量重建，同帧重复 N 次），叠加移动期 worker_traffic.avoid 每物理帧 O(N²) 全组扫描、blocked≥0.5s 全量重寻路尖峰；HUD/渲染已排除。分类：性能/命令派发与寻路；关联：ADR-001、TS-025（已 review）、TS-028（已 review，实施已完成并含 test_movement_scaling，共享 worker_navigation/movement_performance 范围；TS-029 若实施须基于 TS-028 现状重新核对候选快赢是否仍适用并协调）。候选快赢（不动架构）：a1 消除路径双算（命令路径直接传给 command_move）；a2 导航重建脏标记（同帧 N 次 _refresh_navigation 合并）；a3 全选>阈值降级提示；更大优化（全组避障空间划分、分批预算寻路）已在 TS-028 分层移动系统范围。方案与 owner 待用户确认；建议先建 headless 基准（10/20/40 工人全选+派发单帧耗时）验证现况是否仍有卡顿再动优化。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'e6e0b831fdc4e80d108311f2d666b7e383f396e4', 'PASS: command dispatch scaling 10/20/40 workers (11.675/13.393/17.499 ms; 8 immediate paths; 2/12/32 deferred), movement scaling, batch dispatch, multi-selection, sheep flock (43 assertions). Existing unrelated mainline failures retained: worker collisions 1, mining 11, food 8, wood 9 then invalid array; headless clip shader/meta errors.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:11:14', '2026-09-08 07:11:14'),
  ('TS-030', 1, '闲置工人集结与一键选择', '用户确认：工人完成存放后优先延续原任务；仅在资源已耗尽或任务目标确实消失时，前往城堡右侧闲置集结区的离散站位，避免堵塞出入口。暂时没有可分配采集位的工人保留任务和等待状态，不归入闲置。左侧事件聚合显示闲置工人数；未选中单位时右侧显示‘闲置工人’入口，点击任一入口同时选中所有闲置工人并定位集结区。分类：玩法/工人调度、建筑入口、单位选择；决策记录：map-build-temp-01/temp-02/docs/decisions/adr_003_idle_worker_rally.md；接续 TS-028。', 'done', 100, 'codex-local-multiselect', 'codex_local_multiselect', NULL, NULL, 0, NULL, 'ee1d2c7e803146e1181a39bf9e4474b3f2e3feb7', 'Godot 4.7.2 editor parse passed; test_idle_worker_rally, test_unit_purchase, test_game_hud, test_worker_yield, test_batch_dispatch, test_movement_scaling and test_worker_collisions passed after TS-026 v3 merge.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 03:31:43', '2026-09-11 03:31:43'),
  ('TS-031', 1, '项目控制台：建筑配置显示与碰撞/集结半径可视化编辑', '用户需求（2026-09-05）：1) 将\"建筑集合可操作的半径\"做成配置放到项目控制台（TinySwordsPM Web http://127.0.0.1:8765），按建筑类型各一条（城堡/兵营/靶场等，默认 96，游戏侧 TS-026 硬编码改读该配置并带默认回退）；2) 建筑配置（如碰撞体积）同步显示在控制台右侧\"实时预览\"窗格；3) 支持在预览窗格上对碰撞体积手动拖拽调整（四边/四角改宽高+整体拖拽调 offset_x/y），并按原素材比例展示；保存走既有校验与原子提交，单位碰撞编辑范围后续再扩。分类：玩法/建筑配置与集结点；工具/Web 控制台；关联：TS-026（集结半径读取方）、TS-001/TS-002（PM 配置接入）、TS-004（房屋人口可配置化同思路）。决策记录：TinySwordsPM/docs/decisions/adr_001_console_building_editor.md（建库时启用）。实施说明：控制台侧改动在 TinySwordsPM 仓库（web/app.js、styles.css、tools/server.py 校验、registry 结构、快照/导出），游戏侧读取在 map-build-temp-01/temp-02 另行同步；多仓库交付需分别推送并记录。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, '2280010e6e51978d61e832072f51773730d28b7c', 'PM unittest 27 passed (registry valid, rally_radius default/invalid rejected, collision min-size+shape, save roundtrip atomic, export/snapshot seed includes rally+collision idempotent); python tools/server.py --check passed. rally_radius per building (default 96, 1-512) with console number field + init/seed tooling; collision drag preview (rect/capsule edges+corners, circle radius, offset drag, min 8 units, ratio 1.25px) manual browser acceptance pending; game-side temp-02 consumption out of this repo commit.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:57:22', '2026-09-05 14:57:22'),
  ('TS-032', 1, '控制台扫描与素材刷新优化（范围/独立/过滤）', '用户反馈（2026-09-05）：项目拉取/扫描后页面素材仍是旧的，希望优化扫描：(a) 扫描范围=只扫项目实际加载的内容，不要历史/未使用内容；(b) 独立存储=每个项目独立扫描、文件独立；(c) 过滤展示=作废或未标记的素材不在页面展示。现状（只读核查）：Godot 插件（temp-02/addons/tiny_swords_pm）扫当前编辑器场景节点树 POST /api/project-scan，服务端原子写入 data/scans/<project_key>.json（已按项目独立文件，含 project_id/scene_path/entities/scanned_at）；素材库 661 条来自 tools/import_asset_catalog.py 按整包素材目录生成的静态 asset_catalog（meta.generated_at 为历史时间），与具体项目加载内容无关。待确认：\"素材旧\"指素材库清单(asset catalog)还是扫描 entities/建筑记录；\"实际加载\"=仅当前场景引用/绑定的记录，还是含项目插件拉取的全部项目配置；\"作废/未标记\"的判定标准（registry 记录是否绑定项目？rating/meta 标记？还是页面隐藏标记）；独立存储是否需要额外目录/命名（现已有每项目 json）。分类：工具/Web 控制台；扫描与素材管理；关联 TS-031（同 owner dsh_map_dev review，可 --continue-from 接续）。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, 'b5017cdc2f208c2d7890840c3e5740953c186ba6', 'PM unittest 49 passed (incl library_scope reference rules, retired flag, asset_preview resolver); server --check passed; node --check app.js passed; /api/library-scope + /api/preview-source smoke 200 (temp-02 scope 7/661). Project-scope default view, retired filtering, per-project scan files unchanged, scanned_at shown. Browser interaction manual acceptance pending; local 参考素材 dir absent so previews show clear missing-file note (expected).', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:06:27', '2026-09-05 15:06:27'),
  ('TS-033', 1, '控制台新增建筑/素材的真实素材预览展示', '用户反馈（2026-09-05）：控制台右上预览区只显示图标/占位，新建建筑未展示实际素材图，希望把真实素材显示在预览框里，更直观美观。现状（只读核查）：web/app.js renderPreview 对 building 记录优先用 visual.preview_asset_id 找 registry.assets 对应素材作背景，找不到则显示占位（图标/色块）；server /source-assets/ 只从 SOURCE_ASSET_CANDIDATES 素材目录提供 catalog 记录的 source_relative 文件；新建建筑若未登记 preview_asset_id 或素材不在 catalog 就没有预览。待确认：预览素材解析优先级（visual.preview_asset_id → assets.normal 路径就近匹配 catalog → 直接按相对路径从素材目录/项目资源目录取图？）；对非 PNG/多帧/特效素材的展示规则；是否需要自动为新建建筑登记 preview_asset_id。分类：工具/Web 控制台；素材预览。关联 TS-031（同 owner dsh_map_dev review，可 --continue-from 接续）。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, 'b5017cdc2f208c2d7890840c3e5740953c186ba6', 'PM unittest 49 passed incl preview resolution chain (preview_asset_id -> assets path filename match -> placeholder); server --check + node --check ok; manual browser acceptance pending for async preview & drag overlay coexistence; asset source dir absent shows explicit 404 note.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:57:24', '2026-09-05 14:57:24'),
  ('TS-034', 1, 'PM 插件启动按钮支持重启服务', '用户需求（2026-09-05）：控制台代码更新后需要重启本地服务；希望改造 Godot 插件（temp-02/addons/tiny_swords_pm），点击「启动并打开管理页面」时若服务已在运行则先停止旧进程再后台启动（重启），使新代码立即生效并打开页面；未运行时行为不变（后台启动）。实现：service_launcher.gd 增加 restart 路径、start_service.ps1 增加 -Restart（按端口停旧进程后启动）、pm_dock.gd 按钮改传 restart；更新 addon 使用文档。分类：工程治理/工具（PM 服务启动器）；关联 TS-019（原启动器任务，owner codex）。交付验收：运行中点击=重启并最终打开页面；未运行=普通启动。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, '234cddfbc5f49613704ffe358c654cf3d6346291', 'Rework 2026-09-05 (user: restart hangs no progress): root cause = restart flag not consumed so healthy state retriggered restart forever; fixed by consuming _restart_if_running before relaunch. Added: per-second staged progress via launcher.progress (helper writes stopping/starting states), restart deadline +8s stop allowance, dock ProgressBar pulse while busy and \'打开启动日志目录\' button (user://tiny_swords_pm_launcher). start_service.ps1 parses clean (UTF-8 BOM); Godot headless editor parse smoke passed; follow-up chore cd4915d captures editor scene reserialization. Manual verify pending: with service running click button -> staged progress, single restart, opens page; stopped -> normal start; failures show log path & folder button opens logs.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:57:26', '2026-09-05 14:57:26'),
  ('TS-035', 1, '预览编辑器返工：碰撞拖拽 bug 修复与“遮罩”多边形编辑', '用户反馈（2026-09-05，TS-031 控制台验收）：右上预览的碰撞拖拽**点击框框后跳到左上角、之后无法继续操作**（具体 bug，待复现修复：事件/坐标换算或指针状态导致起点丢失）。已确认方向：(a) 预览区底部提供工具栏按钮（含“遮罩”按钮），点“遮罩”进入遮罩框编辑；(b) 遮罩=围绕建筑的**多边形顶点编辑**（拖拽顶点、加/删点），坐标以建筑自身为基准、**归一化 0..1** 存储（可选新字段，如 visual.mask_polygon=[[x,y],...]），后续素材/建筑放入地图按比例缩放应用；物理碰撞（矩形/圆/胶囊，宽度高度偏移）保持现机制并同样按比例展示，二者并存；(c) 修复现有碰撞编辑器展示与交互问题（含跳到左上角 bug、手柄可操作性、数值与表单联动、保存原子化）。分类：工具/Web 控制台；素材与碰撞编辑。关联：TS-031（review，同 owner dsh_map_dev）。验收：碰撞框点击后不跳位、可连续拖拽与保存；遮罩模式可编辑多边形并正确显示/保存/读回；归一化坐标字段有校验与测试。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, '88e5e8c478f8f2799998a2705609adc29dd75274', 'PM unittest 66 passed (mask polygon validation/roundtrip, mounts parse/match/filter, prior 49); server --check ok; node --check app.js ok. Preview drag jump fixed (root cause: stale cached stage rect + full re-render per move; now live rect + grab-offset follow + lightweight update, pointer capture cleanup). Mask editor: toolbar 碰撞/遮罩/说明, visual.mask_polygon normalized 0..1 (3..64 pts) with vertex add/drag/remove, save atomic. Manual browser acceptance pending.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:06:29', '2026-09-05 15:06:29'),
  ('TS-036', 1, '场景扫描采集素材挂载状态与筛选', '用户需求（2026-09-05，TS-032 延续）：点击“扫描当前编辑场景”时，素材库加载出**该场景实际引用**的素材并赋予“挂载状态”：1) 素材被场景加载→状态“已挂载”；2) 标识挂载到的具体场景（scene_path）；3) 素材库新增按状态（全部/已挂载/未挂载）及场景的筛选。匹配规则（用户选 A）：场景采集到的资源（res:// 路径：Sprite 贴图、AnimatedSprite 帧、TileSet/其余资源）按**文件路径/文件名自动匹配**素材库 catalog 条目，无需手工绑定。实现拆两仓：temp-02/addons/tiny_swords_pm（pm_dock 扫描扩展：遍历当前场景实际引用的资源与所属 scene_file_path，上传“resources:[{path,type}]”；不改场景/不入库缓存）；TinySwordsPM（server 收存挂载映射（随 data/scans/<key>.json 或独立挂载文件、原子写）、web 素材库状态字段/场景标识与筛选、tools/asset_preview 复用路径匹配、单测）。分类：工具/Web 控制台；扫描与素材管理。关联：TS-032（review，同 owner dsh_map_dev）。验收：扫描 temp-02 场景后，素材库出现“已挂载(场景路径)”状态并可筛选；重复扫描覆盖不残留旧场景挂载；对 catalog 未收录的路径给出未匹配提示。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, '88e5e8c478f8f2799998a2705609adc29dd75274', 'PM unittest 66 passed incl mounts; plugin commit 04f4111 (temp-02 addon scene_resources.gd + pm_dock scan resources, no editor run). /api/mounts ok; library shows mounted badge+scene and filters by status/scene (combined w/ project/all/retired); unmatch count notice. Godot plugin resource collection needs editor reload + manual scene scan acceptance (uid sidecar generated on editor open).', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:57:28', '2026-09-05 14:57:28'),
  ('TS-037', 1, '控制台预览面板可拖拽调宽与放大编辑', '用户需求（2026-09-05）：控制台右侧实时预览/编辑面板（碰撞与遮罩编辑所在栏）希望可拖拽调宽并可放大成可移动编辑窗，便于编辑。实现：右栏左缘拖拽分隔条改宽（记住宽度）+ 放大按钮切换浮层编辑窗（可拖动标题栏移动、右下角缩放，可返回）。范围 TinySwordsPM web（app.js/styles/index）与工具/测试。分类：工具/Web 控制台；关联 TS-031/035（同 owner review）。交付：拖拽调宽不破布局、放大窗可移动缩放、保存/遮罩交互保留。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, 'e7a05e36cc97ca1faba5688df98e929a8c851424', 'A1 accepted: preview art-fit geometry anchored to asset, divider drag width memory, magnify floating editor; node+unittest66+server check green.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:57:42', '2026-09-05 14:57:42'),
  ('TS-038', 1, '遮罩在游戏内作为视觉遮挡层生效', '用户需求（2026-09-05，承接 TS-035 的 visual.mask_polygon 数据）：遮罩数据已能在控制台编辑保存，游戏内尚未消费。已确认语义=视觉遮挡层（非阻挡）：带 mask_polygon 的建筑，单位处于其多边形覆盖区（建筑身后区域）时被建筑盖住、不叠在建筑图之上；点击/命中仍用现有碰撞/图元规则。需要先在 temp-02 摸清 runtime 建筑与 worker/soldier 的 y-sort/绘制顺序机制，选最小可靠方案（如按单位脚点是否落在多边形内且位于建筑后侧，动态调整其绘制次序/渲染子层），不改物理阻挡；归一化坐标按建筑贴图视觉盒比例换算（与 TS-035 约定一致）。分类：玩法/视觉表现与建筑；关联 TS-035（数据）、TS-026（soldier/worker）。交付：多站位遮挡表现正确、既有采集/集结与测试不回归、渲染对比或单测记录。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, '02f1018a01af0fdea1de276a70d127bc4e857904', 'TS-038 v3 polygon-clip occlusion accepted by user (F6): visual_occlusion 29/0, runtime collision 40/0, regressions green.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:53:31', '2026-09-05 15:53:31'),
  ('TS-039', 1, '控制台建筑碰撞编辑在游戏内生效为阻挡区(含兵种)', '用户需求(2026-09-05):控制台编辑建筑碰撞后,游戏内以该区域为阻挡区,工人与兵种都不能通过/进入。缺口:runtime建筑(house/barracks/tower/archery)在PM无登记;castle已登记但游戏未消费building记录碰撞;兵种collision 0不被挡。实现:TinySwordsPM侧补runtime建筑记录(runtime_key、默认碰撞=现常量、rally96、mask空)入bindings与快照导出(原子幂等);temp-02侧建房/城堡按快照记录建碰撞形状(rect/circle/capsule,offset语义足底锚定),兵种改layer2/mask15。遮罩维持视觉遮挡层(TS-038)。关联TS-001/002、TS-031/035、TS-038。验收:改碰撞-拉快照-F6,工人与兵种均被拦。', 'done', 100, 'dsh-map-dev', 'dsh_map_dev', NULL, NULL, 0, NULL, 'de63f7c2b6638fc3e2c7582b2cafe66ecd39dc35', 'TS-039 accepted: runtime building records + snapshot-driven collision blocks workers and troops; game commit 02f1018; PM registry/contract/tooling de63f7c; runtime tests 40/0 + regressions green.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 15:52:28', '2026-09-05 15:52:28'),
  ('TS-040', 1, '素材管理台整合任务进度与详情', '用户已确认：参照旧素材与任务索引，在新素材管理台加入任务入口、状态统计、搜索筛选、完整详情和刷新；使用现有任务接口，不迁入旧任务，不更改认领流程。分类：工具/Web 控制台。决策：docs/decisions/adr_007_task_dashboard.md', 'done', 100, 'codex-task-dashboard', 'codex_task_dashboard', NULL, NULL, 0, NULL, '59b22e0afb5cd112c9afa0d341c1c50fec5bbe13', '72 Python tests passed; node syntax and server check passed; browser verified counts, 55% done-only completion, TS-004 search/delivery, status-filter empty state and readable screenshot. Original dirty checkout preserved; independent console port 8766.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-08 07:10:54', '2026-09-08 07:10:54'),
  ('TS-041', 1, '教程素材索引原框架整合任务进度', '用户纠正目标为 godot-game-learn-main：在原网页导航、米色绿色样式框架中新增任务进度与详情，使用 TinySwordsPM 任务源，保持素材/教程/词典。分类：工具/素材索引。决策：godot-game-learn-main/docs/decisions/adr_001_task_dashboard.md。TS-040为此前错误目标实现，不代表本任务验收。', 'done', 100, 'codex-task-dashboard', 'codex_task_dashboard', NULL, NULL, 0, NULL, '85b6da076a599e9dfd7d2c20c004a81053b4aff6', 'PASS: asset index/catalog checks (841 files), catalog, animation, glossary four-view routing, detail resize, node syntax; task HTTP fresh-read/read-only/malformed-data tests. Browser: existing paper/green theme, task view, asset selection and action switch. Uses canonical local TinySwordsPM tasks; no auto Git sync.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:20:52', '2026-09-05 14:20:52'),
  ('TS-042', 1, '任务状态配色与详情表单化优化', '用户反馈（2026-09-05）：任务列表中的未认领、已完成等状态需要用不同颜色区分；右侧详情按表单结构规划。沿用 godot-game-learn-main 原米色/绿色 UI，完善五种状态色、状态徽标、负责人提示、详情分组和只读表单字段，并保持搜索筛选与移动端布局。接续 TS-041，分类：工具/素材索引；决策追加于 docs/decisions/adr_001_task_dashboard.md。', 'done', 100, 'codex-task-dashboard', 'codex_task_dashboard', NULL, NULL, 0, NULL, '413b0e4d31ee453af57dbe1c3d9642b2d14715e2', 'PASS: task_dashboard.js syntax; four-view routing; detail resize; animation regression; static contract verifies gray unclaimed states, green completed cards, five status badges, real readonly input/textarea fields, responsive layout. User visually reviewed 8767 page and accepted on 2026-09-05. Asset catalog check still reports pre-existing line-ending mismatch in isolated clone; related catalog/tutorial files unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-05 14:01:03', '2026-09-05 14:01:03'),
  ('TS-043', 1, '树木新增受击抖动效果', '用户需求（2026-09-05）：为树木增加受击抖动效果。目标工程：map-build-temp-01/temp-02。分类：交互/资源受击反馈。验收：每次有效砍击触发短暂可见抖动，结束后恢复原位，不产生累计位移；保持三次完整砍击后变树桩并掉落 1 木材的规则，碰撞与采集流程不受视觉抖动影响。抖动幅度和时长为实施时可调视觉参数。实施前在目标工程 docs/decisions/ 创建决策记录并回填路径，更新相应玩法基准与回归测试。决策记录：temp-02/docs/decisions/adr_011_tree_hit_shake.md。验收反馈（2026-09-06）：原版树木在工人砍击动作结束后才抖动，体感有延迟；已改为单次挥斧 55% 命中帧立即触发。后续反馈要求动作快速且短暂，抖动压缩至 0.08 秒并使用快速加减速回弹；完整挥斧和资源结算时序不变。', 'done', 100, 'codex-ts043', 'codex_ts043', NULL, NULL, 0, NULL, 'e0e8a31e39e5e4fb9810163860770a6e44253197', 'PASS: tree shake remains aligned with axe impact at frame 33/60 (55 percent), now uses a fast easing curve and completes in 0.08 seconds while full swing settlement remains frame 60; test_tree_hit_feedback.gd 18 assertions 0 failures; OpenGL real-render saved rest/shaking/recovered frames; git diff --check. Existing mainline regression results are unchanged from the prior TS-043 review record. Environment emits root-certificate/log/editor-settings permission warnings.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-06 13:09:00', '2026-09-06 13:09:00'),
  ('TS-044', 1, '羊受击红色闪烁并改为攻击两次掉肉', '用户需求（2026-09-05）：为羊增加受击红色闪烁效果，并改为需要两次有效攻击才能变成肉。目标工程：map-build-temp-01/temp-02。分类：玩法/食物采集；交互/资源受击反馈。验收：有效命中触发红色闪烁；第一次命中后羊仍存活且不掉肉，第二次命中后变成肉，只掉落 1 食物；闪烁结束恢复原色；保持搬运、城堡交付和繁殖流程。用户确认（2026-09-06）：受击次数保存在羊自身，中断或换另一名工人后不重置；第二次命中先播放快速红色闪烁，再变成肉并掉落 1 食物。范围协调（2026-09-06）：利用 sheep_flock 返回的待生效肉块维持致命攻击者的领取权，不修改 worker.gd，因此不进入 TS-022 占用的 worker_jobs 范围。验收返工（2026-09-06）：用户发现第二击后、肉块显示前，工人会切换攻击旁边的羊；修正为当前工人预约对应肉块，红闪期间肉块不可见、不可枚举、不可拾取，红闪完成后直接进入拾取流程。第二次返工（2026-09-07）：用户要求缩短受击动作与闪红反馈的间隙；红闪前移到攻击动画 50% 命中帧，完整攻击仍在 1 秒时结算，命中帧后取消不增加命中次数。第三次返工（2026-09-07）：第一次攻击仍在 50% 闪红；第二次致命攻击的 0.10 秒闪红对齐攻击结算末端，闪红完成信号立即显示已预约肉块，消除恢复原色后的等待。决策记录：temp-02/docs/decisions/adr_012_sheep_two_hit_feedback.md。', 'done', 100, 'codex-ts044', 'codex_ts044', NULL, NULL, 0, NULL, '3c5961a07f32c249fc35c668bac4eabc336c2284', 'Third acceptance rework was not automatically tested or rendered at the user\'s explicit request; user will perform validation. Change aligns the lethal 0.10-second red flash with attack settlement so its completion signal immediately activates the reserved meat. Previous verified baseline: test_food_jobs 51 assertions with 8 existing mainline failures; sheep_hit_feedback 14/0, sheep_flock 43/0, tree_hit_feedback 18/0; unrelated worker_collisions 1 failure, mining_cycle 11 failures, wood_jobs existing failures remain recorded.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-07 14:10:02', '2026-09-07 14:10:02'),
  ('TS-045', 1, '城镇道路拥堵与单位寻路方案优化', '用户提出在城镇道路拥挤、全图约一两百个活动单位且工人约几十个时继续优化 Warcraft 风格单位通行。基于 TS-028 已实现的共享静态导航、空间网格和分帧寻路预算，补充城镇交通层：道路采用低基础成本与平滑变化的拥堵成本，避免瞬时改道震荡；宽路提供稳定靠右/固定侧避让与减速跟随；城门、桥梁、窄巷等单宽瓶颈采用方向锁、等待队列、公平换向和通道外等待区，不预约整条路径；仓库、矿点、工地等共同目标提供接近/工作/等待槽位，禁止多人争抢单一坐标；卡死按减速、侧移、让行、后退、冷却后重寻路、替代落点分级恢复；调度优先近距离和区域化工人，并错峰派发。实施前需同步并协调 TS-029 正在占用的 worker_navigation/movement_performance 范围，不修改其认领内容；本任务不放开单位物理穿透，软重叠仍需另行确认。验收目标：双向宽路不长期顶死或左右抖动；窄口双向流可公平通过且不死锁；几十名工人访问共同建筑不堆叠；拥堵时无大规模重复寻路尖峰；提供道路、路口/窄口、共同目标和几十单位压力场景供用户实际体验。分类：玩法/城镇交通；架构/单位移动；性能/拥堵与寻路。关联任务：TS-028、TS-029、TS-030；决策记录：实施时扩展 map-build-temp-01/temp-02/docs/decisions/adr_001_unit_movement.md。', 'claimed', 100, 'sasaki', 'codex_local_multiselect', NULL, '8d5e71a12d127493b748f89e8ca6d1867dad899894c2d3b34b019006b6561f27', 0, 'task/TS-045-town-traffic', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, '2026-09-08 01:01:17', '2026-09-23 03:29:29'),
  ('TS-046', 1, '正式哥布林怪物与窝点素材接入', '用户反馈（2026-09-09）：当前怪物与窝点仍使用临时深红战士和黑色兵营，应改用素材引用项目已经索引的 Tiny Swords (Update 010)/Factions/Goblins 正式资源。素材证据：asset-index ID 485 Torch_Red.png（1344x960）及 ID 484 Aseprite 源文件用于怪物 idle/run/attack 等动画；ID 452 Goblin_House.png（128x192）作为基础窝点；ID 460 Wood_Tower_Red.png（1024x192，四帧图集）保留为强化窝点/塔的候选，不直接按静态整图显示。实施时复制所需资源到 temp-02/res://assets/enemies/goblins/，建立明确帧表和 SpriteFrames，移除临时 tint 与黑色兵营依赖；保持现有怪物数值、寻路、战斗组和三轮生成契约。验收：游戏内怪物为真实红色哥布林火炬兵并正常播放待机/跑动/攻击；三个窝点显示哥布林建筑且透明区域、Y排序、碰撞和出怪点正确；素材来源和索引 ID 可追踪。分类：美术接入/敌人视觉。决策：temp-02/docs/decisions/adr_017_goblin_assets_distance_and_health_feedback.md。仅登记，待确认后按任务流程认领。', 'done', 100, 'codex-ts046', 'codex_ts046', NULL, NULL, 0, NULL, 'beead01eba02b059dc7bde7aaa6568cf9c6cede3', 'Godot 4.7.2：test_monster_assault_integration、test_monster_wave_controller、test_troop_combat、test_unit_production_integration、test_visual_occlusion、test_unit_purchase 均退出码0且日志无ERROR/FAIL；render_monster_preview 使用OpenGL Compatibility成功生成并人工检查待机/攻击截图。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-09 02:18:26', '2026-09-09 02:18:26'),
  ('TS-047', 1, '南部战场扩展、窝点远移与首轮准备时间调整', '用户反馈（2026-09-09）：当前怪物窝点离主城过近，需要向地图下方移动几个屏幕框，为生产和布防留出更充足空间；第一波准备阶段也需适当拉长。规划目标：向南扩展可行走地图约 3 个 1152x648 基准视口高度，三个窝点基线放在主城下方约 2.5至3个视口高度处，并保留中间连续可通行战场；相机边界、小地图覆盖、寻路 bounds、障碍和建筑放置边界同步扩展。第一波准备时间暂以 60 秒为候选值（当前 20 秒），后续 45 秒轮次间隔和每轮27只总契约不在本任务默认改动；用户原话中的“第一波稍微拉长”语义和精确秒数须在开工前再次确认。需与正在占用移动/寻路范围的 TS-045 协调，禁止在冲突未解决时认领。验收：主城与最近窝点之间至少保留约2.5屏纵向准备区；三窝点均在地图内、彼此分离且出怪点可行走；相机和小地图能完整抵达/显示新南部区域；27只怪物均可找到主城路径；首轮倒计时显示确认后的新时长。分类：地图/波次节奏。决策：temp-02/docs/decisions/adr_017_goblin_assets_distance_and_health_feedback.md。仅登记，待确认后按任务流程认领。', 'done', 100, 'codex-ts046', 'codex_ts046', NULL, NULL, 0, NULL, '9ee8b26c80864e35275bf1de08a595bfd7b199c8', 'Godot 4.7.2：test_monster_assault_integration 验证三窝点距主城至少1296px、地图南扩至少三屏、27只怪物可生成并向主城移动；test_monster_wave_controller 验证首轮60秒及三轮27只；test_camera_safe_bounds 验证扩展后相机/小地图边界；另有 troop_combat、visual_occlusion、unit_purchase 回归，全部退出码0且日志无ERROR/FAIL。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-09 02:20:08', '2026-09-09 02:20:08'),
  ('TS-048', 1, '主城与战斗单位受击反馈及条件血条', '用户反馈（2026-09-09）：主城和战斗单位受击缺少直观反馈与血量展示。规划：玩家兵种与怪物头顶增加世界空间血条；满血默认隐藏，首次受伤立即显示并实时更新，治疗恢复满血后再次隐藏，死亡随单位清理；主城作为核心目标显示生命数值/血条并与现有1500生命和失败状态同步。有效伤害触发短促受击闪色或回弹，反馈不得修改碰撞、寻路、攻击结算或Y排序；连续攻击时避免重复 Tween 累积和颜色残留。验收：满血小兵无血条；受击同帧出现且比例准确；治疗至满血隐藏；玩家兵种和哥布林行为一致；主城受击能看到生命下降，归零显示主城失守；对象释放后无残留 UI/RID。增加逻辑专项和真实渲染对比。分类：战斗交互/生命UI。决策：temp-02/docs/decisions/adr_017_goblin_assets_distance_and_health_feedback.md。仅登记，待确认后按任务流程认领。', 'done', 100, 'codex-ts046', 'codex_ts046', NULL, NULL, 0, NULL, '9ee8b26c80864e35275bf1de08a595bfd7b199c8', 'Godot 4.7.2：test_monster_assault_integration、test_monster_wave_controller、test_camera_safe_bounds、test_troop_combat、test_visual_occlusion、test_unit_purchase 均退出码0且日志无ERROR/FAIL；OpenGL Compatibility真实渲染确认条件血条、主城常驻血条和HUD生命数值。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-09 02:18:04', '2026-09-09 02:18:04'),
  ('TS-049', 1, '非工人战斗单位沿途索敌与临时交战', '用户需求（2026-09-09）：第一版本为所有非工人战斗单位增加索敌距离与沿途自动交战能力，覆盖当前玩家兵种和野怪，工人明确排除。单位在移动、进攻或执行既有目标期间持续检查索敌范围内的有效敌对战斗单位；例如野怪原本以主城等建筑为进攻目的地，途中发现玩家兵种后应暂停原行军，转而接近并攻击该兵种。临时目标死亡、失效或脱离允许追击范围后，单位恢复原始命令或原建筑目标，不能永久丢失波次进攻目标，也不能在多个候选间逐帧抖动切换。第一版本不增加‘特定新兵种始终优先建筑’的单位级优先级配置，该能力留待后续独立规划；工人仍沿用现有生产与采集逻辑，不参与自动索敌。索敌半径、检查频率、目标锁定与脱离距离应集中为可调战斗参数，具体默认距离在实施前结合近战/远程攻击距离和实际地图比例确认。验收：玩家当前各战斗兵种会主动攻击进入索敌范围的野怪；进攻建筑途中的野怪会停下攻击进入索敌范围的玩家兵种；范围外敌人不会无条件拉走单位；临时交战结束后恢复原目标；工人行为不变；多人混战下目标稳定且无明显全量扫描性能尖峰。分类：玩法/战斗AI与目标选择；性能/索敌查询。关联：ADR-014、ADR-016、TS-045、TS-048。决策记录：实施时新建 temp-02/docs/decisions/adr_018_combat_target_acquisition.md。仅登记，不认领、不实施。', 'done', 100, 'codex-ts049', 'codex_ts049', NULL, NULL, 0, NULL, 'fa9bf07b5b330bca0993c473e45dfea78e66e263', 'PASS Godot 4.7.2: test_troop_combat, test_monster_assault_integration, test_monster_wave_controller, test_unit_production_integration, test_unit_purchase, test_direct_commands and test_sheep_flock all 0 failures, git diff --check passed. Existing unrelated baseline failures remain: worker_collisions 1, mining_cycle 10, food_jobs 8, wood_jobs 9, game_hud existing title/BodyScroll failure and hang. Headless environment cannot write user logs/editor settings and reports existing exit-time RID leaks.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 03:32:32', '2026-09-11 03:32:32'),
  ('TS-050', 1, '建筑世界血条移至顶部并按受伤状态显隐', '用户需求（2026-09-09）：所有具有生命值的建筑，其世界空间血条放在建筑视觉上方；满血时默认隐藏，生命低于最大值时立即显示，恢复满血后再次隐藏。现有主城血条需取消 always_visible，并由城门下方迁移至建筑顶部；运行时房屋、兵营、箭塔、靶场等建筑应复用同一显隐规则和 PM visual.health_bar_offset_y / health_bar_width 配置，不用硬编码一个偏移覆盖不同尺寸。顶部 HUD 中的主城生命数值属于情报展示，本任务默认保留，不等同世界血条。需建立统一的建筑当前/最大生命同步入口，为后续修缮复用；不在本任务增加修缮按钮、木材扣费或新的怪物目标优先级。验收：满血主城和已完工建筑不显示世界血条；受到有效伤害同帧在建筑顶部显示且比例准确；恢复满血隐藏；血条不被建筑贴图遮挡、不跟随错误节点漂移；建筑销毁后无残留 UI。分类：交互/建筑生命反馈；架构/建筑生命状态。关联：TS-048、TS-051。决策记录：实施时新建 temp-02/docs/decisions/adr_019_building_health_and_repair.md。仅登记，不认领、不实施。', 'done', 100, 'codex-ts050', 'codex_ts050', NULL, NULL, 0, NULL, 'c65f57d4bdc1cd4196783d9de53167dafe6b1bb0', 'PASS Godot 4.7.2: test_monster_assault_integration, test_unit_purchase, test_runtime_building_collision, test_visual_occlusion all 0 failures; test_troop_combat and test_monster_wave_controller exit 0; real renderer preview verified castle top conditional health bar. Existing sandbox user-log/root-CA and exit RID warnings remain.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 04:53:39', '2026-09-11 04:53:39'),
  ('TS-051', 1, '工人修缮受损建筑与木材成本结算', '用户于 2026-09-09 确认修缮规则：必须先选中一名空闲工人，再选择仍存活且生命未满的建筑，右侧命令栏才显示可执行‘修缮’入口；满血或已销毁建筑不能修缮、不能扣费。工人到达建筑接近点后使用锤子持续敲打。修缮进度直接采用建筑当前生命百分比，不建立独立完成倒计时；满损建筑基础修缮时间暂定 10 秒，恢复速率按最大生命换算。修缮期间建筑继续正常受击，伤害实时降低生命与显示进度，但不自动中断工人的修缮任务。木材按实际恢复生命持续结算，累计公式为 ceil(建筑建造木材成本 × 实际恢复生命 / 最大生命)，因此修缮期间新增伤害不会被免费恢复；木材不足时不得透支，未开始时拒绝派工，进行中不足时暂停并明确提示。建筑受损后优先接入项目已有着火/烟雾动画素材，默认按生命阈值呈现轻重受损层级，满血后关闭特效、恢复完整建筑外观并隐藏血条。建筑或工人失效时停止任务，不重复扣费。复用 TS-050 的统一建筑生命状态，不扩展怪物目标优先级。实施涉及工人移动与建筑接近点，须与 TS-045 协调；TS-050 已交付 review，认领时按任务工作流处理依赖与范围。验收覆盖选人再选建筑、入口显隐、到达与锤击动画、按生命百分比修复、受击并行、逐步木材结算、资源不足、火焰/烟雾显隐、完成回满、对象失效和多目标竞争。分类：玩法/建筑修缮；经济/木材结算；交互/建筑命令。依赖：TS-050；关联：TS-045、BUILD-007～009。决策记录：扩展 temp-02/docs/decisions/adr_019_building_health_and_repair.md。规则已确认，可进入范围协调与认领。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'f940859bb154436af7e242cba99418cbbef72286', 'test_building_repair.gd 14/14 pass; test_cheat_spawn.gd 19/19 pass; monster assault regression 0 failures', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 04:52:57', '2026-09-12 04:52:57'),
  ('TS-052', 1, '战斗兵种属性配置与科技成长接口', '用户于 2026-09-09 确认战斗配置与科技方向。第一阶段让 soldier、archer、priest、spearman 的最大生命、攻击或治疗强度、攻击间隔、攻击距离、索敌距离、脱离距离和移动速度采用‘代码默认值 + 有效 TinySwordsPM 配置覆盖’，缺失或损坏配置安全回退，工人排除。第二阶段建立数据驱动的百分比倍率科技；科技对全军中符合适用兵种标签的所有单位生效，同时更新已经生产和之后新训练的单位，但不同科技不跨兵种误加：箭术类只作用全部 archer，甲胄类只作用全部 soldier，牧师强化只作用全部 priest；spearman 预留独立适用标签。首版预设均为一次性购买：箭术使弓手伤害 +10%，甲胄使战士防御 +10%，圣愈使牧师回复量 +10%；具体费用与倍率由配置承载，先取与当前经济节奏相符的保守默认值，整体测试验收时再调整。重复购买不得重复叠加。攻速、防御 Buff、持续回血等持续效果只预留结构，不在首版启用，后期单独规划。TS-049 已交付 review 且涉及相同 troop/config 文件，认领时必须按任务工作流协调范围，不覆盖其索敌实现。验收覆盖 PM 覆盖与无效值回退、兵种标签隔离、百分比倍率、现有/新兵同步、一次性购买保护、弓手伤害/战士防御/牧师回复实效及存量默认行为不变。分类：架构/战斗配置；玩法/军事科技成长。关联：TS-002、TS-013、TS-049、ADR-010、ADR-018。决策记录：实施时新建 temp-02/docs/decisions/adr_023_combat_stats_and_technology.md。规则已确认，可进入范围协调与认领。', 'done', 100, 'codex-unit-evolution', 'codex_unit_evolution', NULL, NULL, 0, NULL, 'e04341f393d043a4bc802f75c4a8c367fe3516aa', 'PASS: TS-052 Godot test_combat_technology (18 checks), test_technology_tree, test_troop_combat, test_unit_purchase RESULT 0 failures after rebasing by cherry-pick onto latest main. PM config commit 584e3e5: test_combat_config 5/5 and node --check web/app.js pass. PM full suite 81/82 with pre-existing building_0004 rally_radius expected 96 vs accepted config 200. Required resource regressions unchanged: sheep 43/0; existing worker collision 1, mining 10, food 8, wood 9 failures. Git diff checks passed; Godot environment still reports existing user log/root certificate/RID exit warnings.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 14:06:07', '2026-09-12 14:06:07'),
  ('TS-053', 1, '怪物攻击运行时建筑与波次参数管理', '用户追加需求（2026-09-09）：兵营、靶场、房屋、箭塔等运行时玩家建筑不仅要初始化生命，还必须能被进攻中的怪物发现、锁定、接近并攻击；建筑受击统一扣减 TS-050 的 health/max_health，受损显示顶部血条，归零清理建筑、碰撞、血条与生产队列，怪物随后恢复原主城目标。工人和中立资源点不作为怪物建筑目标。怪物仍可在沿途临时攻击进入索敌范围的玩家战斗单位，单位与建筑候选按距离稳定选择。另将总波数、每窝每波数量、首轮等待秒数、轮间等待秒数、同波出怪间隔纳入 TinySwordsPM 项目配置页面、项目快照和 Godot 有效配置读取；缺失或损坏值回退现有 3波/每窝3只/60秒/45秒/0.6秒。验收覆盖运行时建筑受击与销毁、血条同步、生产退款/导航清理、交战后恢复攻城，以及 PM 编辑字段、快照导出、Godot 读取和无效值回退。分类：玩法/怪物建筑目标；架构/波次配置；工具/项目参数管理。关联：TS-049、TS-050、TS-051、ADR-016、ADR-018、ADR-019。决策记录：更新 temp-02/docs/decisions/adr_019_building_health_and_repair.md，并新增 temp-02/docs/decisions/adr_020_monster_wave_configuration.md。', 'done', 100, 'codex-ts050', 'codex_ts050', NULL, NULL, 0, NULL, '68656246ecfe2e8fd50040dccc3a28456d481437', 'Godot TS-053: test_unit_purchase 0 failures; test_monster_wave_controller 0 failures; assault/troop/runtime-collision/occlusion/production regressions passed. Resource regressions unchanged from accepted baseline. PM: monster-wave tests 5/5, node syntax and server check passed; full suite 76/77 with pre-existing building_0004 rally_radius 200 vs legacy test expected 96.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 07:25:25', '2026-09-12 07:25:25'),
  ('TS-054', 1, '战士战斗 MVP：独立地图与战斗基础', '用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段1/5。独立平铺测试地图，通过 F6 运行，不改变正式地图/启动场景。1名战士、5只共用模板且固定原地反击的小怪。左键选中，右键地面移动，右键怪物靠近持续攻击，新指令打断旧任务。双方伤害 max(1,攻击-防御)，无随机。战士死亡显示重新挑战，重置全部角色和本局；清怪显示挑战完成及重试。头顶血条。验收完整胜败重试、距离/取消/单次死亡、UI输入拦截及现有资源回归。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。', 'done', 100, 'codex-warrior-mvp', 'codex_warrior_mvp', NULL, NULL, 0, NULL, '3c4d51132b00336bc581f77d60ee50c0a141c7e5', 'Implementation 5c06f7d50ce03ceb4d5e36baac98a7b61e7f0c47. Godot 4.7.2 import exit0; MVP32 checks0 failures incl viewport input, movement, stationary retaliation, win/death/retry; OpenGL screenshot inspected; diff-check PASS. Unmodified same-commit baseline matches: collisions1/mining10/food8/wood9 failures; HUD missing BodyScroll and35s timeout. Sheep43 assertions0 failures, technology/purchase/troop-combat exit0. Some old suites report DummyRenderer RID leaks; not all-regressions-pass. See docs/warrior_mvp.md. Await user stage1 acceptance; TS-055..058 not started.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-09 08:25:34', '2026-09-09 08:25:34'),
  ('TS-055', 1, '战士战斗 MVP：经验等级与属性成长', '用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段2/5。依赖阶段1验收。击杀一次结算怪物经验，命中不加；上限3级，5怪经验使1级升至3级；逐级经验表递增、保留溢出、满级提示。生命/攻击/防御/攻击间隔/移动速度/每秒回复支持基础与等级成长及上下限。升级只补生命上限增量，持续回血包括战斗、不超上限。单选右栏显示等级经验及六属性，升级提示。不做跨局存档，重试重置。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-054，仅前置验收后开工。', 'done', 100, 'codex-warrior-mvp', 'codex_warrior_mvp', NULL, NULL, 0, NULL, 'fb834ddba22cb2f5aa66b158359b83f79e8698fe', 'Implementation0f725470f90842ca41dc4f79bed08c7b8b12e275. Godot4.7.2 import exit0; growth37 and MVP32 checks all pass including actual speed/damage/interval, regen/pause, XP/cap/retry. OpenGL1152x648 and864x486 screenshots inspected. Post-merge6865624 retest: same69 pass; sheep/technology/purchase/troop/wave assertions pass. Existing failures retained collisions1/mining10/food8/wood9; HUD BodyScroll null35s timeout; old RID leaks and wave resource-exit warning. diff-check pass. See docs/warrior_mvp.md. Await stage2 acceptance; stage3 not started.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 07:56:14', '2026-09-12 07:56:14'),
  ('TS-056', 1, '战士战斗 MVP：编辑器右侧成长插件', '用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段3/5。依赖阶段2验收。Godot编辑器右侧停靠面板，运行前配置，保存后运行生效。三页：战士六属性及等级预览；等级上限与严格递增经验梯度；小怪生命攻击防御攻击间隔攻击范围击杀经验，5怪共模板。校验、保存、放弃未保存修改；配置长期保留，停用插件游戏仍运行。独立MVP配置，不覆盖PM基础参数；TS-052正式兵种整合另行协调。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-055，仅前置验收后开工。', 'done', 100, 'codex-warrior-mvp', 'codex_warrior_mvp', NULL, NULL, 0, NULL, 'd9c567e11363509ee7f360bf13977a8b40680c33', 'Code8a3bf45e790b894f10bf3506e85561f6866647d1. Godot4.7.2 editor plugin import exit0 noERROR. Dock23+growth37+MVP32 checks all pass (92), including real controls, atomic replace, external-edit rejection and runtime consumption. Three tabs and320px dock rendered/inspected. Existing regressions unchanged: collisions1/mining10/food8/wood9 failures, HUD BodyScroll error35s timeout; sheep/technology/purchase/troop assertions pass with old RID leaks. diff-check pass. TS-055 remains review under user deferral; TS-056 also awaits acceptance. See addons/warrior_growth/README.md.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 07:57:54', '2026-09-12 07:57:54'),
  ('TS-057', 1, '战士战斗 MVP：剧情与新手引导', '用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段4/5。依赖阶段3验收。开场对白→选择战士→移动→攻击小怪→首次升级说明→全部击杀结束对白。对白暂停移动攻击回血，继续恢复；操作目标提示不暂停。UI拦截地图输入，事件驱动推进，重复触发不重复结算，重试清理引导状态。配置和逻辑分离，不扩展经营序章。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-056，仅前置验收后开工。', 'done', 100, 'codex-warrior-mvp', 'codex_warrior_mvp', NULL, NULL, 0, NULL, 'a8d321b8b462f33181fe7cadf5c007269441770b', 'Code04cb21b4be03a309677317ee6e18075d1b945eea. Godot4.7.2 tutorial30+dock23+growth37+MVP32=122 checks pass, incl real mouse/combat, pause clocks, last-kill dialogue queue, skip/retry and zero-XP. OpenGL opening/move/upgrade/small-victory inspected. After merge6089fea initial missing global class fixed by editor import; final production-cooldown and unit-production integration pass. Existing collisions1/mining10/food8/wood9 failures and HUD35s timeout retained; old RID leaks retained. diff-check pass. Stages2-4 remain review, no automatic acceptance.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 07:59:01', '2026-09-12 07:59:01'),
  ('TS-058', 1, '战士战斗 MVP：整体回归与使用说明', '用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段5/5。依赖阶段4验收。完整胜败试玩、两次升级、配置修改生效、异常配置/连续升级/暂停恢复/重试/UI布局检查；回归碰撞采矿羊群食物伐木科技训练，区分旧失败与新增失败。交付F6路径、插件说明、配置规则、测试报告与提交号，等用户验收，不自动done。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-057，仅前置验收后开工。', 'claimed', 100, 'sasaki', NULL, NULL, '4c2f92fa23a2441c5df95c8357c2159743bb49b97ab710b6d077450c8244e89b', 0, 'task/TS-058-mvp-regression', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, '2026-09-09 07:09:24', '2026-09-23 03:29:30'),
  ('TS-059', 1, '启动器测试探针适配 restart 参数，修复打开项目解析错误', '用户报告打开MVP工程时probe_pm_launcher.gd Parse error。Godot --check-only复现第7行父类签名为(String,String,bool=false)，测试覆盖仍为两个参数。仅修复测试探针签名并转发restart，验证解析及相关隔离测试；不修改服务行为、不进入MVP第二阶段。关联TS-019、TS-034、TS-054。分类：缺陷/测试接口兼容。修复记录temp-02/docs/pm_service_launcher.md。用户此前已授权任务及代码普通提交推送，本次为第一阶段验收反馈修复。', 'done', 100, 'codex-warrior-mvp', 'codex_warrior_mvp', NULL, NULL, 0, NULL, 'a28dfe7cf1086e80464a8ec4c4865322ab1405f3', 'Godot4.7.2 probe --check-only before exit1 signature mismatch line7; after exit0 no script error. Existing test_missing_directory,test_helper_error_is_shown,test_startup_timeout:3 passed. git diff --check passed. Only probe signature and super restart forwarding changed; no actual service start/restart tests run. MVP remains stage1 review.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 08:00:39', '2026-09-12 08:00:39'),
  ('TS-060', 1, '生产按钮改为英雄联盟式径向冷却反馈', '用户于 2026-09-09 审核并确认径向冷却方案，授权登记、认领及普通推送后实施。训练队列头项生产期间，购买按钮显示覆盖完整图标的灰蓝径向冷却遮罩；每生产一个单位都按该单位自己的完整训练时间连续扫掠一圈，该单位出场后若仍有待产项目，下一单位从零开始新的一圈，不按整数秒重置，不再使用旋转鼠标指针。右上角只显示该兵种尚未生成的数量，不显示剩余时间；剩余大于 1 秒使用稳定深灰蓝遮罩，最后 1 秒降低遮罩透明度但扫掠连续不中断。冷却完成时播放约 0.3～0.45 秒金色双亮边后恢复可点击视觉。保留串行生产、资源与人口结算、阻塞出生点等待及现有命令格素材；视觉状态不能改变生产时序。需为逐单位径向进度、待产数量、末秒透明度、完成反馈和清空队列补充测试。分类：UI/生产反馈；交互/冷却状态。关联：TS-013、TS-014、TS-026。决策记录：temp-02/docs/decisions/adr_022_production_cooldown_ui.md。', 'done', 100, 'codex-ui-cooldown', 'codex_ui_cooldown', NULL, NULL, 0, NULL, '6089feaaf938eff7a0c2fda9bfffeb0d04ccbcbe', 'Godot 4.7.2: production_cooldown_ui 11/11 passed; unit_production_integration 18/18 passed; production_queue 17/17 passed; unit_purchase 0 failures; real graphical renderer previews inspected for deep and final-second overlays; git diff --check passed. Final behavior: upper-right shows per-kind pending quantity only; each unit production duration maps to one full radial circle, next queued unit restarts from zero; final second uses lighter opacity. Existing unrelated baseline failures remain: worker_collisions 1, mining/food/wood timing suites, game_hud obsolete BodyScroll assertion.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-09 13:26:13', '2026-09-09 13:26:13'),
  ('TS-061', 1, '素材库增加兵种进化前后对照', '用户于 2026-09-09 至 2026-09-10 确认：新版素材库中 Free Pack 与 Update 010 各有一套工人、弓箭手、战士素材，应登记为同兵种的基础形态与进化形态并提供升级前后对照。基础形态分别为 free/character/pawn、free/character/archer、free/character/warrior；进化形态分别为 update010/character/knights/pawn、update010/character/knights/archer、update010/character/knights/warrior。蓝、紫、红、黄可一一对应；Free Pack 独有黑色且 Update 010 无对应黑色，页面必须明确显示缺少进化变体，不得擅自改色或生成素材。素材详情增加“基础形态 → Lv.5 且对应科技完成后可进化”的关系展示，进化等级仅为可配置默认值的说明，不在素材库实现游戏逻辑。保留角色/素材组与全部文件视图，不移动、覆盖或复制原始素材。验收覆盖三组映射、四种共同颜色、黑色缺失提示、前后详情跳转、搜索筛选及现有 841 文件/102 组一致性。分类：素材管理/进化关系；UI/前后对照。关联：TS-052、TS-062。决策记录：godot-game-learn/docs/decisions/adr_002_unit_evolution_asset_pairs.md。用户已明确授权本次登记、普通提交推送及认领实施。 【验收退回 2026-09-12】用户判定验收不通过：交付提交 8e6357707e8e547e1ab2b9a8b7c19951d16d6317 不在 godot-game-learn-main 历史；8766 assets-view 仅有换色、无 Free Pack↔Update 010 形态对照/黑色缺失提示/详情跳转。退回 ready 供返工认领。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'feb1d966774a484576cf21ede7e4b466f031a573', 'ACCEPTED by user 2026-09-12. Branch task/TS-061-unit-evolution-asset-pairs @ d2f55ce44300bb99f7f989458c87d98663931a88. Await merge-to-main vs next-acceptance (ADR-035); done after main merge. Evolution UI retained as-is per independent-unit product note; Update 010 knight sheet rows named idle/run/attack1-5; UI cleanup (no duplicate row-hint bar; advanced slicer collapsed). PASS verify_asset_catalog.cjs; browser ?v=ts061-5.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:20:23', '2026-09-12 12:20:23'),
  ('TS-062', 1, '可配置等级与科技双条件单位进化', '用户于 2026-09-10 确认采用单位个体培养与科技资格共同控制进化：每个单位独立登记等级和进化状态，默认 required_level=5，可配置；同时必须完成该兵种配置的 required_technology，才将该个体从 Free Pack 基础素材替换为 Update 010 进化素材。未达到等级的单位不得因科技完成而提前进化，新生产单位仍从基础形态开始；达到等级但科技未完成时保持待进化，科技完成后立即重新判定。工人、弓箭手、战士分别配置素材组和对应科技；已有单位与新单位共用同一判定且进化只执行一次。科技继续提供按兵种限定的全军百分比增幅，个体等级与外观进化状态独立，禁止重复叠加属性。第一阶段只实现可配置判定、素材替换、运行时状态登记与测试；跨局持久化、工人劳动经验来源和死亡继承规则另行确认，不在本任务擅自扩展。依赖 TS-052 的军事科技接口与通用单位属性配置；素材映射来自 TS-061。验收覆盖阈值边界、科技先后顺序、单个单位独立进化、重复判定、三兵种素材切换、颜色映射缺失回退及新旧单位并存。分类：玩法/单位进化；配置/成长条件；视觉/素材替换。决策记录：temp-02/docs/decisions/adr_023_configurable_unit_evolution.md。用户已明确授权本次登记及普通提交推送；实施应在依赖满足且无 scope 冲突后认领。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-13 14:47:54', '2026-09-22 06:45:37'),
  ('TS-063', 1, 'MVP哥布林死亡烟尘与骷髅消散', '2026-09-10用户确认取消模拟受击停顿和位移，致命一击立即播放Dust_01烟尘遮挡哥布林，再衔接Dead骷髅消散。死亡立即关闭碰撞、仅结算一次经验；特效独立清理，覆盖升级/胜利对话和重试。仅实施死亡表现，三关与通用角色配置插件待后续确认。分类：视觉/死亡反馈。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。用户本轮明确允许登记认领及测试后代码普通提交推送；接续TS-055/057并保留待验收。', 'done', 100, 'codex-warrior-mvp', 'codex_warrior_mvp', NULL, NULL, 0, NULL, '3f15004f1210f6c138f23413a5e4c6f8985b1dfd', 'Implementation b8f3f52ed966743a4d3ee97e9af5d4954b6e1320. Godot4.7.2 import exit0; death13 + MVP32 + growth37 + dock23 + tutorial30 =135 checks passed. Real OpenGL 4-stage death frames inspected. New test initial WeakRef inference parse error fixed with explicit type; rerun13 passed. Existing resource failures unchanged: collisions1/mining10/food8/wood9; HUD missing BodyScroll timeout35s; old RID exit leaks. Sheep43 and tech/purchase/troop/production assertions passed. diff-check passed. Death cosmetic runs during dialogue pause, clears on retry/exit, immediate single XP reward; no three-stage or plugin changes. 用户 2026-09-13 确认此前验收已通过。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-13 08:40:00', '2026-09-13 08:40:00'),
  ('TS-064', 1, 'MVP三关成长循环与角色配置下拉插件', '用户确认方案并明确授予本次登记认领与普通提交推送权限。三关各5怪，刷新本关或进入下一关保留等级经验当前血量属性；安全出生点，结算不回血；第三关刷新或从第一关重置，失败重置。上限6级，经验40/60/90/130/180，怪物生命55/85/120攻击10/14/18防御1/3/5经验20/35/50。插件更名角色配置，当前编辑场景及待生成角色目录扫描、唯一ID下拉，战士与哥布林可配，未接入类型只读，未保存切换提示。分类：玩法/关卡成长；工具/角色配置。决策temp-02/docs/decisions/adr_021_warrior_mvp.md追加。接续55/56/57/63，不自动验收前序。', 'done', 100, 'codex-warrior-mvp', 'codex_warrior_mvp', NULL, NULL, 0, NULL, 'a439fb070c585f9b25b385450fa94e04efa2b14c', 'Implementation6c9b43c77c6e550ee4bff8a88d3b8c59e1f348f8. Godot4.7.2 campaign39+character15+death13+combat32+growth37+dock23+tutorial30=189 checks passed. Final tier whitelist change retested campaign39 and character15 passed. Headless editor import exit0; real renderer campaign and character dock including narrow layout inspected. Full three-stage live combat reaches level6; HP/XP retained, repeat rewards, failure/reset, readonly roles and dirty switch protected. Existing regressions unchanged: collisions1/mining10/food8/wood9 failures; HUD missing BodyScroll timeout35s; old RID leaks. Other sheep/tech/purchase/troop/production assertions passed. FF synced documentation-only61e449a; diff-check passed. Await user acceptance; formal roles remain readonly as agreed.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-10 12:57:51', '2026-09-10 12:57:51'),
  ('TS-065', 1, '建筑物图层遮罩与碰撞体积优化', '用户于 2026-09-11 提出新增需求：优化建筑物的图层遮罩与碰撞体积。现状基线：TS-038 遮罩多边形作视觉遮挡（clip/Y 排序相关已迭代）、TS-039 控制台碰撞在游戏内作阻挡、TS-010 曾验收底部占地与前后遮挡。本任务聚焦观感与站位体验优化：遮罩范围/顶点与建筑贴图对齐、单位被错误裁切或踩屋顶问题；碰撞体积与真实墙脚占地一致，工人/兵种通行与停靠不被过大或错位的阻挡卡住。不擅自改动 PM 控制台编辑器交互（TS-031/035）；改碰撞/遮罩数据须经快照加载验证。待确认：优先建筑清单（城堡/房/兵营/箭塔/靶场/金矿等）、验收截图或对照标准、是否允许改 PM 默认碰撞与 mask_polygon。实施前在 temp-02/docs/decisions/ 建 ADR 并回填；更新 gameplay_interaction_rules 与 visual_occlusion/runtime_collision 相关测试。分类：玩法/建筑视觉与碰撞；关联 TS-010、TS-038、TS-039。仅登记待确认，不认领不实施。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-14 01:45:33', '2026-09-22 06:45:37'),
  ('TS-066', 1, '建筑物受击燃烧效果优化', '用户于 2026-09-11 提出新增需求：优化建筑物受击后的燃烧效果。现状基线：TS-051 修缮链路中 `_update_building_damage_fx` 按生命比例切换 Fire_01/Fire_02 静态贴图；满血移除、重伤加深透明度；城堡与 runtime 建筑位置偏移不同。本任务仅优化燃烧表现（动画/层级/贴合建筑/轻重档过渡），不改生命结算、修缮扣木、怪物索敌与血条规则。范围协调：TS-051（sasaki，claimed：building_repair 等）交付或交接前勿改同一修缮主路径；本任务 scope 独立为 building_damage_fire_fx，认领前须确认与 TS-051 无文件冲突。待确认：期望素材（现有 Fire 帧动画或 Particle）、是否跟随生命阈值动画、是否含主城与全部可修缮建筑、可接受的 z/Y 排序表现。实施前扩展 adr_019 或新建 ADR；补充燃烧显隐与层级专项/真实渲染对照。分类：视觉/建筑受损反馈；关联 TS-050、TS-051、TS-053。仅登记待确认，不认领不实施。', 'ready', 100, NULL, 'codex_ts066', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-14 02:21:50', '2026-09-22 06:45:37'),
  ('TS-067', 2, 'map-build 接入 TinySwordsPM（项目维度 + 插件扫描基线）', '在 TinySwordsPM 登记 project_0002/key=map-build；Godot 工程启用 tiny_swords_pm 插件（PROJECT_KEY=map-build）；能扫描 reference_valley 并写入 data/tiny_swords_pm.json 快照。不改玩法逻辑。验收：管理页可见该项目与任务；编辑器扫描/拉取成功。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '93121518d4bbb7e23b1c188f96e0a4c8f302157b', 'PASS: python tools/validate_pm_bridge.py --start-server (scan entities=532 resources=10, pull project_0002/map-build snapshot, tasks TS-067..077 visible); PASS: Godot 4.7.2 headless --script res://tools/validate_pm_bridge_godot.gd prints TS067_PM_BRIDGE_OK; plugin enabled in project.godot with PROJECT_KEY=map-build; no gameplay/map overwrite. Mount unmatched_count=10 expected until asset catalog alignment (TS-070).', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 08:28:47', '2026-09-11 08:28:47'),
  ('TS-068', 2, '道路与桥梁可行走区域生成', '从 Terrain_基础地形 识别 custom_data=road 的黄色道路格，以及 Bridges_桥梁 下桥面 TileMap（custom_data=bridge），生成可行走 mask / Navigation 或等效碰撞数据。输出可重复运行的 tools 脚本，不覆盖用户已保存摆放。验收：主路与两座桥面可查询为可行走；报告格数。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '97bb1a485c71751a30fd53446bbb1d36abc99f76', 'PASS: Godot 4.7.2 headless tools/build_walkability_roads.gd -> WALKABILITY_ROADS_OK roads=473 bridges=2 deck_cells=18 walkable_union=487 (road+bridge overlap=4); PASS: --validate-only roundtrip WALKABILITY_ROADS_VALIDATE_OK; outputs data/maps/reference_valley_walkability.json and previews/reference_valley_walkability_mask.png; reference_valley.tscn unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 08:30:49', '2026-09-11 08:30:49'),
  ('TS-069', 2, '水体与岩壁不可走阻挡层', '基于同一基础地形层将水面、岩壁（及必要时越界外区）标为不可走，与 TS-068 道路/桥面合并为完整通行图。禁止多层覆盖伪造阻挡。验收：水中/立面不可走，道路与桥头连通；有校验报告。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '8ad54aca43fec5eb97e9577311b1da1c87c8dc7e', 'PASS: Godot 4.7.2 headless tools/build_terrain_blockers.gd -> TERRAIN_BLOCKERS_OK water=472 cliff=127 empty=0 path=487 surface=2514; PASS: --validate-only TERRAIN_BLOCKERS_VALIDATE_OK; outputs data/maps/reference_valley_passability.json and preview mask; reference_valley.tscn unchanged; depends on TS-068 walkability json.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 09:12:32', '2026-09-11 09:12:32'),
  ('TS-070', 2, '场景物件统一注册表（建筑/资源类型）', '为 WorldObjects 下 Buildings/Towers/Mines/Outposts/GoldRocks/Trees 建立类型级注册表（id、asset_name、交互类型 harvest/obstacle/attackable、默认碰撞与采集点偏移）。以 map-build data JSON 为主建立类型注册表；不改 temp-02/PM 战斗配置 scope。场景实例只引用 registry_id。验收：可枚举类型与实例数量，金矿48/建筑分组可对账。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '42ab2611c314c511bbadedb649b602e99123f3f8', 'PASS: Godot 4.7.2 headless tools/build_object_registry.gd -> OBJECT_REGISTRY_OK types=16 instances=513 gold=48 buildings=15 trees=412 towers=19 mines=8 outposts=11; PASS: --validate-only; outputs data/maps/reference_valley_object_registry.json; scene placements unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 09:14:44', '2026-09-11 09:14:44'),
  ('TS-071', 2, '可交互物件挂接碰撞与采集点', '按注册表为金矿石、树木、建筑/箭塔/矿洞/据点批量或按需挂 StaticBody2D/Area2D 与脚底排序兼容的碰撞；不破坏自由拖动编辑。验收：抽样节点有碰撞；Godot headless 可加载场景；验证工具通过。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '9e395930bb110cde5195155cae94800af76b3ff7', 'PASS: Godot 4.7.2 headless tools/validate_object_colliders.gd -> OBJECT_COLLIDERS_OK built=513 gold_sprites=48; colliders on separate ObjectCollisionLayer; sample gold Sprite2D has 0 children; reference_valley.tscn placements unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 09:16:20', '2026-09-11 09:16:20'),
  ('TS-072', 2, 'temp-02 场景适配层（WorldObjects 对接玩法控制器）', '将 temp-02 的 Main/MpObjects/Castle/GoldMineActive 假设适配到 ReferenceValley/WorldObjects_* 与选定主城/矿点绑定。控制器解耦硬编码路径；不直接覆盖 reference_valley 美术摆放。验收：适配后能定位城堡、至少一处矿点与物件分组。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '5377ec7ba5e29717f362876087cc1cf5c48000e7', 'PASS: Godot 4.7.2 headless tools/validate_valley_adapter.gd -> VALLEY_ADAPTER_OK castle+primary_mine bound, gold=48 bridges=2; writes data/maps/valley_gameplay_bindings.json; reference_valley.tscn unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 09:18:27', '2026-09-11 09:18:27'),
  ('TS-073', 2, '工人角色系统移植', '从 temp-02 移植 worker 场景/脚本与基础寻路（可见性图或 A*），接入 TS-068/069 通行数据与 TS-071 资源节点。先打通移动+采金/伐木闭环中的最小路径。验收：至少 1 名工人可在道路上移动并完成一次资源交互或明确桩测试。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '4a916cf27c87a20a99e4210c3c5ebe38788f2e5c', 'PASS: Godot 4.7.2 headless tools/validate_valley_worker.gd -> VALLEY_WORKER_OK frames=595 path from deposit to primary mine on passability grid; uses TS-069/TS-072 outputs; reference_valley.tscn unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 09:21:52', '2026-09-11 09:21:52'),
  ('TS-074', 2, '建筑系统移植（建造/人口/训练入口）', '移植房屋/兵营/箭塔/箭场等运行时建造与人口上限逻辑；绑定地图已有建筑原型。依赖 TS-072/073。验收：可放置或识别至少一类建筑完工效果（人口或训练入口之一）。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'd9451a5a1237296d500321836027a50173fc58e2', 'PASS: Godot 4.7.2 headless tools/validate_valley_buildings.gd -> VALLEY_BUILDINGS_OK linked=13 cap 10->15 training=3; house placement applies +5 population; barracks exposes soldier train_unit; reference_valley.tscn art unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 10:26:49', '2026-09-11 10:26:49'),
  ('TS-075', 2, 'HUD 与资源栏接入大地图', '接入 temp-02 HUD/小地图到 reference_valley 尺度与镜头；资源与人口显示正确。验收：F6 运行可见资源栏；镜头可浏览整图关键区域。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '3d81588107950e590e2e0894c5a630130b825a6d', 'PASS: Godot 4.7.2 headless tools/validate_valley_hud.gd -> VALLEY_HUD_OK gold/pop labels update after house placement; gameplay camera focuses deposit point; map preview camera disabled; reference_valley art unchanged.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 10:33:29', '2026-09-11 10:33:29'),
  ('TS-076', 2, '大地图寻路与障碍性能优化', '针对 80x45 格与 500+ 物件优化障碍刷新与寻路；必要时空间划分。验收：多工人同时寻路无明显卡顿的可测指标或 profiler 记录。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'ea2902ad920924a31b5c255e85c825d952140a17', 'PASS: Godot 4.7.2 headless tools/validate_pathfinding_perf.gd -> PATHFINDING_PERF_OK 96 queries avg~1.3ms (<5ms budget) on 80x45 walkable=3001; adds scripts/maps/passability_grid.gd.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 10:37:48', '2026-09-11 10:37:48'),
  ('TS-077', 2, '战斗 MVP 移植（兵种/受击/建筑血量）', '从 temp-02 _combat_mvp_work 移植最小战斗：兵种移动攻击、建筑生命/受损反馈。排在经济闭环之后。验收：可训练或生成单位并完成一次交战或建筑掉血演示。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'f0e7c20cf1664be5e496527d41f06355f08e2faa', 'PASS: Godot 4.7.2 headless tools/validate_valley_combat.gd -> VALLEY_COMBAT_OK troop damages house health below 100 with damaged flag; frames simulated without rewriting reference_valley art.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 11:28:03', '2026-09-11 11:28:03'),
  ('TS-078', 1, '出兵通道闲置让路与停驻（ADR-024 兵种侧）', '用户于 2026-09-11 确认廊带通用方案并授权登记、认领推进本出兵侧任务。方案摘自 temp-02/docs/decisions/adr_024_transport_corridor_yield_stay.md（用户 2026-09-11 确认）。通用原则：对稳定高频通道建立运输廊带（带宽约 1～2 脚底直径，不硬锁整条折线像素）；路过可穿廊；闲置不得长期占廊心；被要求让路的闲置单位移动到廊外安全点后默认停驻新点、不自动回原点；带货/出场优先于空闲赶路。不取消局部避让与物理碰撞；不为每次任意右键临时路建永久廊带。资源场景：矿/树/羊等固定线路注册廊带，回城带货共用廊权，门口闲置/排队不得占廊心。出兵场景：(a) 避让——单位出场需要通道时，廊上闲置兵必须让路；(b) 停驻——让路后停在新点便于后续继续出兵。验收后若调参，以本任务描述与 ADR-024 为准追加变更，不覆盖历史结论。 本任务范围：城堡/兵营/靶场生产出场通道的廊带声明；闲置战斗单位让路；让路后更新停驻点不回原占道点；不改资源工人全局寻路图重建策略，不放开物理穿透。可与资源侧任务并行；共享廊带/让路停驻接口时先合接口再分场景。分类：架构/单位移动；玩法/出兵集结与通道。决策：ADR-024。注意：不占用 TS-045 的 town_traffic/worker_navigation/bottleneck_routing 范围标签；若实现触及工人导航核心须与 TS-045（claimed:codex_local_multiselect）协调。 并行关联：TS-079。', 'claimed', 100, 'codex-ts078', 'sasaki', NULL, 'b7f4158ca7acf96f51d922198ab8695740c0928842f1bb95df08a19c6fe4b33a', 0, 'task/TS-078-troop-exit-corridor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, '2026-09-11 08:28:28', '2026-09-23 04:15:47'),
  ('TS-079', 1, '资源运输廊带与闲置清场（ADR-024 工人侧）', '用户于 2026-09-11 确认廊带通用方案并授权登记本资源侧任务。方案摘自 temp-02/docs/decisions/adr_024_transport_corridor_yield_stay.md（用户 2026-09-11 确认）。通用原则：对稳定高频通道建立运输廊带（带宽约 1～2 脚底直径，不硬锁整条折线像素）；路过可穿廊；闲置不得长期占廊心；被要求让路的闲置单位移动到廊外安全点后默认停驻新点、不自动回原点；带货/出场优先于空闲赶路。不取消局部避让与物理碰撞；不为每次任意右键临时路建永久廊带。资源场景：矿/树/羊等固定线路注册廊带，回城带货共用廊权，门口闲置/排队不得占廊心。出兵场景：(a) 避让——单位出场需要通道时，廊上闲置兵必须让路；(b) 停驻——让路后停在新点便于后续继续出兵。验收后若调参，以本任务描述与 ADR-024 为准追加变更，不覆盖历史结论。 本任务范围：矿口↔城堡交付、树区/羊群等高频资源线廊带注册；闲置/等待工人清出廊心并停驻廊外；带货回城优先穿廊。实施前必须与 TS-045（城镇道路拥堵，claimed:codex_local_multiselect，scope含 town_traffic/worker_navigation/bottleneck_routing）协调，避免重复开发同一通行层；本任务 scope 标签刻意与 TS-045 分离，但代码入口可能相邻，认领前再 sync 确认。分类：架构/单位移动；玩法/资源交付通道。决策：ADR-024。关联出兵侧并行任务。 并行关联：TS-078。', 'claimed', 100, 'sasaki', 'sasaki', NULL, '49bc1f38fd36c6cc89ef0e601b209266570d14b92972b0115bf9d411c4f63a28', 0, 'task/TS-079-resource-corridor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, '2026-09-11 08:28:40', '2026-09-23 03:29:30'),
  ('TS-080', 1, '弓箭手进入箭塔驻守防御并提升攻击距离', '用户于 2026-09-11 提出并授权登记、认领与实现：弓箭手可进入已完工箭塔在塔上防御，并获得攻击距离加成。交互：选中弓箭手后右键存活箭塔派驻；每塔容量 1；驻守时单位站在塔顶可见、关闭碰撞、不离塔追击，仅在加成射程内攻击；右键地面令驻守弓箭手安全下塔再移动；箭塔被摧毁时强制下塔并恢复基础射程。非弓箭手右键箭塔仍按原移动/修缮逻辑。验收：进塔/满员拒绝或等待、射程加成、下塔移动、塔毁弹出、选中与 HUD 状态正确；新增 headless 测试并回归 troop_combat。分类：玩法/建筑驻守与远程防御。决策记录：temp-02/docs/decisions/adr_025_archer_tower_garrison.md；规则写入 docs/gameplay_interaction_rules.md。关联 UNIT-001/005、BUILDING-HEALTH-002、TS-026/039/051。scope 刻意避开 building_repair / combat_unit_stats_config / monster_building_targeting / troop_exit_corridor。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '544859c01802791802b1eb6edb2486bc6e4998cd', 'PASS Godot 4.7.2 headless: test_tower_garrison, test_troop_combat, test_training_dummy (exit 0). User F6 acceptance: tower range ring, manual-move priority, arrow release-frame parabola, training dummy.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 04:26:33', '2026-09-12 04:26:33'),
  ('TS-081', 2, '金矿采集交付闭环', '在 map-build 工人桩上接入采金→抱金→城堡交付→自动返矿的最小闭环；交付时增加 BuildingSystem/会话金币。不覆盖 reference_valley 摆放。验收：headless 完成至少一趟入库且可自动开始第二趟。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '34eccff9299b9862a22397d5bf3579a091591477', 'PASS: Godot 4.7.2 headless tools/validate_valley_mining_cycle.gd -> VALLEY_MINING_CYCLE_OK gold 1000->1010 trips=1; regression validate_valley_worker.gd VALLEY_WORKER_OK.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 11:39:12', '2026-09-11 11:39:12'),
  ('TS-082', 2, '山谷玩法会话启动（bootstrap 可运行）', '为 valley_gameplay_bootstrap 挂会话控制器：自动 adapter.bind、buildings.setup、注册建筑、HUD、生成至少 1 工人。F6/主场景可直接运行，不依赖 validate 脚本拼装。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '2685e5a3a43c3e5a5d53285aa1fd554e862070ac', 'PASS: Godot 4.7.2 headless tools/validate_valley_session.gd -> VALLEY_SESSION_OK workers=1 linked=13 gold 1000->1010; regressions mining_cycle/combat/hud OK.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 11:47:00', '2026-09-11 11:47:00'),
  ('TS-083', 2, '工人点选与采矿命令', '左键选中工人，右键主矿/矿口发出采矿命令；HUD 显示选中/采矿状态。未选中不派工。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '1040d5266e1ea4f7c54ba66065d0f2dc14760c68', 'PASS: Godot 4.7.2 headless tools/validate_valley_selection.gd -> VALLEY_SELECTION_OK unselected rejected, select+mine deposits gold; session/mining regressions OK.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 11:48:23', '2026-09-11 11:48:23'),
  ('TS-084', 2, '城堡召唤工人（扣费/人口）', '按快照 economy.train.worker 扣金、预占人口、倒计时后在 deposit_point 附近生成可采矿工人；资源/人口不足拒绝且库存不变。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '7977fdc97ece5eeffecb627af706a4bdc4585c91', 'PASS: Godot 4.7.2 headless tools/validate_valley_train_worker.gd -> VALLEY_TRAIN_WORKER_OK workers 1->2 gold_spent=50; unaffordable rejected; selection/session regressions OK.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 11:49:55', '2026-09-11 11:49:55'),
  ('TS-085', 2, '树木砍伐入库', '工人对 Trees_树木 完成砍伐→抱木→城堡交付，wood 增加；至少 1 棵树可耗尽；库存足以支撑一次 place_building(house) 扣木。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '1f0f163772aef1fc910df4060e6df9ef3f2c8d62', 'PASS: Godot 4.7.2 headless tools/validate_valley_wood_harvest.gd -> VALLEY_WOOD_HARVEST_OK wood_trips=2 house_cost=80 tree depleted; selection regression OK.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 11:55:54', '2026-09-11 11:55:54'),
  ('TS-086', 2, '兵营扣费出兵', '选中兵营按 train.warrior/兵种配置扣金生成 valley_troop；可对建筑 meta 造成伤害；资源不足不生成。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'dbf5e326f6a5c8a12c90960868e3c0b3fdba5cc9', 'PASS: Godot 4.7.2 headless tools/validate_valley_barracks_train.gd -> VALLEY_BARRACKS_TRAIN_OK troops=1 hp=25 spent=60; unaffordable rejected.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-11 11:57:04', '2026-09-11 11:57:04'),
  ('TS-087', 1, '围攻体积槽位：满槽拒锁与原地等待', '用户 2026-09-11 确认原理并授权登记。单位默认圆形碰撞体积；被锁定后攻击者沿外缘占有限围攻槽。槽满则新单位不得再锁定该目标；探测内无其他候选则原地等待。建筑物占地碰撞外缘同一契约。完善现有单位体积在接敌/拒锁中的使用；不改工人采集、箭塔驻守庇护、手动移动优先。决策：temp-02/docs/decisions/adr_029_engage_volume_slots.md；规则 ENGAGE-001～003。关联 ADR-018、WAVE-003、TS-049/053。scope 避开 tower_garrison / transport_corridor / building_repair / monster_building_targeting / combat_unit_stats_config。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '51e7008793a7ada65a00f073180a804dad9dd2d2', 'test_engage_slots / test_troop_crowd_path / test_troop_combat passed; ENGAGE-001~009 F6 accepted by user 2026-09-12. 用户 2026-09-13 确认已合主并完成任务。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-13 08:50:00', '2026-09-13 08:50:00'),
  ('TS-088', 1, '战斗单位原地待命：只原地攻击不追敌', '用户于 2026-09-11 提出并授权登记、认领与实现：为可选战斗任务单位新增「原地待命」命令。激活后战斗单位只能站在原地攻击（或牧师原地震治疗），不得因锁敌追踪，也不得因攻击范围外出现新敌人而自主移动接敌；探测范围内仍可锁定目标，但仅当目标进入攻击/治疗射程时开火，超出脱离距离则清锁。右键地面移动取消原地待命并按既有手动移动优先规则执行。工人不参与。验收：右栏命令格可下达；持守中发现射程外敌人不 chase；射程内可攻击；移动命令解除持守后恢复自动索敌追击；新增/扩展 headless 测试并回归 troop_combat。分类：玩法/战斗命令与 AI。决策记录：temp-02/docs/decisions/adr_031_hold_position_stance.md；规则写入 docs/gameplay_interaction_rules.md（UNIT-008）。关联 UNIT-001/005、ADR-018、ADR-028。scope 避开 tower_garrison / transport_corridor / building_repair / combat_engage_slots / combat_unit_stats_config。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '1f37947406d81b56d12517bc0e0c20d503a5711a', 'PASS Godot 4.7.2: test_troop_combat all assertions incl hold-position no-chase / in-range attack / move cancels hold (exit 0); test_tower_garrison passed (exit 0). ADR-031 and UNIT-008 recorded.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 04:27:15', '2026-09-12 04:27:15'),
  ('TS-089', 1, '战斗单位右键直接锁敌并按距离分围攻槽', '用户 2026-09-11 确认：入口 A。选中战斗单位后右键敌方单位/建筑，直接锁敌并按到受击体距离从近到远瓜分围攻槽（同 ENGAGE 距离分槽契约）；未分到槽者原地等待。本轮不实现，先 ready。关联 ADR-029 / ENGAGE-008；入口 B（移动到位后再分槽）在 TS-087。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '470a72b23bbf49303cbd2be42485e997964a3b2a', '用户 2026-09-13 F6 通过右键直锁与密封环；合主 470a72b（accept/TS-089-right-click-direct-lock）。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-13 08:50:00', '2026-09-13 08:50:00'),
  ('TS-090', 1, '战斗调参实验室：科技 Buff 叠层与兵种木桩/治疗靶', '用户于 2026-09-12 确认独立 combat_lab（新插件+新场景）。顶栏科技按 type 覆盖/异 type 叠加；左侧锁定四兵种；右侧默认空；木桩伤害/QPS 与牧师治疗靶。决策 adr_033_combat_lab_tech_buff.md。关联 TS-052/056。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '9f18c5172b1b8883af78b8062a2ce3c56f33de97', 'test_combat_lab.gd 41/41 pass; F6 combat_lab range rings/tech preview accepted 2026-09-12', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 07:54:12', '2026-09-12 07:54:12'),
  ('TS-091', 1, '默认移动属地交战优先于到达终点', '用户于 2026-09-12 验收会话确认并授权登记。兵种移动分两类：（1）玩家选中后点击的显式移动；（2）默认移动（兵营/靶场出生后前往集合点，以及后期巡逻）。默认移动过程中，属地（探测范围内自动锁敌/交战）优先于到达终点：途中遇敌应优先锁定攻击；交战结束后恢复未完成的默认目的地，除非被玩家新命令覆盖。玩家显式移动仍遵守 ADR-028 / UNIT-005（到达优先、途中不索敌）。廊带让路移动不纳入本契约。验收：出兵赴集合点途中遇怪优先交战并可续行集合；玩家右键地面移动途经同敌人仍不中途交战。分类：玩法/命令优先级与战斗 AI。决策：temp-02/docs/decisions/adr_034_default_move_engage_priority.md；规则 UNIT-009（并修订 UNIT-005）。关联 ADR-018、ADR-028、TS-026。scope 避开 troop_exit_corridor / transport_corridor_band / combat_lab_scene / combat_engage_slots / troop_right_click_attack。规则已确认，登记为 ready，可认领实施。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '4d96e80d3d6a3cab0c0d2a59336c60d572650889', 'test_troop_combat.gd pass (UNIT-009 default-move + patrol); F6 accepted 2026-09-12; merged to main 5c9d3da', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 11:45:58', '2026-09-12 11:45:58'),
  ('TS-092', 1, '战斗编队：右栏编队与左下角快跳图标', '用户于 2026-09-12 在 TS-091 验收通过后确认并授权登记。选中一组战斗兵种后，右栏在巡逻/原地待命旁新增「编队」；编队后左下角出现小图标，点击将视角居中到该编队以便快速锁定（如巡逻中）。决策：temp-02/docs/decisions/adr_036_troop_formation_bar.md。关联 TS-091 / ADR-034 / ADR-031。scope 避开 troop_default_move / default_move_engage_priority / combat_lab_scene。规则已确认，登记为 ready，可认领实施。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 14:06:07', '2026-09-12 14:06:07'),
  ('TS-093', 2, '地面金矿石大/中/小分档消耗与素材切换', '地面 GoldRocks_金矿石（gold4大/gold3中/gold1·gold2小）为不可再生资源。工人采集消耗存量：消耗1/3切换中型素材，再消耗1/3切换小型，采完后隐藏消失；切换时做短暂缩放过渡。不覆盖地图编辑摆放；重开场景恢复。验收：headless 完成大→中→小→消失，金币入库。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '94c0bc891bfe94fc8656bc64e4143dcf13825d39', 'PASS: Godot 4.7.2 headless tools/validate_valley_gold_rock_stages.gd -> VALLEY_GOLD_ROCK_STAGES_OK stages large/medium/small, 48 rocks bound, worker deposits +10 gold, depleted hidden.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:08:12', '2026-09-12 12:08:12'),
  ('TS-094', 2, '右键伐木命令接入', '选中工人后右键树木触发伐木循环，木料入库且 HUD 木数增加。未选中不派工。验收：headless 命令 API 完成一趟交付。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'de4958242d0430fe500c63bb94014bc6eb8efd4b', 'PASS: Godot 4.7.2 headless tools/validate_valley_wood_right_click.gd -> VALLEY_WOOD_RIGHT_CLICK_OK wood 400->440; unselected rejected.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:18:16', '2026-09-12 12:18:16'),
  ('TS-095', 2, 'HUD 训练/建造操作栏', '在 ValleyHUD 增加召唤工人/出兵/造房按钮，调用会话 train_*/place_building；扣费与资源/人口显示同步。验收：headless API 触发训练/建造成功。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '324324ea0a0ddd71dbe6162b1ab28984361c870c', 'PASS: Godot 4.7.2 headless tools/validate_valley_hud_actions.gd -> VALLEY_HUD_ACTIONS_OK workers=2 troops=1 buildings=14.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:19:26', '2026-09-12 12:19:26'),
  ('TS-096', 2, '山谷玩法主场景入口', 'project.godot run/main_scene 指向 valley_gameplay_bootstrap.tscn；F5/运行直接进入可操作会话。验收：配置存在且 headless 加载会话 boot 成功。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '1014341dd15f3890e381148b4d52e40ab3938be0', 'PASS: Godot 4.7.2 headless tools/validate_valley_main_scene.gd -> VALLEY_MAIN_SCENE_OK bootstrap main_scene boots with worker.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:20:10', '2026-09-12 12:20:10'),
  ('TS-097', 2, '羊群/食物最小闭环', '地图羊群或等价食物点可派工收获入库；food 可供兵营训练扣费。不做繁殖。验收：headless 完成一趟入食。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '3f390c8188b53013eeb7528873f1286a3f5ec4b1', 'PASS: Godot 4.7.2 headless tools/validate_valley_food_harvest.gd -> VALLEY_FOOD_HARVEST_OK food trip + barracks spends food=20.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:22:10', '2026-09-12 12:22:10'),
  ('TS-098', 1, '金矿运输双廊分道：带货上行 / 空手下行', '用户于 2026-09-12 确认：在既有 TRAFFIC-025 带货优先与 ADR-024 单条矿↔城廊带之上，为建筑金矿增加方向分道——带货回城走上行（原主廊），空手返矿走主廊下方平行下行，降低对向交汇拥堵。软偏置途经点（堵可回主线），本期仅建筑矿↔城堡；树/羊线不做。保留让路优先级与闲置清廊。决策：temp-02/docs/decisions/adr_037_mine_dual_lane.md。关联 ADR-001/024、TRAFFIC-025、TS-025/078/079；协调 TS-045（scope 不重叠）。不改预约整条路、不硬锁禁止穿廊。用户已确认可实施。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'c3b0721b5a9f6b40bb25f28c49d372fcfd464d5f', 'task branch task/TS-098-mine-dual-lane @ c3b0721; accept branch accept/TS-098-099-mine-lane-and-building-health @ be9240b (ADR-041 renumber from conflicting ADR-037). User F6 acceptance PASS 2026-09-12 on CORRIDOR-005 dual-lane (cargo up / empty down); awaiting merge to main then done.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 14:07:18', '2026-09-12 14:07:18'),
  ('TS-099', 1, '建筑受击生命：左侧事件栏按需展示', '用户于 2026-09-12 确认核心规则：1) 默认不在左侧展示生命值（移除常驻「主城生命」情报格）；2) 建筑受到攻击时在左侧事件栏生成事件；3) 事件条件消失（例如建筑不再受到攻击）时从事件栏去除。世界空间血条仍按 TS-050/BUILDING-HEALTH-001。决策见 temp-02 docs/decisions/adr_038_building_health_event_sidebar.md（ADR-038）。未决（实现前确认或按 ADR 默认）：是否全部可受损建筑、不再受击的超时/锁定判定、与闲置等单槽事件优先级、点击是否定位建筑。实施前写入 gameplay_interaction_rules；回归事件定位与主城/建筑受击测试。避开 TS-092 编队条与 TS-098 金矿双廊 scope。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '3f7d0211eaa2727876dd80134229eba12acfc187', 'task branch task/TS-099-building-health-event-sidebar @ 3f7d0211eaa2727876dd80134229eba12acfc187 (ADR-035; not on main). PASS test_building_health_event.gd 11/11; PASS test_event_focus.gd 10/10. test_monster_assault_integration.gd RESULT 8 failures (castle collision width; troop acquire/monster health bar; timed castle damage chain + cascade event asserts; perimeter siege) — direct _damage_castle covered by dedicated test; not claimed as full assault pass. test_building_repair.gd 22 checks / 1 failure (damage fire clears at full health), likely pre-existing.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 14:07:18', '2026-09-12 14:07:18'),
  ('TS-100', 2, '兵种点选与右键移动/攻击', '山谷会话中已可训练士兵，但无法点选与下达命令。实现：左键选中兵种（与工人选择互斥或并存清晰），右键空地移动，右键敌对/可攻击目标发起攻击；HUD 显示选中兵种状态。不改 formation/编队条（避开 project_0001 TS-092）。验收：headless 选中士兵→移动到位→攻击目标掉血。关联 TS-077/086。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'c4731d1daa67d8c9827e4ce8e6493fb550c538ff', 'PASS: Godot 4.7.2 headless tools/validate_valley_troop_command.gd -> VALLEY_TROOP_COMMAND_OK select+move+attack hp drop; regressions validate_valley_barracks_train/combat/selection OK. branch=task/TS-100-troop-select-move-attack', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:46:50', '2026-09-12 12:46:50');
INSERT INTO `tasks` (`id`, `project_id`, `title`, `description`, `status`, `priority`, `owner_agent_id`, `legacy_owner`, `lease_expires_at`, `claim_token_hash`, `claim_reissue_pending`, `branch_name`, `delivery_commit`, `delivery_tests`, `delivery_notes`, `blocked_reason`, `status_reason`, `accepted_by`, `accepted_at`, `version`, `created_at`, `updated_at`) VALUES
  ('TS-101', 2, '工人右键地面移动命令', '选中工人后右键空地（非矿/树/矿石/食物）下达移动；到达后保持空闲，不覆盖进行中的采集命令优先级（资源右键仍优先）。验收：headless 选中工人→地面移动到位且未误触发采矿。关联 TS-083/094。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '05692bc5eefa9587719105c40026551f90cfe8dc', 'PASS: Godot 4.7.2 headless tools/validate_valley_worker_move.gd -> VALLEY_WORKER_MOVE_OK; regressions selection/wood_right_click/troop_command OK. branch=task/TS-101-worker-ground-move', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:49:03', '2026-09-12 12:49:03'),
  ('TS-102', 2, '箭场扣费训练弓箭手', '地图/运行时箭场可训练 archer：扣金/粮与人口，倒计时后生成远程兵种（沿用 troop 场景或 archer 变体）。资源不足拒绝。HUD 增加箭场出兵入口或复用操作栏。验收：headless 完成一次箭场训练并生成单位。关联 TS-086/095/074。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'a516c3e01554487a74463c9f69fbfbdedfbb8b83', 'PASS: Godot 4.7.2 headless tools/validate_valley_archery_train.gd -> VALLEY_ARCHERY_TRAIN_OK archer range=96 spent gold/food; regressions barracks_train/hud_actions OK. branch=task/TS-102-archery-train', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:52:24', '2026-09-12 12:52:24'),
  ('TS-103', 2, '地图箭塔自动防御射击', '为 Towers_箭塔 / 运行时塔接入自动索敌与间歇伤害（射程内敌对单位）。不改地图摆放，仅运行时绑定。验收：headless 敌对单位进入射程后塔造成伤害。关联 TS-077。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '873dbf34f4e76d5a27ecbd73faa3340883eeff95', 'PASS: Godot 4.7.2 headless tools/validate_valley_tower_defense.gd -> VALLEY_TOWER_DEFENSE_OK towers=19 hostile hp drop; regressions troop_command/session OK. branch=task/TS-103-tower-auto-attack', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:54:06', '2026-09-12 12:54:06'),
  ('TS-104', 2, '通行网格并入建筑与树木阻挡', '将建筑脚底/树木等物件阻挡合并进 passability 网格（或运行时遮罩），工人/兵种 BFS 绕行；道路桥面仍可行走。输出可重复工具或会话启动时合并，不覆盖 reference_valley 摆放。验收：headless 验证建筑邻格不可走且绕行路径存在。关联 TS-069/071/076。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '545336ad3df884c8acdf5997d95c7e69821e2e5d', 'PASS: Godot 4.7.2 headless tools/build_object_blockers.gd OBJECT_BLOCKERS_OK added=709; tools/validate_object_blockers.gd OBJECT_BLOCKERS_RUNTIME_OK; regressions worker/mining_cycle/worker_move/troop_command OK. branch=task/TS-104-object-blockers', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 12:58:25', '2026-09-12 12:58:25'),
  ('TS-105', 2, 'HUD 建造兵营/箭场/箭塔', '在山谷 HUD 增加建造兵营/箭场/箭塔入口，扣金木后在交付点附近可走格放置（instant 可验收）。资源不足拒绝。不改 reference_valley 原有摆放。验收：headless 各至少成功放置一类。关联 TS-095/074/102。', 'review', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, 'a4be6a3e0e1becc9d7d2fecd6c455b2035e2f973', 'PASS: Godot 4.7.2 headless tools/validate_valley_hud_build_military.gd -> VALLEY_HUD_BUILD_MILITARY_OK barracks+archery+tower; regression hud_actions OK. branch=task/TS-105-hud-build-military', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-12 13:09:34', '2026-09-12 13:09:34'),
  ('TS-106', 2, '敌对单位波次最小生成', '按快照 monster_waves 或会话默认，在地图边缘生成敌对单位并走入箭塔射程/可被兵种攻击。不做完整难度曲线。验收：headless 至少一波生成且塔或兵造成伤害。关联 TS-103/100。', 'claimed', 100, 'codex-local-mapbuild', NULL, NULL, 'd40e35458bf55976655c2a3abb2e709500800141837741e593e1a1c79a8f0364', 0, 'task/TS-106-wave-migration', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, '2026-09-12 13:06:52', '2026-09-23 03:29:31'),
  ('TS-107', 2, '兵种框选与多选命令', '拖拽框选多个兵种；右键移动/攻击对当前多选同时下达。与工人选择互斥清晰。验收：headless 框选≥2 兵并共同移动。关联 TS-100。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '470a72b23bbf49303cbd2be42485e997964a3b2a', '用户 2026-09-13 F6 通过兵种框选；合主 470a72b。实现在 temp-02。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-13 08:50:00', '2026-09-13 08:50:00'),
  ('TS-108', 2, '运行时建筑阻挡刷新通行网格', '放置房屋/兵营等运行时建筑后，动态把脚底格标为阻挡并保持道路桥面；工人/兵种随后绕行。不重建整张地形阻挡。验收：headless 造房后原格不可走且仍有绕行路径。关联 TS-104/074。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-13 03:20:36', '2026-09-22 06:45:37'),
  ('TS-109', 1, '城堡军事科技 LV1/LV2/LV3 与满级菜单展示', '用户于 2026-09-12 确认：军事科技线 LV1/LV2/LV3；同 type 高等级覆盖；二次进入须明确当前等级样式；满级 LV3 置灰且不可再点选（不隐藏）。决策 adr_040_combat_tech_levels.md。关联 TS-052 / ADR-023。', 'done', 100, 'sasaki', 'sasaki', NULL, NULL, 0, NULL, '470a72b23bbf49303cbd2be42485e997964a3b2a', '用户 2026-09-13 F6 通过军事科技 LV1-3 与资源不足灰字；合主 470a72b。', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-13 08:50:00', '2026-09-13 08:50:00'),
  ('TS-110', 1, '金矿双廊往返抑制对向让路与出入口原地等待', '用户于 2026-09-12 确认方向：建筑金矿双廊往返时，廊中段不对向工人触发 TRAFFIC-025 侧移让路；出入口占口者先行、被挡方原地短等待不侧移；闲置/非双廊挡路仍由挡路方让开；对向采矿工人挡路则优先调双廊偏置间距。关联 ADR-042（docs/decisions/adr_042_mine_lane_no_peer_yield.md）、ADR-041/TS-098、ADR-024、TRAFFIC-025。本期仅建筑金矿↔城堡；不改 TS-078/079 出兵/闲置清廊 scope。实现与数值（口部半径、等待上限、偏置像素）待认领后落地。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-13 14:37:43', '2026-09-22 06:45:37'),
  ('TS-111', 1, '素材卡片按切片展示第一帧', '用户于 2026-09-13 明确要求创建并实现：素材列表卡片按已有 frame_hint 显示第一行第一帧并等比居中；无可靠切片数据保留原图，不改原始素材。验收覆盖横向动画条、多行图集、普通图片、角色与全部文件模式。分类：素材管理/UI预览。决策：docs/decisions/adr_003_asset_first_frame_thumbnail.md。本次用户授权先建立独立工作区再认领开发，保留共享目录未提交内容。 【用户验收通过】2026-09-13 用户确认首帧预览及七组素材、绵羊补漏均无问题。验收分支 accept/20260913-ts111，验收提交 d78a918880f4a873cdd5d235f6b43e0736c157b8。等待用户选择合主或验收下一任务；合主前保留 review。 【合主完成】用户授权合主推送；代码 main 已推送 d78a918880f4a873cdd5d235f6b43e0736c157b8，TS-111 标记 done。', 'done', 100, 'codex-asset-first-frame', 'codex_asset_first_frame', NULL, NULL, 0, NULL, '41410341dc4b564fef1ab0adaa18d5d8e1329804', 'PASS: three Update 010 sheep PNG source/128x128 assertions; index/catalog checks, UI and animation regression (407 auto-slice / 745 PNG bounds), JS syntax/diff. Acceptance commit d78a918880f4a873cdd5d235f6b43e0736c157b8. Browser visual verification not performed.', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-13 07:07:33', '2026-09-13 07:07:33'),
  ('TS-112', 1, '靶场炮台兵种：炮台工人建造与操作', '用户于 2026-09-13 确认可认领。将 Enemy Pack Extra/Cannon（Cannon_Ball + 朝向炮身）做成固定炮台，搭配黄衣工人。靶场新增「炮台」购买项，训练炮台工人（runtime_id=turret_crew）：金币20/人口1/训练3秒；右栏仅「建立炮台」。放置确认扣第一段金币150；施工6秒，完工再扣200；第二段不足则停工等待不退第一段。不含木材。完工后施工者立即1:1操作炮台（cannon_turret）。战斗：射程500、伤害60、间隔4.0秒、范围伤害半径64px（只伤敌对）。空台不开火。当前怪物/常规单位攻击操作工人（打生命至死），炮台不摧毁、空台不被锁定。后续优先防御建筑或优先攻建筑的兵种才可锁炮台（含空台），本任务不实现该优先。补员：选中空闲炮台工人右键空台接管，不再付两段建台费。操作中不能主动离开。普通采集工不能建台或接管。不改箭塔驻守 TOWER-080。科技树前置解锁后置，本任务靶场可直接买。炮弹飞行与爆炸表现见 TS-113/ADR-044（溅射扣血已归本任务）。决策：temp-02/docs/decisions/adr_043_turret_emplacement.md。分类：玩法/固定炮台与操作工人。scope：turret_crew_unit / turret_emplacement / turret_operator_combat，避开 TS-107/108/109 与 tower_garrison。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-13 11:47:14', '2026-09-22 06:45:37'),
  ('TS-113', 1, '炮塔发射炮弹与命中火焰爆炸效果', '用户于 2026-09-13 提出并确认攻击表现：基于 TS-112 炮台开火，把炮弹飞行和击中对应区域的爆炸展示出来。不重做建造/绑人/两段费用/空台补员。弹道为抛物线；开火瞬间标记落点，炮弹必须飞到该点（目标中途移动或死亡也不改落点）。到达后对标记点 64px 内敌对结算 ADR-043 伤害 60（需要溅射，不误伤友军）。爆炸只用 Update 010 Effects/Explosion/Explosions.png，播放一轮动画后结束，不叠 Fire、不残留地面燃烧。不改弓箭手箭矢与箭塔驻守。决策：temp-02/docs/decisions/adr_044_turret_cannon_explosion.md。分类：玩法/远程战斗反馈与固定炮台。关联 TS-112、ADR-043、ADR-027、UNIT-007。弹速实现默认约 420px/s。scope 独立，避开 turret_crew_unit/turret_emplacement 与 tower_garrison。素材复制进 temp-02。玩法已确认；依赖 TS-112 可开火后认领实施。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-13 14:31:34', '2026-09-22 06:45:37'),
  ('TS-114', 1, '建筑种类区分：资源类与兵营防御类', '用户于 2026-09-13 确认第一版：房屋=资源类；金矿/露天矿=资源类且仍不可被怪打；兵营/靶场/箭塔=防御建筑；城堡=core。小怪默认就近可攻击建筑；特殊兵种可只锁防御或只锁资源（过滤落空回主城，沿途单位仍 ADR-018），过滤另立后续任务。本期实现 building_class 字段、默认表、PM/快照覆盖与读取测试；不改哥布林索敌。看板保持可认领、owner 空，后续认领制作不绑定本次会话。可选续作：本地任务分支 task/TS-114-building-class-defense @ 43be5a3b2873d4cf3b38b80c50ba85aa47adbc0c（未 push、未合主）。决策：temp-02/docs/decisions/adr_045_building_class_defense.md。分类：玩法/建筑分类与攻城目标。关联 ADR-018、ADR-019、TS-053、BUILDING-HEALTH-002。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-13 11:47:16', '2026-09-22 06:45:37'),
  ('TS-115', 1, '快捷启动同时启动素材与任务进度服务', '用户要求扩展现有快捷启动脚本：同时启动 8766 素材服务和 8767 任务进度服务，重复启动复用服务，保留原快捷方式入口。先独立工作区再认领。分类：工具/启动流程；决策 docs/decisions/adr_004_dual_service_launcher.md。', 'review', 100, 'codex-dual-launcher', 'codex_dual_launcher', NULL, NULL, 0, NULL, 'ce8bb95663ae1a4962ca83e7b67d530dc2c199aa', 'PASS python verify_launcher.py: real dual HTTP startup + task API; repeat reuse; space-containing path; equal-port and wrong-service rejection. Only test-created processes stopped; fixtures retained. Default 8766/8767 unchanged; browser opening not exercised (NoBrowser test). branch task/TS-115-dual-service-launcher', NULL, NULL, NULL, NULL, NULL, 1, '2026-09-13 09:05:03', '2026-09-13 09:05:03'),
  ('TS-116', 1, '诅咒萨满攻击（图集挂载：投射物与爆炸）', '用户于 2026-09-13 确认优先实现：诅咒萨满（Hex Shaman，素材组 enemy/character/hex-shaman）在怪物图集中对固定战士肉靶攻击。播放 Attack 动画，发射 Hex Shaman_Projectile，命中后可挂Hex Shaman_Explosion。建议默认第一版不含变形法术（Hex Shaman_Transformation Spell），是否作为第二技能待确认。效果为可挂载模块，后续移植进游戏。决策：temp-02/docs/decisions/adr_046_monster_atlas_attacks.md。分类：玩法/怪物图集与挂载式攻击。依赖 TS-141 攻击舞台；本任务只挂载本兵种模块，不改图鉴头像列表、舞台核心与其他兵种脚本。素材复制进 temp-02，运行时不依赖素材项目路径。本阶段不接入 world_map 波次。仅登记待确认，不认领不实施。', 'ready', 100, NULL, 'sasaki', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '租约到期', NULL, NULL, 2, '2026-09-14 02:35:52', '2026-09-22 06:45:37'),
