  ('imp_4576ba874961c024b1c227c2d2377063', '4576ba874961c024b1c227c2d2377063632711ccc601c6f19aed0ab3367bb9c6', '{\"task_count\": 189, \"by_status\": {\"done\": 110, \"claimed\": 42, \"ready\": 3, \"review\": 30, \"pending_confirmation\": 4}, \"projects\": {\"project_0001\": 116, \"project_0002\": 73}, \"owners\": {\"codex_ts001\": 1, \"codex_ts002\": 1, \"codex_ts003\": 1, \"dsh_map_dev\": 11, \"codex_local_multiselect\": 23, \"codex_ts013\": 1, \"codex_ts016\": 1, \"codex_pm_launcher\": 1, \"codex_task_dashboard\": 3, \"codex_ts043\": 1, \"codex_ts044\": 1, \"codex_ts046\": 3, \"codex_ts049\": 1, \"codex_ts050\": 2, \"sasaki\": 108, \"codex_unit_evolution\": 1, \"codex_warrior_mvp\": 7, \"codex_ui_cooldown\": 1, \"codex_ts066\": 1, \"codex_asset_first_frame\": 1, \"codex_dual_launcher\": 1, \"codex_ts118_rework\": 1, \"codex_ts119_rework\": 1, \"codex_ts120_rework\": 1, \"codex_ts121_rework\": 1, \"codex_ts122_rework\": 1, \"codex_ts129_takeover\": 1, \"codex_ts131_takeover\": 1, \"codex_ts133_takeover\": 1, \"codex_ts134_takeover\": 1, \"codex_ts136_takeover\": 1, \"codex_ts146\": 1}, \"unknown_status\": [], \"claimed_pending\": [\"TS-045\", \"TS-062\", \"TS-065\", \"TS-066\", \"TS-078\", \"TS-079\", \"TS-108\", \"TS-110\", \"TS-112\", \"TS-113\", \"TS-114\", \"TS-116\", \"TS-124\", \"TS-126\", \"TS-127\", \"TS-128\", \"TS-129\", \"TS-131\", \"TS-135\", \"TS-137\", \"TS-138\", \"TS-139\", \"TS-140\", \"TS-142\", \"TS-143\", \"TS-166\", \"TS-167\", \"TS-168\", \"TS-169\", \"TS-170\", \"TS-172\", \"TS-173\", \"TS-174\", \"TS-175\", \"TS-176\", \"TS-179\", \"TS-180\", \"TS-181\", \"TS-182\", \"TS-183\", \"TS-186\", \"TS-187\"], \"unknown_owners\": [\"codex_asset_first_frame\", \"codex_dual_launcher\", \"codex_local_multiselect\", \"codex_pm_launcher\", \"codex_task_dashboard\", \"codex_ts001\", \"codex_ts002\", \"codex_ts003\", \"codex_ts013\", \"codex_ts016\", \"codex_ts043\", \"codex_ts044\", \"codex_ts046\", \"codex_ts049\", \"codex_ts050\", \"codex_ts066\", \"codex_ts118_rework\", \"codex_ts119_rework\", \"codex_ts120_rework\", \"codex_ts121_rework\", \"codex_ts122_rework\", \"codex_ts129_takeover\", \"codex_ts131_takeover\", \"codex_ts133_takeover\", \"codex_ts134_takeover\", \"codex_ts136_takeover\", \"codex_ts146\", \"codex_ui_cooldown\", \"codex_unit_evolution\", \"codex_warrior_mvp\", \"dsh_map_dev\", \"sasaki\"], \"scope_conflicts\": [{\"tasks\": [\"TS-068\", \"TS-069\"], \"scopes\": [\"walkability\"], \"project_key\": \"project_0002\"}, {\"tasks\": [\"TS-073\", \"TS-076\"], \"scopes\": [\"pathfinding\"], \"project_key\": \"project_0002\"}], \"delivery_count\": 139, \"import_id\": \"imp_4576ba874961c024b1c227c2d2377063\", \"idempotent\": false}', '[{\"id\": \"TS-001\", \"project_key\": \"project_0001\", \"title\": \"兵营兵种挂载\", \"description\": \"将兵营与可训练兵种和实际角色生成关联；兵种列表和生成规则待确认。\", \"status\": \"done\", \"owner\": \"codex_ts001\", \"scopes\": [\"barracks_training\"], \"delivery_commit\": \"fd3e52a6cf8f18589aef397d9014c30eae1ca30d\", \"delivery_tests\": \"PASS: Godot 4.7.2 full import; test_unit_purchase.gd RESULT 0 failures; test_sheep_flock.gd 38 assertions 0 failures; git diff --check. Existing unrelated regressions recorded truthfully: test_worker_collisions 1 failure; test_mining_cycle, test_food_jobs and test_wood_jobs have failures and hang; affected gameplay files were not changed. TS-001 is fulfilled by existing TS-026 implementation commits ccfe277 and 89e8c6b; this delivery adds ADR and traceability only.\", \"updated_at\": \"2026-09-05T14:44:05+00:00\", \"continues_from\": []}, {\"id\": \"TS-002\", \"project_key\": \"project_0001\", \"title\": \"兵营兵种接入插件配置\", \"description\": \"通过 TinySwordsPM / Godot 插件配置兵营兵种并接入执行逻辑；字段与同步方式待确认。\", \"status\": \"done\", \"owner\": \"codex_ts002\", \"scopes\": [\"barracks_training\", \"pm_config\"], \"delivery_commit\": \"11468547d6c823e5d446f1289c14d0a23d20395b\", \"delivery_tests\": \"PASS: JSON snapshot schema and cross-reference validation; git diff --check; Godot 4.7.2 test_tiny_swords_pm_config.gd; test_unit_purchase.gd RESULT 0 failures. Snapshot now registers soldier/archer units, barracks/archery training.unit_runtime_ids, project unit bindings and train economy. Invalid references fall back to existing defaults. Existing unrelated dummy-renderer occlusion shader warning remains.\", \"updated_at\": \"2026-09-05T14:59:33+00:00\", \"continues_from\": []}, {\"id\": \"TS-003\", \"project_key\": \"project_0001\", \"title\": \"树木复活时间及配置\", \"description\": \"增加可配置的树木复活时间；复活位置、触发和占位处理待确认。\", \"status\": \"done\", \"owner\": \"codex_ts003\", \"scopes\": [\"forest\", \"pm_config\"], \"delivery_commit\": \"507c1f0f7a14453474ffe81724a2d14b99776784\", \"delivery_tests\": \"PASS: finite-forest static contract verifies forest has no respawn timer/regrowth path, felled trees retain stump state, and test_wood_jobs keeps the Trees do not regrow assertion; git diff --check passed. No gameplay code or user map was changed. Decision: TS-003 automatic regrowth is not implemented because the user confirmed standard finite-resource RTS behavior and existing WOOD-008 remains authoritative.\", \"updated_at\": \"2026-09-05T15:10:09+00:00\", \"continues_from\": []}, {\"id\": \"TS-004\", \"project_key\": \"project_0001\", \"title\": \"房屋人口上限加成（每房+5，可配置）\", \"description\": \"用户反馈（2026-09-05）：房屋建造完成后人口没有上涨。已确认需求：每栋房屋完工时提升人口上限，默认 +5（可叠加多房）；加成数值后期可在 TinySwordsPM 管理端配置（先行以配置常量/快照字段承载，管理端字段化属后续）；事件关联=建筑完工事件（mining_controller._build_after_delay 完工段）接入人口上限提升并刷新 HUD/提示；不改变初始人口，工人训练等人口校验沿用新的上限。注意与 TS-026/TS-030 的完工事件与集结改动共享文件，实施前须同步协调；此任务为原“房屋与人口产生挂载”的确认细化（原范围 construction/population 收紧为 population/house_capacity，避免与 TS-021 占用冲突）。验收目标：建造前后 population_cap 精确 +5、HUD/提示正确、可继续训练工人至新上限、配置值可覆盖默认 5。分类：玩法/人口与建筑；决策记录：实施时建 temp-02/docs/decisions/adr_004_house_population.md。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"population\", \"house_capacity\"], \"delivery_commit\": \"704c8cbba0db8aba8f0bdc38ce2736936318db11\", \"delivery_tests\": \"test_house_population 18/0 (default +5, once-only, stack +10, override 8, top-bar toast, full-cap refusal, training past old cap); unit_purchase 77/0; idle_worker_rally (TS-030 merged) passed; worker_yield 15/0 incl exhaustion->idle; movement_scaling 13/0; worker_training/crowd/batch/game_hud/building_construction passed per implementer. Integrated on ee1d2c7(TS-030). Legacy mining/food/wood failures unrelated. ADR-004 + POP-001 v1.7.0 recorded.\", \"updated_at\": \"2026-09-05T14:57:20+08:00\", \"continues_from\": []}, {\"id\": \"TS-005\", \"project_key\": \"project_0001\", \"title\": \"建造条件及反馈\", \"description\": \"无法建造时显示原因；右侧资源不足的建造选项置灰；建造必须选中工人。具体交互待确认。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"construction\", \"game_hud\"], \"delivery_commit\": \"1f4f91e62409450cfaf7179d9807af1d42360b24\", \"delivery_tests\": \"Build conditions 9, construction 29 and HUD passed. Other pre-existing resource regressions not resolved. Worker menu migration follows in TS-012; no manual acceptance yet.\", \"updated_at\": \"2026-09-03T21:31:34+08:00\", \"continues_from\": [\"TS-009\"]}, {\"id\": \"TS-006\", \"project_key\": \"project_0001\", \"title\": \"羊群等扩展事件选择 UI 断开问题\", \"description\": \"用户反馈点击羊群进行事件选择时，展开 UI 仍有部分断开。后续需复现并确认是布局衔接、按钮命中还是菜单保持问题，再修复相关扩展事件入口；原因尚未确认。验收目标：羊群事件菜单显示完整、按钮可连续正常选择。仅登记，待确认后认领。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"game_hud\", \"sheep_interaction\"], \"delivery_commit\": \"38bd58fe08b045d074a3290a23b694950304acc3\", \"delivery_tests\": \"Menu 13 and real rendering passed; HUD camera batch selection real resources passed; existing food 8 failures and exit resource warnings retained. User accepted.\", \"updated_at\": \"2026-09-03T16:38:24+08:00\", \"continues_from\": [\"TS-009\"]}, {\"id\": \"TS-007\", \"project_key\": \"project_0001\", \"title\": \"左上地图边界被顶部 UI 遮挡\", \"description\": \"用户反馈推拉视角到地图左上角时，顶部 UI 栏仍遮挡左上角地图。后续排查相机边界与可用显示区域的对应关系，复测拖动、缩放后的边界表现。验收目标：保留顶部 UI，同时能将左上边界地图内容完整查看，不被遮挡。仅登记，待确认后认领。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"camera_bounds\", \"game_hud\"], \"delivery_commit\": \"632fad68f8a0ad28da7b579befabc100cf533b5e\", \"delivery_tests\": \"Camera actual transform 25 checks and HUD passed. Construction, animation, batch dispatch, real resource cycles, selection, collision, sheep and freed targets passed. Existing mining 10, food 8, wood multiple/empty array and resource exit warnings retained. User accepted.\", \"updated_at\": \"2026-09-03T16:30:23+08:00\", \"continues_from\": [\"TS-009\"]}, {\"id\": \"TS-008\", \"project_key\": \"project_0001\", \"title\": \"建筑施工工人闪烁\", \"description\": \"用户反馈建筑建造过程中工人出现闪烁。后续复现并检查施工动画、状态切换及建筑遮挡等可能原因，不预设根因。验收目标：工人前往施工、持续建造和完工退出过程中显示稳定，不发生异常闪烁。2026-09-03 用户确认施工不再闪烁，视觉验收通过；代码尚待提交及交付归档，状态暂保留 claimed，不绕过 review/done 流程。新反馈的完工站位、底部碰撞及前后遮挡问题归入 TS-010，不视为闪烁问题重新出现。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"construction\", \"worker_animation\"], \"delivery_commit\": \"a701799466d08e7e33431163007bbe477bb306f6\", \"delivery_tests\": \"Animation 7 checks, construction, batch dispatch, real resource cycles, selection, collisions, sheep and freed targets passed. Existing mining 10, food 8, wood multiple/empty array and minimap 1 failures retained. User accepted no flicker.\", \"updated_at\": \"2026-09-03T15:05:30+08:00\", \"continues_from\": []}, {\"id\": \"TS-009\", \"project_key\": \"project_0001\", \"title\": \"鼠标框选无法同时选中多个单位\", \"description\": \"用户反馈场景存在多个工人时，鼠标框选无法同时选中多个单位。后续复现并检查框选命中、选中集合及各单位选中标记，不预设根因。验收目标：框住多个可选工人后，这些工人同时保持选中并各自显示选中反馈；保留原有单选行为，单纯选择不得中断已有工作。批量命令、编队和追加选择等规则另行确认，不在本任务登记时默认扩展。仅登记，待确认后认领。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"unit_selection\", \"game_hud\"], \"delivery_commit\": \"2d16c939c67035b18a67b335f8d072faca4078b8\", \"delivery_tests\": \"Multi-selection 14 assertions passed; worker collisions, sheep flock and construction passed. Existing failures: mining 10, food 8, wood multiple plus empty array, minimap 1. Manual visual acceptance pending.\", \"updated_at\": \"2026-09-05T15:16:49+00:00\", \"continues_from\": []}, {\"id\": \"TS-010\", \"project_key\": \"project_0001\", \"title\": \"新建建筑的碰撞体积与遮挡关系\", \"description\": \"2026-09-03 用户结合三张截图明确验收要求：图1（角色显示在屋顶上）：角色从建筑后方经过时，建筑图像应绘制在角色之上并遮住重叠部分，不能呈现踩在屋顶的效果。图2（角色与下部墙体重叠）：建筑底部实际落地占地应有碰撞阻挡；工人从下部经过时不得进入该区域，已有重叠需要排出到占地外，而不只是调整显示层级。图3（完工角色留在建筑内）：建筑完成后，应将占地内的施工工人或其他小兵安全移出至建筑旁可站立地面，不能留在墙体或屋顶图像上；安全落点应可达、不落入其他障碍，也不能困住单位。碰撞偏移、寻路障碍与完工清场使用一致的底部占地范围，不以整张贴图或贴图中心代替实际占地。前后遮挡依据单位脚底与建筑落地点关系：后方被建筑遮住，前方且已在占地外的单位正常显示在建筑前。验收分别覆盖后方遮挡、下部碰撞排除、完工移出三种情况，不能只靠提高建筑图层掩盖碰撞错误。透明或轮廓提示未获要求，不自行添加；施工阶段是否阻挡仍待确认。与 TS-008 协调，但施工闪烁已由用户验收通过。本次仅补充记录，不认领、不实施，待后续执行确认。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"construction\", \"building_collision\", \"depth_sorting\"], \"delivery_commit\": \"c9d6b3eae2df71d0820fec7b1a575dbc75cc46b4\", \"delivery_tests\": \"Construction 29 passed incl. arrival gate, bottom collisions, clearance and sorting; animation, batch jobs, real resource cycles, selection, collisions, sheep and freed targets passed. Existing mining 10, food 8, wood/empty array and minimap 1 failures retained; user accepted.\", \"updated_at\": \"2026-09-03T16:23:10+08:00\", \"continues_from\": []}, {\"id\": \"TS-011\", \"project_key\": \"project_0001\", \"title\": \"左侧事件通知点击定位并选中目标\", \"description\": \"点击左侧通知应快速定位对应事件目标。例如用户所述工人限制暂按工人闲置理解，点击后相机定位并选中该工人。通知必须绑定具体目标，目标失效时不能误选其他单位或报错。多工人通知聚合及定位方式待确认；与 TS-007、TS-009 协调，单纯定位选择不得中断现有工作。仅本地登记，不执行。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"game_hud\", \"unit_selection\", \"camera_bounds\"], \"delivery_commit\": \"68c77497ed00e7ca8597eda514cc9ba397acfa3c\", \"delivery_tests\": \"Event focus 5, direct commands 6, construction 29, HUD, camera25, menu13, selection, batch, real resources, collisions, sheep38 and freed targets passed. Existing mining10 food8 wood/empty array failures retained; manual acceptance deferred.\", \"updated_at\": \"2026-09-03T21:31:53+08:00\", \"continues_from\": [\"TS-005\", \"TS-009\", \"TS-012\", \"TS-014\", \"TS-015\"]}, {\"id\": \"TS-012\", \"project_key\": \"project_0001\", \"title\": \"建筑建造入口迁移至工人菜单\", \"description\": \"将建筑建造事件绑定到工人菜单，不再绑定到主建筑菜单。选中工人后显示其建造入口，并关联该施工工人。与 TS-005 的选中工人建造条件共同落实，避免重复实现；多选工人时如何指定施工者待确认。仅本地登记，不执行。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"construction\", \"game_hud\", \"unit_selection\"], \"delivery_commit\": \"868336ec0e64b69cc1993624657e973812dc2c4a\", \"delivery_tests\": \"Build conditions/menu 10, construction 29, HUD and selection passed. Existing resource failures retained; manual acceptance pending.\", \"updated_at\": \"2026-09-03T21:31:39+08:00\", \"continues_from\": [\"TS-005\", \"TS-009\"]}, {\"id\": \"TS-013\", \"project_key\": \"project_0001\", \"title\": \"主建筑菜单绑定科技树与召唤工人\", \"description\": \"主建筑单位菜单负责科技树、召唤工人等事件，与 TS-012 的工人建造菜单区分。核查入口绑定实际功能，不能只是占位显示。本项不默认授权扩展科技内容或改变升级规则，其他主建筑事件待确认；与 TS-014 协调召唤交互。仅本地登记，不执行。\", \"status\": \"done\", \"owner\": \"codex_ts013\", \"scopes\": [\"game_hud\", \"worker_training\", \"technology_tree\"], \"delivery_commit\": \"5ad81a6d07f739ead854b3c6656a03d5cf1e3776\", \"delivery_tests\": \"PASS: test_tiny_swords_pm_config.gd; test_technology_tree.gd verifies configured cost, one-time purchase, 20 percent mining/wood speed effect and no duplicate charge; test_unit_purchase.gd RESULT 0 failures; technology JSON contract and git diff --check pass. Existing dummy-renderer occlusion shader warnings remain unrelated.\", \"updated_at\": \"2026-09-08T07:10:35+00:00\", \"continues_from\": []}, {\"id\": \"TS-014\", \"project_key\": \"project_0001\", \"title\": \"建造与召唤工人取消菜单二次确认\", \"description\": \"点击建筑或召唤工人菜单选项后直接进入下一环节，不再要求额外点击执行确认。建造暂按直接进入地图放置预览、仍由用户选择有效落点确认理解，不自动选择位置；召唤工人暂按条件满足后直接进入现有训练流程理解，不跳过耗时。资源和人口校验、建造取消不扣费、一次操作不重复扣费须保留。与 TS-005、TS-012、TS-013 协调；上述解释待确认。仅本地登记，不执行。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"construction\", \"game_hud\", \"worker_training\"], \"delivery_commit\": \"52f2f91706c68adb45c7c1abf1b4747a689d2041\", \"delivery_tests\": \"Direct commands 6, build conditions 10, construction 29, HUD and selection passed. Real worker spawned after delay and single payment; no manual acceptance yet.\", \"updated_at\": \"2026-09-03T21:31:43+08:00\", \"continues_from\": [\"TS-005\", \"TS-009\", \"TS-012\"]}, {\"id\": \"TS-015\", \"project_key\": \"project_0001\", \"title\": \"小地图嵌入右侧菜单顶部\", \"description\": \"将目前右上角的小地图嵌入右侧菜单的上部，重新安排下方单位与建筑命令内容。保留小地图定位交互，复核面板尺寸、缩放和鼠标命中区域；与 TS-007 的地图可视区域及 TS-011 的事件定位协调，避免新增地图遮挡或位置映射偏差。具体布局尺寸待确认。仅本地登记，不执行。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"game_hud\", \"camera_bounds\", \"minimap_layout\"], \"delivery_commit\": \"812aec5e6b07ed30ee7aa133c4b8a9434fd3e848\", \"delivery_tests\": \"HUD, camera, sheep menu, direct commands, construction and selection passed; OpenGL preview inspected. Command detail spacing refined after preview; ongoing regression follows. Existing resource failures retained; manual acceptance pending.\", \"updated_at\": \"2026-09-03T21:31:48+08:00\", \"continues_from\": [\"TS-005\", \"TS-009\", \"TS-012\", \"TS-014\"]}, {\"id\": \"TS-016\", \"project_key\": \"project_0001\", \"title\": \"未选中状态下右侧栏显示建议事件\", \"description\": \"未选中单位或建筑时，右侧栏展示基于当前事件的操作建议，而不是仅显示空白状态。例如工人闲置时建议重新分配任务，兵营建造完成时建议生产兵种。与左侧通知共用对应事件目标，关联 TS-011 的定位选中流程及 TS-001/TS-002 的兵营生产能力，避免重复实现。建议点击后是先定位选中并打开相应菜单，还是直接进入操作流程，及建议优先级、数量和消失条件待确认；不得因显示建议自动派工、训练或扣费。验收目标：未选中时展示有效建议，进入单位选择后恢复相应菜单，目标失效或条件变化时不保留错误操作入口。仅本地登记，不执行。\", \"status\": \"done\", \"owner\": \"codex_ts016\", \"scopes\": [\"game_hud\", \"unit_selection\", \"barracks_training\"], \"delivery_commit\": \"7c87326c0354f915095dc12747d3350561406734\", \"delivery_tests\": \"PASS: Godot 4.7.2 import; event_focus 10/0, idle_worker_rally 9/0, build_conditions 10/0, multi_selection 19/0, unit_purchase 0 failures, direct_commands 6/0, batch_dispatch 18/0, sheep_flock 43/0; OpenGL ui_empty_preview visually verified latest idle event selects six workers and shows full worker menu without auto command or camera move. Existing failures retained: worker_collisions 1, mining_cycle 10, food_jobs 8, wood_jobs 9; game_hud related TS-016 assertions pass then pre-existing title layout and missing BodyScroll stop script; dummy shader, log and exit leak warnings remain.\", \"updated_at\": \"2026-09-08T08:35:16+00:00\", \"continues_from\": []}, {\"id\": \"TS-017\", \"project_key\": \"project_0001\", \"title\": \"扩大鼠标滚轮视野缩放范围\", \"description\": \"用户希望滚轮可调整的视野范围再扩大，并希望获得最大值建议。当前本地代码 CAMERA_ZOOM_MIN=0.55、CAMERA_ZOOM_MAX=1.80、每档倍率1.12。注意 Godot zoom 越小看到的地图越多，越大则角色和建筑越大；用户所说调高是拉远范围还是近看倍率仍需确认。建议第一轮试验范围为0.40至2.40：相对当前最远视野，0.40可多看约37.5%的横纵范围、约89%的面积；2.40相对当前最大近看倍率再放大约33%。这些是待确认试验值而非已修改参数，需实测单位辨识、点选、框选及地图大小限制；UI保持固定尺寸，协同 TS-007/TS-015 复核边界遮挡与小地图定位。仅本地登记，不执行。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"camera_bounds\", \"camera_zoom\", \"game_hud\"], \"delivery_commit\": \"15c8095b47594abcee9c42dfaed8f7f0a45af1ec\", \"delivery_tests\": \"Zoom range0.40-2.40; camera29 selection19 HUD34 passed again with user parameters; server check passed. Collision20 sheep38 passed in previous run; existing mining10 food8 failures, wood45s timeout and exit resource warnings retained. User authorized combined config commit. Manual zoom visual acceptance pending.\", \"updated_at\": \"2026-09-05T15:18:03+00:00\", \"continues_from\": [\"TS-009\", \"TS-020\"]}, {\"id\": \"TS-018\", \"project_key\": \"project_0001\", \"title\": \"批量派工与资源目标独占分配\", \"description\": \"已确认分配规则：每份掉落货物只允许一名工人拾取，一只羊对应一名工人，一棵树对应一名工人，一个建造任务对应一名工人；批量采矿、伐木、狩猎采集按这些目标容量分配，不能把全部工人派到同一独占目标。金矿允许多工人同时采集。派工时预占目标，而非到达后再争抢；取消、目标失效或工人离开时释放占用，货物只拾取和入库一次，已携带货物不因换任务丢失。用户已确认：工人数超过可用目标时，未分到目标的工人原地等待；同类任务出现可用目标后自动补位，不抢占其他工人的目标。手动改派后退出原等待队列，不得被旧任务自动召回。依赖 TS-009 多选验收；与 TS-005/TS-012 的施工者规则协调。当前是规则确认记录，不等于 TS-009 已验收，也不等于认领、开发或推送授权；仍待执行流程确认。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"unit_selection\", \"game_hud\", \"worker_jobs\", \"forest\", \"sheep_interaction\", \"construction\"], \"delivery_commit\": \"ebed647b6376815d9e9002d0e3caaa9edb972222\", \"delivery_tests\": \"Focused tests passed: batch dispatch 18, real resource cycles 4, multi-selection 14, construction 16, collisions, sheep flock 38, freed targets. Existing failures retained: mining 10, food 8, wood multiple plus empty array, HUD minimap 1; headless exit resource warnings. User explicitly accepted TS-018 on 2026-09-03.\", \"updated_at\": \"2026-09-03T11:44:19+08:00\", \"continues_from\": [\"TS-009\"]}, {\"id\": \"TS-019\", \"project_key\": \"project_0001\", \"title\": \"Godot 项目控制台一键启动管理服务\", \"description\": \"用户已确认并授权本次任务的认领、代码和交付推送。将 temp-02 插件按钮改为启动并打开管理页面，复用健康检查，服务未运行时后台启动 TinySwordsPM，防重复启动，显示路径、Python、端口及启动超时等错误。插件目录及专用测试、使用文档为修改范围；不修改游戏玩法、场景或其他任务代码。\", \"status\": \"done\", \"owner\": \"codex_pm_launcher\", \"scopes\": [\"pm_service_launcher\"], \"delivery_commit\": \"aeff7a30fb18dfb445716d0428a69f497eda90fc\", \"delivery_tests\": \"Godot 4.7.2 headless editor import passed; 11 launcher integration tests passed, including cold start, reuse, concurrent launch, Chinese/space paths, missing Python/path, server failure, timeout and dock button states. Worker collisions and sheep flock passed. Existing gameplay failures retained: mining 10, food 8; wood 9 assertions plus invalid array access, terminated after 25s timeout. Browser window opening and visual acceptance pending; details in temp-02/docs/pm_service_launcher.md.\", \"updated_at\": \"2026-09-08T07:10:40+00:00\", \"continues_from\": []}, {\"id\": \"TS-020\", \"project_key\": \"project_0001\", \"title\": \"放大右栏小地图并将命令标题移到其下方\", \"description\": \"用户明确要求右栏顶部小地图放大，工人命令等标题移到小地图下方。保持右栏宽度、地图定位及下方滚动命令可用。本任务不修改工人碰撞；用户已要求碰撞部分先不展开，继续其他任务。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"game_hud\", \"minimap_layout\"], \"delivery_commit\": \"cac6f6578926888b771eedebea9778f55aa8de45\", \"delivery_tests\": \"HUD, camera safe bounds, direct commands, event focus and sheep menu passed. Actual OpenGL preview inspected; minimap 236x178 above title. Worker collision unchanged; existing resource test failures and exit warnings remain. Manual acceptance pending.\", \"updated_at\": \"2026-09-05T15:20:00+00:00\", \"continues_from\": [\"TS-009\"]}, {\"id\": \"TS-021\", \"project_key\": \"project_0001\", \"title\": \"工人互相碰撞与障碍绕行\", \"description\": \"用户确认同时处理工人之间不可重叠、与建筑树木等障碍的脚底碰撞；移动需要绕行让位，不能因开启硬碰撞导致多人挖矿、交付或建造堵死。保留独占羊树货物规则，金矿支持多人；检查出生、停靠和拥堵重试，不改变资源产出和费用。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"worker_jobs\", \"worker_collision\", \"worker_navigation\", \"worker_training\", \"construction\"], \"delivery_commit\": \"d9c7d334e9846e18c09479da27d63c3ca73866c4\", \"delivery_tests\": \"Crowd 5 passed incl ten workers two mining cycles, head-on passage and no overlap; real resources, batch dispatch, static collision, construction29, training, build conditions, selection, HUD, sheep38 and freed targets passed. Existing mining10 food8 wood/empty array failures and exit warnings retained. Manual acceptance pending.\", \"updated_at\": \"2026-09-05T15:23:15+00:00\", \"continues_from\": []}, {\"id\": \"TS-022\", \"project_key\": \"project_0001\", \"title\": \"矿洞内独立采集与安全出洞\", \"description\": \"用户确认：工人到达矿口才隐藏并关闭碰撞，矿洞内不限工作位，各自按原配置独立计时；采完从矿口附近安全出洞恢复碰撞并运输。矿上显示采矿人数。中途改派需安全出洞、不丢已有货物、不结算未完成采集。保留洞外碰撞；5人并行采集不保证运输入库严格5倍。用户已授权本次认领与交付普通推送。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"worker_jobs\", \"worker_collision\", \"worker_navigation\", \"unit_selection\"], \"delivery_commit\": \"f9cc3f899a6b700f936b4ff055bc534f6fb242b0\", \"delivery_tests\": \"Mine interior 18 passed, including five concurrent miners, real blocked exit, no duplicate cargo, safe emergence and cancellation. Crowd five passed incl ten workers two delivery cycles. Batch real resources, dispatch, collisions, construction, direct commands, selection, HUD, sheep38 and freed references passed. OpenGL preview inspected; editor import passed. Existing mining10 food8 wood assertions/empty array failures and exit RID warnings retained; see docs/ts_022_mine_interior.md. Manual acceptance pending.\", \"updated_at\": \"2026-09-08T07:10:44+00:00\", \"continues_from\": [\"TS-009\", \"TS-021\"]}, {\"id\": \"TS-023\", \"project_key\": \"project_0001\", \"title\": \"建筑内并行交付与露天金矿对比\", \"description\": \"用户确认并授权认领交付推送：工人到城堡入口后隐藏，各自按原交付时间完成入库，安全出门；保留中途取消货物与一次性结算。增加一处露天矿石作为对比，工人在矿石旁可见挥镐，不隐藏、不远距离采集；建筑型金矿保留洞内采集。沿用配置产量时长，不调整地图原始绘制或经济费用。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"worker_jobs\", \"worker_collision\", \"worker_navigation\", \"unit_selection\", \"resource_deposit\"], \"delivery_commit\": \"028976a5a56e160befd474071d48e4305c2d9995\", \"delivery_tests\": \"Depot/outdoor integration18 and ore slots6 passed. Mine interior18, ten-worker two-cycle crowd, batch real resources, dispatch, collision, construction, direct commands, multi-selection, HUD, sheep38 and freed references passed. OpenGL comparison inspected; headless editor import and diff check passed. Existing mining10 food8 wood assertion/empty-array failures and exit RID warnings retained; see docs/ts_023_depot_and_outdoor_ore.md. Manual acceptance pending.\", \"updated_at\": \"2026-09-08T07:10:49+00:00\", \"continues_from\": [\"TS-009\", \"TS-021\", \"TS-022\"]}, {\"id\": \"TS-024\", \"project_key\": \"project_0001\", \"title\": \"矿点工人容量配置与露天采集约束\", \"description\": \"用户授权认领、配置代码修改及普通推送。管理页面增加每矿点采集工人数上限，建筑金矿默认5、露天矿石默认2；配置经插件快照实际加载，超额等待且不挥镐不产出，空位释放后补位。检查露天矿石攻击距离和朝向，城堡存放容量不变。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"worker_jobs\", \"worker_navigation\", \"resource_capacity\", \"pm_parameters\"], \"delivery_commit\": \"b205f064ee5f999d3b563d5416198715eb25870c\", \"delivery_tests\": \"User accepted TS-024. PM unittest18 and server check passed; capacity12 collision20 sheep38 HUD34 depot18 ore slots7 passed. Legacy mining10 food8 failures; wood timed out at45s; exit resource warnings remain. PM code committed separately; docs/ts_024_mining_capacity.md records validation.\", \"updated_at\": \"2026-09-04T12:54:18+08:00\", \"continues_from\": [\"TS-021\", \"TS-022\", \"TS-023\"]}, {\"id\": \"TS-025\", \"project_key\": \"project_0001\", \"title\": \"工人局部优先级让路与城堡通道疏通\", \"description\": \"用户确认局部请求让路：运输优先于赶路，空闲和等待最低，同级稳定编号决定；低优先级暂存任务侧移，通道腾出后高优先级通过。每次锁定一个请求和落点；新用户命令打断；无安全位置不得穿透。资源耗尽保留任务并在通道外等待。验证六工人六树全部交付、迎面和多人通过、任务货物不丢不重复结算。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"worker_jobs\", \"worker_collision\", \"worker_navigation\", \"resource_deposit\"], \"delivery_commit\": \"8e90557c5f865ffb0a0f41d28a1db1057cb6ff88\", \"delivery_tests\": \"Yield15 incl six actual trees all deposited and doorway clear; crowd5 incl ten workers two cycles; final real-resource4 capacity12 passed. Depot18 batch18 collision20 construction29 selection19 HUD34 interior18 sheep38 freed targets passed. Editor import and OpenGL yield15 passed. Legacy mining11 confirmed same failures on pre-change15c8095; food8; wood9 plus invalid array and50s timeout; exit resource warnings remain. Manual acceptance pending; docs/ts_025_worker_yield.md.\", \"updated_at\": \"2026-09-08T07:10:59+00:00\", \"continues_from\": [\"TS-021\", \"TS-022\", \"TS-023\"]}, {\"id\": \"TS-026\", \"project_key\": \"project_0001\", \"title\": \"兵营/弓箭营购买兵种与出兵集结范围\", \"description\": \"用户确认细则：步兵（近战战士）金币50/4秒/人口1，弓箭手金币60/4秒/人口1，与召唤工人对齐、后续可经配置调整；兵营与靶场落成后在门口生成发光购买点，点击即按命令面板样式购买；兵营、主城（城堡）、弓箭营（靶场）出兵后新单位在建筑中心周边64px内集结等待、不超出范围，城堡现有工人训练出兵同样遵循；可继续下达命令。现有基础：temp-02 已配置兵营（木材160/金币60/10秒）与靶场（木材180/金币50/9秒）建造价格，HUD 注明建造后\\\"解锁步兵/解锁弓手\\\"；城堡训练仅支持 worker（金币50/4秒），规则 TRAIN-001/002（城堡交付点附近生成工人）；房屋/兵营/塔/靶场建造入口与放置规则见 docs/gameplay_interaction_rules.md（UI-006/UI-007/BUILD-001）；registry 已登记 unit_0001-0003 近战战士数值可作兵种参数来源。待确认（不阻塞开发）：兵种数量上限与后续战斗规则、弓箭手数值具体来源。验收目标：兵营光点可购买步兵、弓箭营光点可购买弓箭手并正确扣费（含资源/人口不足不扣费）与生成；兵营、主城、弓箭营出兵后单位集结于建筑周边64px范围内、不超出范围。兵种选择/移动/战斗与数值插件化属后续任务（TS-001/TS-002 及战斗任务），不在本任务验收范围。分类：玩法/单位生产与集结；决策记录：map-build-temp-01/temp-02/docs/decisions/adr_002_ts026_recruit_rally.md。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"barracks_training\", \"unit_purchase\", \"rally_point\"], \"delivery_commit\": \"209c16d6be832b1cc3a6eca36c2d24dab93fe524\", \"delivery_tests\": \"TS-026 v3 返工（2026-09-05 用户要求圆心=建筑本体）：test_unit_purchase 77 断言通过（兵营占地中心/城堡碰撞中心为允许圆圆心、默认集合点=门口/交付点且在圆内、圆外拒/圆内落、真实输入链路购买、出生≤96 按建筑中心计）；test_movement_scaling13、worker_yield15、crowd5、batch18、game_hud34、worker_training 通过。集成于 TS-028 之上。历史遗留失败类（mining/food/wood）与本任务无关。购买入口仍为门口光点（悬停提示+完工指引）；手动视觉验收待复验。\", \"updated_at\": \"2026-09-05T14:57:18+08:00\", \"continues_from\": []}, {\"id\": \"TS-027\", \"project_key\": \"project_0001\", \"title\": \"决策记录规范与移动系统架构决策归档\", \"description\": \"用户明确要求将沟通最终方案、问题描述、挂载任务和分类本地留档。建立 docs/decisions 索引、模板和 ADR-001，记录 TS-025 验收反馈、采用分层移动系统的架构方向及实施边界。分类：工程治理/决策追踪；关联实施任务 TS-028。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"decision_records\"], \"delivery_commit\": \"36d583eae590bc0c1c1a0fd6f47ff1a779492726\", \"delivery_tests\": \"Documentation validated: local Markdown links resolve; required problem/final decision/task/category sections present; TS-027 and TS-028 project associations verified; diff check passed. No gameplay code changed. ADR-001 records approved architecture, unconfirmed soft overlap and TS-026 coordination boundary; TS-028 not claimed.\", \"updated_at\": \"2026-09-08T07:11:04+00:00\", \"continues_from\": []}, {\"id\": \"TS-028\", \"project_key\": \"project_0001\", \"title\": \"分层单位移动系统与规模性能验证\", \"description\": \"用户已同意采用共享地图寻路、局部邻居查询/避障、出入口规则分层及分批计算方向，详见 temp-02/docs/decisions/adr_001_unit_movement.md。问题：TS-025 验收中单位相遇走停，多人时明显；真实画面掉帧与计算耗时尚未测定。分类：架构/单位移动；性能/寻路与局部避障；缺陷/拥挤卡顿。计划100/200/300单位分散、交汇、出口压力原型验证，不宣称现有战斗系统或既定性能。实施边界已收紧：TS-026已交付review，提交ccfe2770；TS-028只读取其64px集结与出生接口，不修改购买、扣费、出生或rally_point规则，不接管TS-026。软重叠未确认，保留物理碰撞。软重叠没有明确确认，保留物理碰撞。用户已确认架构方向并指示同步后认领推进；范围收紧后可执行。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"worker_navigation\", \"worker_collision\", \"worker_jobs\", \"resource_deposit\", \"movement_performance\"], \"delivery_commit\": \"617276ff3e83e8f6bd94aba956a0b1fc2eed0660\", \"delivery_tests\": \"PASS: test_movement_scaling (100/200/300), test_worker_yield, test_freed_resource_targets, test_batch_dispatch, test_unit_purchase. test_worker_crowd first 4 checks passed; long 10-worker mining loop retained as extended regression.\", \"updated_at\": \"2026-09-08T07:11:09+00:00\", \"continues_from\": [\"TS-021\", \"TS-022\", \"TS-023\", \"TS-025\"]}, {\"id\": \"TS-029\", \"project_key\": \"project_0001\", \"title\": \"工人超20人全选派发指令卡顿排查与优化\", \"description\": \"用户反馈（2026-09-04）：大量训练工人，工人超过约20人时一次性框选全部工人并发送一条指令（右击地面移动/指派），出现明显卡顿。静态代码排查结论（未实测）：主因是点击当帧 N 名工人同步各自执行含全量障碍的可见图 A*（mining_controller _move_selected_group 先算一次可达性即弃、command_move/_travel 路径请求再算一遍=路径双算；每请求 _find_worker_path 触发 _refresh_navigation 全量重建，同帧重复 N 次），叠加移动期 worker_traffic.avoid 每物理帧 O(N²) 全组扫描、blocked≥0.5s 全量重寻路尖峰；HUD/渲染已排除。分类：性能/命令派发与寻路；关联：ADR-001、TS-025（已 review）、TS-028（已 review，实施已完成并含 test_movement_scaling，共享 worker_navigation/movement_performance 范围；TS-029 若实施须基于 TS-028 现状重新核对候选快赢是否仍适用并协调）。候选快赢（不动架构）：a1 消除路径双算（命令路径直接传给 command_move）；a2 导航重建脏标记（同帧 N 次 _refresh_navigation 合并）；a3 全选>阈值降级提示；更大优化（全组避障空间划分、分批预算寻路）已在 TS-028 分层移动系统范围。方案与 owner 待用户确认；建议先建 headless 基准（10/20/40 工人全选+派发单帧耗时）验证现况是否仍有卡顿再动优化。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"worker_navigation\", \"movement_performance\", \"command_dispatch\"], \"delivery_commit\": \"e6e0b831fdc4e80d108311f2d666b7e383f396e4\", \"delivery_tests\": \"PASS: command dispatch scaling 10/20/40 workers (11.675/13.393/17.499 ms; 8 immediate paths; 2/12/32 deferred), movement scaling, batch dispatch, multi-selection, sheep flock (43 assertions). Existing unrelated mainline failures retained: worker collisions 1, mining 11, food 8, wood 9 then invalid array; headless clip shader/meta errors.\", \"updated_at\": \"2026-09-08T07:11:14+00:00\", \"continues_from\": [\"TS-021\", \"TS-022\", \"TS-023\", \"TS-025\", \"TS-028\"]}, {\"id\": \"TS-030\", \"project_key\": \"project_0001\", \"title\": \"闲置工人集结与一键选择\", \"description\": \"用户确认：工人完成存放后优先延续原任务；仅在资源已耗尽或任务目标确实消失时，前往城堡右侧闲置集结区的离散站位，避免堵塞出入口。暂时没有可分配采集位的工人保留任务和等待状态，不归入闲置。左侧事件聚合显示闲置工人数；未选中单位时右侧显示‘闲置工人’入口，点击任一入口同时选中所有闲置工人并定位集结区。分类：玩法/工人调度、建筑入口、单位选择；决策记录：map-build-temp-01/temp-02/docs/decisions/adr_003_idle_worker_rally.md；接续 TS-028。\", \"status\": \"done\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"idle_worker_rally\", \"idle_worker_selection\", \"idle_worker_event\"], \"delivery_commit\": \"ee1d2c7e803146e1181a39bf9e4474b3f2e3feb7\", \"delivery_tests\": \"Godot 4.7.2 editor parse passed; test_idle_worker_rally, test_unit_purchase, test_game_hud, test_worker_yield, test_batch_dispatch, test_movement_scaling and test_worker_collisions passed after TS-026 v3 merge.\", \"updated_at\": \"2026-09-11T03:31:43+00:00\", \"continues_from\": [\"TS-028\"]}, {\"id\": \"TS-031\", \"project_key\": \"project_0001\", \"title\": \"项目控制台：建筑配置显示与碰撞/集结半径可视化编辑\", \"description\": \"用户需求（2026-09-05）：1) 将\\\"建筑集合可操作的半径\\\"做成配置放到项目控制台（TinySwordsPM Web http://127.0.0.1:8765），按建筑类型各一条（城堡/兵营/靶场等，默认 96，游戏侧 TS-026 硬编码改读该配置并带默认回退）；2) 建筑配置（如碰撞体积）同步显示在控制台右侧\\\"实时预览\\\"窗格；3) 支持在预览窗格上对碰撞体积手动拖拽调整（四边/四角改宽高+整体拖拽调 offset_x/y），并按原素材比例展示；保存走既有校验与原子提交，单位碰撞编辑范围后续再扩。分类：玩法/建筑配置与集结点；工具/Web 控制台；关联：TS-026（集结半径读取方）、TS-001/TS-002（PM 配置接入）、TS-004（房屋人口可配置化同思路）。决策记录：TinySwordsPM/docs/decisions/adr_001_console_building_editor.md（建库时启用）。实施说明：控制台侧改动在 TinySwordsPM 仓库（web/app.js、styles.css、tools/server.py 校验、registry 结构、快照/导出），游戏侧读取在 map-build-temp-01/temp-02 另行同步；多仓库交付需分别推送并记录。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"pm_web_console\", \"building_config\", \"collision_editor\", \"rally_radius_config\"], \"delivery_commit\": \"2280010e6e51978d61e832072f51773730d28b7c\", \"delivery_tests\": \"PM unittest 27 passed (registry valid, rally_radius default/invalid rejected, collision min-size+shape, save roundtrip atomic, export/snapshot seed includes rally+collision idempotent); python tools/server.py --check passed. rally_radius per building (default 96, 1-512) with console number field + init/seed tooling; collision drag preview (rect/capsule edges+corners, circle radius, offset drag, min 8 units, ratio 1.25px) manual browser acceptance pending; game-side temp-02 consumption out of this repo commit.\", \"updated_at\": \"2026-09-05T14:57:22+08:00\", \"continues_from\": []}, {\"id\": \"TS-032\", \"project_key\": \"project_0001\", \"title\": \"控制台扫描与素材刷新优化（范围/独立/过滤）\", \"description\": \"用户反馈（2026-09-05）：项目拉取/扫描后页面素材仍是旧的，希望优化扫描：(a) 扫描范围=只扫项目实际加载的内容，不要历史/未使用内容；(b) 独立存储=每个项目独立扫描、文件独立；(c) 过滤展示=作废或未标记的素材不在页面展示。现状（只读核查）：Godot 插件（temp-02/addons/tiny_swords_pm）扫当前编辑器场景节点树 POST /api/project-scan，服务端原子写入 data/scans/<project_key>.json（已按项目独立文件，含 project_id/scene_path/entities/scanned_at）；素材库 661 条来自 tools/import_asset_catalog.py 按整包素材目录生成的静态 asset_catalog（meta.generated_at 为历史时间），与具体项目加载内容无关。待确认：\\\"素材旧\\\"指素材库清单(asset catalog)还是扫描 entities/建筑记录；\\\"实际加载\\\"=仅当前场景引用/绑定的记录，还是含项目插件拉取的全部项目配置；\\\"作废/未标记\\\"的判定标准（registry 记录是否绑定项目？rating/meta 标记？还是页面隐藏标记）；独立存储是否需要额外目录/命名（现已有每项目 json）。分类：工具/Web 控制台；扫描与素材管理；关联 TS-031（同 owner dsh_map_dev review，可 --continue-from 接续）。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"pm_web_console\", \"scan_pipeline\", \"asset_catalog\"], \"delivery_commit\": \"b5017cdc2f208c2d7890840c3e5740953c186ba6\", \"delivery_tests\": \"PM unittest 49 passed (incl library_scope reference rules, retired flag, asset_preview resolver); server --check passed; node --check app.js passed; /api/library-scope + /api/preview-source smoke 200 (temp-02 scope 7/661). Project-scope default view, retired filtering, per-project scan files unchanged, scanned_at shown. Browser interaction manual acceptance pending; local 参考素材 dir absent so previews show clear missing-file note (expected).\", \"updated_at\": \"2026-09-05T15:06:27+08:00\", \"continues_from\": [\"TS-031\"]}, {\"id\": \"TS-033\", \"project_key\": \"project_0001\", \"title\": \"控制台新增建筑/素材的真实素材预览展示\", \"description\": \"用户反馈（2026-09-05）：控制台右上预览区只显示图标/占位，新建建筑未展示实际素材图，希望把真实素材显示在预览框里，更直观美观。现状（只读核查）：web/app.js renderPreview 对 building 记录优先用 visual.preview_asset_id 找 registry.assets 对应素材作背景，找不到则显示占位（图标/色块）；server /source-assets/ 只从 SOURCE_ASSET_CANDIDATES 素材目录提供 catalog 记录的 source_relative 文件；新建建筑若未登记 preview_asset_id 或素材不在 catalog 就没有预览。待确认：预览素材解析优先级（visual.preview_asset_id → assets.normal 路径就近匹配 catalog → 直接按相对路径从素材目录/项目资源目录取图？）；对非 PNG/多帧/特效素材的展示规则；是否需要自动为新建建筑登记 preview_asset_id。分类：工具/Web 控制台；素材预览。关联 TS-031（同 owner dsh_map_dev review，可 --continue-from 接续）。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"building_preview\", \"asset_preview_resolver\"], \"delivery_commit\": \"b5017cdc2f208c2d7890840c3e5740953c186ba6\", \"delivery_tests\": \"PM unittest 49 passed incl preview resolution chain (preview_asset_id -> assets path filename match -> placeholder); server --check + node --check ok; manual browser acceptance pending for async preview & drag overlay coexistence; asset source dir absent shows explicit 404 note.\", \"updated_at\": \"2026-09-05T14:57:24+08:00\", \"continues_from\": [\"TS-031\"]}, {\"id\": \"TS-034\", \"project_key\": \"project_0001\", \"title\": \"PM 插件启动按钮支持重启服务\", \"description\": \"用户需求（2026-09-05）：控制台代码更新后需要重启本地服务；希望改造 Godot 插件（temp-02/addons/tiny_swords_pm），点击「启动并打开管理页面」时若服务已在运行则先停止旧进程再后台启动（重启），使新代码立即生效并打开页面；未运行时行为不变（后台启动）。实现：service_launcher.gd 增加 restart 路径、start_service.ps1 增加 -Restart（按端口停旧进程后启动）、pm_dock.gd 按钮改传 restart；更新 addon 使用文档。分类：工程治理/工具（PM 服务启动器）；关联 TS-019（原启动器任务，owner codex）。交付验收：运行中点击=重启并最终打开页面；未运行=普通启动。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"pm_launcher_restart\"], \"delivery_commit\": \"234cddfbc5f49613704ffe358c654cf3d6346291\", \"delivery_tests\": \"Rework 2026-09-05 (user: restart hangs no progress): root cause = restart flag not consumed so healthy state retriggered restart forever; fixed by consuming _restart_if_running before relaunch. Added: per-second staged progress via launcher.progress (helper writes stopping/starting states), restart deadline +8s stop allowance, dock ProgressBar pulse while busy and \'打开启动日志目录\' button (user://tiny_swords_pm_launcher). start_service.ps1 parses clean (UTF-8 BOM); Godot headless editor parse smoke passed; follow-up chore cd4915d captures editor scene reserialization. Manual verify pending: with service running click button -> staged progress, single restart, opens page; stopped -> normal start; failures show log path & folder button opens logs.\", \"updated_at\": \"2026-09-05T14:57:26+08:00\", \"continues_from\": []}, {\"id\": \"TS-035\", \"project_key\": \"project_0001\", \"title\": \"预览编辑器返工：碰撞拖拽 bug 修复与“遮罩”多边形编辑\", \"description\": \"用户反馈（2026-09-05，TS-031 控制台验收）：右上预览的碰撞拖拽**点击框框后跳到左上角、之后无法继续操作**（具体 bug，待复现修复：事件/坐标换算或指针状态导致起点丢失）。已确认方向：(a) 预览区底部提供工具栏按钮（含“遮罩”按钮），点“遮罩”进入遮罩框编辑；(b) 遮罩=围绕建筑的**多边形顶点编辑**（拖拽顶点、加/删点），坐标以建筑自身为基准、**归一化 0..1** 存储（可选新字段，如 visual.mask_polygon=[[x,y],...]），后续素材/建筑放入地图按比例缩放应用；物理碰撞（矩形/圆/胶囊，宽度高度偏移）保持现机制并同样按比例展示，二者并存；(c) 修复现有碰撞编辑器展示与交互问题（含跳到左上角 bug、手柄可操作性、数值与表单联动、保存原子化）。分类：工具/Web 控制台；素材与碰撞编辑。关联：TS-031（review，同 owner dsh_map_dev）。验收：碰撞框点击后不跳位、可连续拖拽与保存；遮罩模式可编辑多边形并正确显示/保存/读回；归一化坐标字段有校验与测试。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"preview_toolbar\", \"collision_mask_editor\", \"building_mask_polygon\"], \"delivery_commit\": \"88e5e8c478f8f2799998a2705609adc29dd75274\", \"delivery_tests\": \"PM unittest 66 passed (mask polygon validation/roundtrip, mounts parse/match/filter, prior 49); server --check ok; node --check app.js ok. Preview drag jump fixed (root cause: stale cached stage rect + full re-render per move; now live rect + grab-offset follow + lightweight update, pointer capture cleanup). Mask editor: toolbar 碰撞/遮罩/说明, visual.mask_polygon normalized 0..1 (3..64 pts) with vertex add/drag/remove, save atomic. Manual browser acceptance pending.\", \"updated_at\": \"2026-09-05T15:06:29+08:00\", \"continues_from\": [\"TS-031\", \"TS-032\", \"TS-033\"]}, {\"id\": \"TS-036\", \"project_key\": \"project_0001\", \"title\": \"场景扫描采集素材挂载状态与筛选\", \"description\": \"用户需求（2026-09-05，TS-032 延续）：点击“扫描当前编辑场景”时，素材库加载出**该场景实际引用**的素材并赋予“挂载状态”：1) 素材被场景加载→状态“已挂载”；2) 标识挂载到的具体场景（scene_path）；3) 素材库新增按状态（全部/已挂载/未挂载）及场景的筛选。匹配规则（用户选 A）：场景采集到的资源（res:// 路径：Sprite 贴图、AnimatedSprite 帧、TileSet/其余资源）按**文件路径/文件名自动匹配**素材库 catalog 条目，无需手工绑定。实现拆两仓：temp-02/addons/tiny_swords_pm（pm_dock 扫描扩展：遍历当前场景实际引用的资源与所属 scene_file_path，上传“resources:[{path,type}]”；不改场景/不入库缓存）；TinySwordsPM（server 收存挂载映射（随 data/scans/<key>.json 或独立挂载文件、原子写）、web 素材库状态字段/场景标识与筛选、tools/asset_preview 复用路径匹配、单测）。分类：工具/Web 控制台；扫描与素材管理。关联：TS-032（review，同 owner dsh_map_dev）。验收：扫描 temp-02 场景后，素材库出现“已挂载(场景路径)”状态并可筛选；重复扫描覆盖不残留旧场景挂载；对 catalog 未收录的路径给出未匹配提示。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"scan_resource_mount\", \"asset_mount_state\"], \"delivery_commit\": \"88e5e8c478f8f2799998a2705609adc29dd75274\", \"delivery_tests\": \"PM unittest 66 passed incl mounts; plugin commit 04f4111 (temp-02 addon scene_resources.gd + pm_dock scan resources, no editor run). /api/mounts ok; library shows mounted badge+scene and filters by status/scene (combined w/ project/all/retired); unmatch count notice. Godot plugin resource collection needs editor reload + manual scene scan acceptance (uid sidecar generated on editor open).\", \"updated_at\": \"2026-09-05T14:57:28+08:00\", \"continues_from\": [\"TS-031\", \"TS-032\", \"TS-033\"]}, {\"id\": \"TS-037\", \"project_key\": \"project_0001\", \"title\": \"控制台预览面板可拖拽调宽与放大编辑\", \"description\": \"用户需求（2026-09-05）：控制台右侧实时预览/编辑面板（碰撞与遮罩编辑所在栏）希望可拖拽调宽并可放大成可移动编辑窗，便于编辑。实现：右栏左缘拖拽分隔条改宽（记住宽度）+ 放大按钮切换浮层编辑窗（可拖动标题栏移动、右下角缩放，可返回）。范围 TinySwordsPM web（app.js/styles/index）与工具/测试。分类：工具/Web 控制台；关联 TS-031/035（同 owner review）。交付：拖拽调宽不破布局、放大窗可移动缩放、保存/遮罩交互保留。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"preview_panel_resize\"], \"delivery_commit\": \"e7a05e36cc97ca1faba5688df98e929a8c851424\", \"delivery_tests\": \"A1 accepted: preview art-fit geometry anchored to asset, divider drag width memory, magnify floating editor; node+unittest66+server check green.\", \"updated_at\": \"2026-09-05T14:57:42+08:00\", \"continues_from\": [\"TS-031\", \"TS-032\", \"TS-033\", \"TS-035\", \"TS-036\"]}, {\"id\": \"TS-038\", \"project_key\": \"project_0001\", \"title\": \"遮罩在游戏内作为视觉遮挡层生效\", \"description\": \"用户需求（2026-09-05，承接 TS-035 的 visual.mask_polygon 数据）：遮罩数据已能在控制台编辑保存，游戏内尚未消费。已确认语义=视觉遮挡层（非阻挡）：带 mask_polygon 的建筑，单位处于其多边形覆盖区（建筑身后区域）时被建筑盖住、不叠在建筑图之上；点击/命中仍用现有碰撞/图元规则。需要先在 temp-02 摸清 runtime 建筑与 worker/soldier 的 y-sort/绘制顺序机制，选最小可靠方案（如按单位脚点是否落在多边形内且位于建筑后侧，动态调整其绘制次序/渲染子层），不改物理阻挡；归一化坐标按建筑贴图视觉盒比例换算（与 TS-035 约定一致）。分类：玩法/视觉表现与建筑；关联 TS-035（数据）、TS-026（soldier/worker）。交付：多站位遮挡表现正确、既有采集/集结与测试不回归、渲染对比或单测记录。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"building_visual_occlusion\", \"mask_polygon_game\"], \"delivery_commit\": \"02f1018a01af0fdea1de276a70d127bc4e857904\", \"delivery_tests\": \"TS-038 v3 polygon-clip occlusion accepted by user (F6): visual_occlusion 29/0, runtime collision 40/0, regressions green.\", \"updated_at\": \"2026-09-05T15:53:31+08:00\", \"continues_from\": [\"TS-004\", \"TS-026\"]}, {\"id\": \"TS-039\", \"project_key\": \"project_0001\", \"title\": \"控制台建筑碰撞编辑在游戏内生效为阻挡区(含兵种)\", \"description\": \"用户需求(2026-09-05):控制台编辑建筑碰撞后,游戏内以该区域为阻挡区,工人与兵种都不能通过/进入。缺口:runtime建筑(house/barracks/tower/archery)在PM无登记;castle已登记但游戏未消费building记录碰撞;兵种collision 0不被挡。实现:TinySwordsPM侧补runtime建筑记录(runtime_key、默认碰撞=现常量、rally96、mask空)入bindings与快照导出(原子幂等);temp-02侧建房/城堡按快照记录建碰撞形状(rect/circle/capsule,offset语义足底锚定),兵种改layer2/mask15。遮罩维持视觉遮挡层(TS-038)。关联TS-001/002、TS-031/035、TS-038。验收:改碰撞-拉快照-F6,工人与兵种均被拦。\", \"status\": \"done\", \"owner\": \"dsh_map_dev\", \"scopes\": [\"runtime_building_registry\", \"building_collision_runtime\", \"troop_collision\"], \"delivery_commit\": \"de63f7c2b6638fc3e2c7582b2cafe66ecd39dc35\", \"delivery_tests\": \"TS-039 accepted: runtime building records + snapshot-driven collision blocks workers and troops; game commit 02f1018; PM registry/contract/tooling de63f7c; runtime tests 40/0 + regressions green.\", \"updated_at\": \"2026-09-05T15:52:28+08:00\", \"continues_from\": [\"TS-031\", \"TS-032\", \"TS-033\", \"TS-035\", \"TS-036\"]}, {\"id\": \"TS-040\", \"project_key\": \"project_0001\", \"title\": \"素材管理台整合任务进度与详情\", \"description\": \"用户已确认：参照旧素材与任务索引，在新素材管理台加入任务入口、状态统计、搜索筛选、完整详情和刷新；使用现有任务接口，不迁入旧任务，不更改认领流程。分类：工具/Web 控制台。决策：docs/decisions/adr_007_task_dashboard.md\", \"status\": \"done\", \"owner\": \"codex_task_dashboard\", \"scopes\": [\"pm_task_dashboard\"], \"delivery_commit\": \"59b22e0afb5cd112c9afa0d341c1c50fec5bbe13\", \"delivery_tests\": \"72 Python tests passed; node syntax and server check passed; browser verified counts, 55% done-only completion, TS-004 search/delivery, status-filter empty state and readable screenshot. Original dirty checkout preserved; independent console port 8766.\", \"updated_at\": \"2026-09-08T07:10:54+00:00\", \"continues_from\": []}, {\"id\": \"TS-041\", \"project_key\": \"project_0001\", \"title\": \"教程素材索引原框架整合任务进度\", \"description\": \"用户纠正目标为 godot-game-learn-main：在原网页导航、米色绿色样式框架中新增任务进度与详情，使用 TinySwordsPM 任务源，保持素材/教程/词典。分类：工具/素材索引。决策：godot-game-learn-main/docs/decisions/adr_001_task_dashboard.md。TS-040为此前错误目标实现，不代表本任务验收。\", \"status\": \"done\", \"owner\": \"codex_task_dashboard\", \"scopes\": [\"tutorial_task_dashboard\", \"tutorial_navigation\"], \"delivery_commit\": \"85b6da076a599e9dfd7d2c20c004a81053b4aff6\", \"delivery_tests\": \"PASS: asset index/catalog checks (841 files), catalog, animation, glossary four-view routing, detail resize, node syntax; task HTTP fresh-read/read-only/malformed-data tests. Browser: existing paper/green theme, task view, asset selection and action switch. Uses canonical local TinySwordsPM tasks; no auto Git sync.\", \"updated_at\": \"2026-09-05T14:20:52+00:00\", \"continues_from\": []}, {\"id\": \"TS-042\", \"project_key\": \"project_0001\", \"title\": \"任务状态配色与详情表单化优化\", \"description\": \"用户反馈（2026-09-05）：任务列表中的未认领、已完成等状态需要用不同颜色区分；右侧详情按表单结构规划。沿用 godot-game-learn-main 原米色/绿色 UI，完善五种状态色、状态徽标、负责人提示、详情分组和只读表单字段，并保持搜索筛选与移动端布局。接续 TS-041，分类：工具/素材索引；决策追加于 docs/decisions/adr_001_task_dashboard.md。\", \"status\": \"done\", \"owner\": \"codex_task_dashboard\", \"scopes\": [\"tutorial_task_dashboard\"], \"delivery_commit\": \"413b0e4d31ee453af57dbe1c3d9642b2d14715e2\", \"delivery_tests\": \"PASS: task_dashboard.js syntax; four-view routing; detail resize; animation regression; static contract verifies gray unclaimed states, green completed cards, five status badges, real readonly input/textarea fields, responsive layout. User visually reviewed 8767 page and accepted on 2026-09-05. Asset catalog check still reports pre-existing line-ending mismatch in isolated clone; related catalog/tutorial files unchanged.\", \"updated_at\": \"2026-09-05T14:01:03+00:00\", \"continues_from\": [\"TS-041\"]}, {\"id\": \"TS-043\", \"project_key\": \"project_0001\", \"title\": \"树木新增受击抖动效果\", \"description\": \"用户需求（2026-09-05）：为树木增加受击抖动效果。目标工程：map-build-temp-01/temp-02。分类：交互/资源受击反馈。验收：每次有效砍击触发短暂可见抖动，结束后恢复原位，不产生累计位移；保持三次完整砍击后变树桩并掉落 1 木材的规则，碰撞与采集流程不受视觉抖动影响。抖动幅度和时长为实施时可调视觉参数。实施前在目标工程 docs/decisions/ 创建决策记录并回填路径，更新相应玩法基准与回归测试。决策记录：temp-02/docs/decisions/adr_011_tree_hit_shake.md。验收反馈（2026-09-06）：原版树木在工人砍击动作结束后才抖动，体感有延迟；已改为单次挥斧 55% 命中帧立即触发。后续反馈要求动作快速且短暂，抖动压缩至 0.08 秒并使用快速加减速回弹；完整挥斧和资源结算时序不变。\", \"status\": \"done\", \"owner\": \"codex_ts043\", \"scopes\": [\"forest\", \"resource_hit_feedback\"], \"delivery_commit\": \"e0e8a31e39e5e4fb9810163860770a6e44253197\", \"delivery_tests\": \"PASS: tree shake remains aligned with axe impact at frame 33/60 (55 percent), now uses a fast easing curve and completes in 0.08 seconds while full swing settlement remains frame 60; test_tree_hit_feedback.gd 18 assertions 0 failures; OpenGL real-render saved rest/shaking/recovered frames; git diff --check. Existing mainline regression results are unchanged from the prior TS-043 review record. Environment emits root-certificate/log/editor-settings permission warnings.\", \"updated_at\": \"2026-09-06T13:09:00+00:00\", \"continues_from\": []}, {\"id\": \"TS-044\", \"project_key\": \"project_0001\", \"title\": \"羊受击红色闪烁并改为攻击两次掉肉\", \"description\": \"用户需求（2026-09-05）：为羊增加受击红色闪烁效果，并改为需要两次有效攻击才能变成肉。目标工程：map-build-temp-01/temp-02。分类：玩法/食物采集；交互/资源受击反馈。验收：有效命中触发红色闪烁；第一次命中后羊仍存活且不掉肉，第二次命中后变成肉，只掉落 1 食物；闪烁结束恢复原色；保持搬运、城堡交付和繁殖流程。用户确认（2026-09-06）：受击次数保存在羊自身，中断或换另一名工人后不重置；第二次命中先播放快速红色闪烁，再变成肉并掉落 1 食物。范围协调（2026-09-06）：利用 sheep_flock 返回的待生效肉块维持致命攻击者的领取权，不修改 worker.gd，因此不进入 TS-022 占用的 worker_jobs 范围。验收返工（2026-09-06）：用户发现第二击后、肉块显示前，工人会切换攻击旁边的羊；修正为当前工人预约对应肉块，红闪期间肉块不可见、不可枚举、不可拾取，红闪完成后直接进入拾取流程。第二次返工（2026-09-07）：用户要求缩短受击动作与闪红反馈的间隙；红闪前移到攻击动画 50% 命中帧，完整攻击仍在 1 秒时结算，命中帧后取消不增加命中次数。第三次返工（2026-09-07）：第一次攻击仍在 50% 闪红；第二次致命攻击的 0.10 秒闪红对齐攻击结算末端，闪红完成信号立即显示已预约肉块，消除恢复原色后的等待。决策记录：temp-02/docs/decisions/adr_012_sheep_two_hit_feedback.md。\", \"status\": \"done\", \"owner\": \"codex_ts044\", \"scopes\": [\"sheep_interaction\", \"resource_hit_feedback\"], \"delivery_commit\": \"3c5961a07f32c249fc35c668bac4eabc336c2284\", \"delivery_tests\": \"Third acceptance rework was not automatically tested or rendered at the user\'s explicit request; user will perform validation. Change aligns the lethal 0.10-second red flash with attack settlement so its completion signal immediately activates the reserved meat. Previous verified baseline: test_food_jobs 51 assertions with 8 existing mainline failures; sheep_hit_feedback 14/0, sheep_flock 43/0, tree_hit_feedback 18/0; unrelated worker_collisions 1 failure, mining_cycle 11 failures, wood_jobs existing failures remain recorded.\", \"updated_at\": \"2026-09-07T14:10:02+00:00\", \"continues_from\": []}, {\"id\": \"TS-045\", \"project_key\": \"project_0001\", \"title\": \"城镇道路拥堵与单位寻路方案优化\", \"description\": \"用户提出在城镇道路拥挤、全图约一两百个活动单位且工人约几十个时继续优化 Warcraft 风格单位通行。基于 TS-028 已实现的共享静态导航、空间网格和分帧寻路预算，补充城镇交通层：道路采用低基础成本与平滑变化的拥堵成本，避免瞬时改道震荡；宽路提供稳定靠右/固定侧避让与减速跟随；城门、桥梁、窄巷等单宽瓶颈采用方向锁、等待队列、公平换向和通道外等待区，不预约整条路径；仓库、矿点、工地等共同目标提供接近/工作/等待槽位，禁止多人争抢单一坐标；卡死按减速、侧移、让行、后退、冷却后重寻路、替代落点分级恢复；调度优先近距离和区域化工人，并错峰派发。实施前需同步并协调 TS-029 正在占用的 worker_navigation/movement_performance 范围，不修改其认领内容；本任务不放开单位物理穿透，软重叠仍需另行确认。验收目标：双向宽路不长期顶死或左右抖动；窄口双向流可公平通过且不死锁；几十名工人访问共同建筑不堆叠；拥堵时无大规模重复寻路尖峰；提供道路、路口/窄口、共同目标和几十单位压力场景供用户实际体验。分类：玩法/城镇交通；架构/单位移动；性能/拥堵与寻路。关联任务：TS-028、TS-029、TS-030；决策记录：实施时扩展 map-build-temp-01/temp-02/docs/decisions/adr_001_unit_movement.md。\", \"status\": \"claimed\", \"owner\": \"codex_local_multiselect\", \"scopes\": [\"town_traffic\", \"worker_navigation\", \"bottleneck_routing\", \"resource_access_slots\", \"movement_performance\"], \"delivery_commit\": null, \"delivery_tests\": null, \"updated_at\": \"2026-09-08T01:01:17+00:00\", \"continues_from\": [\"TS-022\", \"TS-023\", \"TS-025\", \"TS-028\", \"TS-029\"]}, {\"id\": \"TS-046\", \"project_key\": \"project_0001\", \"title\": \"正式哥布林怪物与窝点素材接入\", \"description\": \"用户反馈（2026-09-09）：当前怪物与窝点仍使用临时深红战士和黑色兵营，应改用素材引用项目已经索引的 Tiny Swords (Update 010)/Factions/Goblins 正式资源。素材证据：asset-index ID 485 Torch_Red.png（1344x960）及 ID 484 Aseprite 源文件用于怪物 idle/run/attack 等动画；ID 452 Goblin_House.png（128x192）作为基础窝点；ID 460 Wood_Tower_Red.png（1024x192，四帧图集）保留为强化窝点/塔的候选，不直接按静态整图显示。实施时复制所需资源到 temp-02/res://assets/enemies/goblins/，建立明确帧表和 SpriteFrames，移除临时 tint 与黑色兵营依赖；保持现有怪物数值、寻路、战斗组和三轮生成契约。验收：游戏内怪物为真实红色哥布林火炬兵并正常播放待机/跑动/攻击；三个窝点显示哥布林建筑且透明区域、Y排序、碰撞和出怪点正确；素材来源和索引 ID 可追踪。分类：美术接入/敌人视觉。决策：temp-02/docs/decisions/adr_017_goblin_assets_distance_and_health_feedback.md。仅登记，待确认后按任务流程认领。\", \"status\": \"done\", \"owner\": \"codex_ts046\", \"scopes\": [\"monster_visual_assets\", \"monster_nest_visual\", \"asset_catalog_binding\"], \"delivery_commit\": \"beead01eba02b059dc7bde7aaa6568cf9c6cede3\", \"delivery_tests\": \"Godot 4.7.2：test_monster_assault_integration、test_monster_wave_controller、test_troop_combat、test_unit_production_integration、test_visual_occlusion、test_unit_purchase 均退出码0且日志无ERROR/FAIL；render_monster_preview 使用OpenGL Compatibility成功生成并人工检查待机/攻击截图。\", \"updated_at\": \"2026-09-09T02:18:26+00:00\", \"continues_from\": []}, {\"id\": \"TS-047\", \"project_key\": \"project_0001\", \"title\": \"南部战场扩展、窝点远移与首轮准备时间调整\", \"description\": \"用户反馈（2026-09-09）：当前怪物窝点离主城过近，需要向地图下方移动几个屏幕框，为生产和布防留出更充足空间；第一波准备阶段也需适当拉长。规划目标：向南扩展可行走地图约 3 个 1152x648 基准视口高度，三个窝点基线放在主城下方约 2.5至3个视口高度处，并保留中间连续可通行战场；相机边界、小地图覆盖、寻路 bounds、障碍和建筑放置边界同步扩展。第一波准备时间暂以 60 秒为候选值（当前 20 秒），后续 45 秒轮次间隔和每轮27只总契约不在本任务默认改动；用户原话中的“第一波稍微拉长”语义和精确秒数须在开工前再次确认。需与正在占用移动/寻路范围的 TS-045 协调，禁止在冲突未解决时认领。验收：主城与最近窝点之间至少保留约2.5屏纵向准备区；三窝点均在地图内、彼此分离且出怪点可行走；相机和小地图能完整抵达/显示新南部区域；27只怪物均可找到主城路径；首轮倒计时显示确认后的新时长。分类：地图/波次节奏。决策：temp-02/docs/decisions/adr_017_goblin_assets_distance_and_health_feedback.md。仅登记，待确认后按任务流程认领。\", \"status\": \"done\", \"owner\": \"codex_ts046\", \"scopes\": [\"world_map_south_expansion\", \"monster_nest_placement\", \"wave_timing\", \"minimap_bounds\"], \"delivery_commit\": \"9ee8b26c80864e35275bf1de08a595bfd7b199c8\", \"delivery_tests\": \"Godot 4.7.2：test_monster_assault_integration 验证三窝点距主城至少1296px、地图南扩至少三屏、27只怪物可生成并向主城移动；test_monster_wave_controller 验证首轮60秒及三轮27只；test_camera_safe_bounds 验证扩展后相机/小地图边界；另有 troop_combat、visual_occlusion、unit_purchase 回归，全部退出码0且日志无ERROR/FAIL。\", \"updated_at\": \"2026-09-09T02:20:08+00:00\", \"continues_from\": []}, {\"id\": \"TS-048\", \"project_key\": \"project_0001\", \"title\": \"主城与战斗单位受击反馈及条件血条\", \"description\": \"用户反馈（2026-09-09）：主城和战斗单位受击缺少直观反馈与血量展示。规划：玩家兵种与怪物头顶增加世界空间血条；满血默认隐藏，首次受伤立即显示并实时更新，治疗恢复满血后再次隐藏，死亡随单位清理；主城作为核心目标显示生命数值/血条并与现有1500生命和失败状态同步。有效伤害触发短促受击闪色或回弹，反馈不得修改碰撞、寻路、攻击结算或Y排序；连续攻击时避免重复 Tween 累积和颜色残留。验收：满血小兵无血条；受击同帧出现且比例准确；治疗至满血隐藏；玩家兵种和哥布林行为一致；主城受击能看到生命下降，归零显示主城失守；对象释放后无残留 UI/RID。增加逻辑专项和真实渲染对比。分类：战斗交互/生命UI。决策：temp-02/docs/decisions/adr_017_goblin_assets_distance_and_health_feedback.md。仅登记，待确认后按任务流程认领。\", \"status\": \"done\", \"owner\": \"codex_ts046\", \"scopes\": [\"combat_health_bar\", \"combat_hit_feedback\", \"castle_health_ui\", \"monster_health_ui\"], \"delivery_commit\": \"9ee8b26c80864e35275bf1de08a595bfd7b199c8\", \"delivery_tests\": \"Godot 4.7.2：test_monster_assault_integration、test_monster_wave_controller、test_camera_safe_bounds、test_troop_combat、test_visual_occlusion、test_unit_purchase 均退出码0且日志无ERROR/FAIL；OpenGL Compatibility真实渲染确认条件血条、主城常驻血条和HUD生命数值。\", \"updated_at\": \"2026-09-09T02:18:04+00:00\", \"continues_from\": [\"TS-046\"]}, {\"id\": \"TS-049\", \"project_key\": \"project_0001\", \"title\": \"非工人战斗单位沿途索敌与临时交战\", \"description\": \"用户需求（2026-09-09）：第一版本为所有非工人战斗单位增加索敌距离与沿途自动交战能力，覆盖当前玩家兵种和野怪，工人明确排除。单位在移动、进攻或执行既有目标期间持续检查索敌范围内的有效敌对战斗单位；例如野怪原本以主城等建筑为进攻目的地，途中发现玩家兵种后应暂停原行军，转而接近并攻击该兵种。临时目标死亡、失效或脱离允许追击范围后，单位恢复原始命令或原建筑目标，不能永久丢失波次进攻目标，也不能在多个候选间逐帧抖动切换。第一版本不增加‘特定新兵种始终优先建筑’的单位级优先级配置，该能力留待后续独立规划；工人仍沿用现有生产与采集逻辑，不参与自动索敌。索敌半径、检查频率、目标锁定与脱离距离应集中为可调战斗参数，具体默认距离在实施前结合近战/远程攻击距离和实际地图比例确认。验收：玩家当前各战斗兵种会主动攻击进入索敌范围的野怪；进攻建筑途中的野怪会停下攻击进入索敌范围的玩家兵种；范围外敌人不会无条件拉走单位；临时交战结束后恢复原目标；工人行为不变；多人混战下目标稳定且无明显全量扫描性能尖峰。分类：玩法/战斗AI与目标选择；性能/索敌查询。关联：ADR-014、ADR-016、TS-045、TS-048。决策记录：实施时新建 temp-02/docs/decisions/adr_018_combat_target_acquisition.md。仅登记，不认领、不实施。\", \"status\": \"done\", \"owner\": \"codex_ts049\", \"scopes\": [\"combat_target_acquisition\", \"troop_aggro\", \"monster_aggro\", \"combat_order_resume\"], \"delivery_commit\": \"fa9bf07b5b330bca0993c473e45dfea78e66e263\", \"delivery_tests\": \"PASS Godot 4.7.2: test_troop_combat, test_monster_assault_integration, test_monster_wave_controller, test_unit_production_integration, test_unit_purchase, test_direct_commands and test_sheep_flock all 0 failures, git diff --check passed. Existing unrelated baseline failures remain: worker_collisions 1, mining_cycle 10, food_jobs 8, wood_jobs 9, game_hud existing title/BodyScroll failure and hang. Headless environment cannot write user logs/editor settings and reports existing exit-time RID leaks.\", \"updated_at\": \"2026-09-11T03:32:32+00:00\", \"continues_from\": []}, {\"id\": \"TS-050\", \"project_key\": \"project_0001\", \"title\": \"建筑世界血条移至顶部并按受伤状态显隐\", \"description\": \"用户需求（2026-09-09）：所有具有生命值的建筑，其世界空间血条放在建筑视觉上方；满血时默认隐藏，生命低于最大值时立即显示，恢复满血后再次隐藏。现有主城血条需取消 always_visible，并由城门下方迁移至建筑顶部；运行时房屋、兵营、箭塔、靶场等建筑应复用同一显隐规则和 PM visual.health_bar_offset_y / health_bar_width 配置，不用硬编码一个偏移覆盖不同尺寸。顶部 HUD 中的主城生命数值属于情报展示，本任务默认保留，不等同世界血条。需建立统一的建筑当前/最大生命同步入口，为后续修缮复用；不在本任务增加修缮按钮、木材扣费或新的怪物目标优先级。验收：满血主城和已完工建筑不显示世界血条；受到有效伤害同帧在建筑顶部显示且比例准确；恢复满血隐藏；血条不被建筑贴图遮挡、不跟随错误节点漂移；建筑销毁后无残留 UI。分类：交互/建筑生命反馈；架构/建筑生命状态。关联：TS-048、TS-051。决策记录：实施时新建 temp-02/docs/decisions/adr_019_building_health_and_repair.md。仅登记，不认领、不实施。\", \"status\": \"done\", \"owner\": \"codex_ts050\", \"scopes\": [\"building_health_bar\", \"building_health_state\", \"castle_health_ui\"], \"delivery_commit\": \"c65f57d4bdc1cd4196783d9de53167dafe6b1bb0\", \"delivery_tests\": \"PASS Godot 4.7.2: test_monster_assault_integration, test_unit_purchase, test_runtime_building_collision, test_visual_occlusion all 0 failures; test_troop_combat and test_monster_wave_controller exit 0; real renderer preview verified castle top conditional health bar. Existing sandbox user-log/root-CA and exit RID warnings remain.\", \"updated_at\": \"2026-09-11T04:53:39+00:00\", \"continues_from\": []}, {\"id\": \"TS-051\", \"project_key\": \"project_0001\", \"title\": \"工人修缮受损建筑与木材成本结算\", \"description\": \"用户于 2026-09-09 确认修缮规则：必须先选中一名空闲工人，再选择仍存活且生命未满的建筑，右侧命令栏才显示可执行‘修缮’入口；满血或已销毁建筑不能修缮、不能扣费。工人到达建筑接近点后使用锤子持续敲打。修缮进度直接采用建筑当前生命百分比，不建立独立完成倒计时；满损建筑基础修缮时间暂定 10 秒，恢复速率按最大生命换算。修缮期间建筑继续正常受击，伤害实时降低生命与显示进度，但不自动中断工人的修缮任务。木材按实际恢复生命持续结算，累计公式为 ceil(建筑建造木材成本 × 实际恢复生命 / 最大生命)，因此修缮期间新增伤害不会被免费恢复；木材不足时不得透支，未开始时拒绝派工，进行中不足时暂停并明确提示。建筑受损后优先接入项目已有着火/烟雾动画素材，默认按生命阈值呈现轻重受损层级，满血后关闭特效、恢复完整建筑外观并隐藏血条。建筑或工人失效时停止任务，不重复扣费。复用 TS-050 的统一建筑生命状态，不扩展怪物目标优先级。实施涉及工人移动与建筑接近点，须与 TS-045 协调；TS-050 已交付 review，认领时按任务工作流处理依赖与范围。验收覆盖选人再选建筑、入口显隐、到达与锤击动画、按生命百分比修复、受击并行、逐步木材结算、资源不足、火焰/烟雾显隐、完成回满、对象失效和多目标竞争。分类：玩法/建筑修缮；经济/木材结算；交互/建筑命令。依赖：TS-050；关联：TS-045、BUILD-007～009。决策记录：扩展 temp-02/docs/decisions/adr_019_building_health_and_repair.md。规则已确认，可进入范围协调与认领。\", \"status\": \"done\", \"owner\": \"sasaki\", \"scopes\": [\"building_repair\", \"worker_repair_job\", \"repair_economy\", \"building_command_ui\"], \"delivery_commit\": \"f940859bb154436af7e242cba99418cbbef72286\", \"delivery_tests\": \"test_building_repair.gd 14/14 pass; test_cheat_spawn.gd 19/19 pass; monster assault regression 0 failures\", \"updated_at\": \"2026-09-12T04:52:57+00:00\", \"continues_from\": []}, {\"id\": \"TS-052\", \"project_key\": \"project_0001\", \"title\": \"战斗兵种属性配置与科技成长接口\", \"description\": \"用户于 2026-09-09 确认战斗配置与科技方向。第一阶段让 soldier、archer、priest、spearman 的最大生命、攻击或治疗强度、攻击间隔、攻击距离、索敌距离、脱离距离和移动速度采用‘代码默认值 + 有效 TinySwordsPM 配置覆盖’，缺失或损坏配置安全回退，工人排除。第二阶段建立数据驱动的百分比倍率科技；科技对全军中符合适用兵种标签的所有单位生效，同时更新已经生产和之后新训练的单位，但不同科技不跨兵种误加：箭术类只作用全部 archer，甲胄类只作用全部 soldier，牧师强化只作用全部 priest；spearman 预留独立适用标签。首版预设均为一次性购买：箭术使弓手伤害 +10%，甲胄使战士防御 +10%，圣愈使牧师回复量 +10%；具体费用与倍率由配置承载，先取与当前经济节奏相符的保守默认值，整体测试验收时再调整。重复购买不得重复叠加。攻速、防御 Buff、持续回血等持续效果只预留结构，不在首版启用，后期单独规划。TS-049 已交付 review 且涉及相同 troop/config 文件，认领时必须按任务工作流协调范围，不覆盖其索敌实现。验收覆盖 PM 覆盖与无效值回退、兵种标签隔离、百分比倍率、现有/新兵同步、一次性购买保护、弓手伤害/战士防御/牧师回复实效及存量默认行为不变。分类：架构/战斗配置；玩法/军事科技成长。关联：TS-002、TS-013、TS-049、ADR-010、ADR-018。决策记录：实施时新建 temp-02/docs/decisions/adr_023_combat_stats_and_technology.md。规则已确认，可进入范围协调与认领。\", \"status\": \"done\", \"owner\": \"codex_unit_evolution\", \"scopes\": [\"combat_unit_stats_config\", \"pm_config\", \"combat_technology\", \"unit_progression\"], \"delivery_commit\": \"e04341f393d043a4bc802f75c4a8c367fe3516aa\", \"delivery_tests\": \"PASS: TS-052 Godot test_combat_technology (18 checks), test_technology_tree, test_troop_combat, test_unit_purchase RESULT 0 failures after rebasing by cherry-pick onto latest main. PM config commit 584e3e5: test_combat_config 5/5 and node --check web/app.js pass. PM full suite 81/82 with pre-existing building_0004 rally_radius expected 96 vs accepted config 200. Required resource regressions unchanged: sheep 43/0; existing worker collision 1, mining 10, food 8, wood 9 failures. Git diff checks passed; Godot environment still reports existing user log/root certificate/RID exit warnings.\", \"updated_at\": \"2026-09-12T14:06:07+00:00\", \"continues_from\": [\"TS-061\"]}, {\"id\": \"TS-053\", \"project_key\": \"project_0001\", \"title\": \"怪物攻击运行时建筑与波次参数管理\", \"description\": \"用户追加需求（2026-09-09）：兵营、靶场、房屋、箭塔等运行时玩家建筑不仅要初始化生命，还必须能被进攻中的怪物发现、锁定、接近并攻击；建筑受击统一扣减 TS-050 的 health/max_health，受损显示顶部血条，归零清理建筑、碰撞、血条与生产队列，怪物随后恢复原主城目标。工人和中立资源点不作为怪物建筑目标。怪物仍可在沿途临时攻击进入索敌范围的玩家战斗单位，单位与建筑候选按距离稳定选择。另将总波数、每窝每波数量、首轮等待秒数、轮间等待秒数、同波出怪间隔纳入 TinySwordsPM 项目配置页面、项目快照和 Godot 有效配置读取；缺失或损坏值回退现有 3波/每窝3只/60秒/45秒/0.6秒。验收覆盖运行时建筑受击与销毁、血条同步、生产退款/导航清理、交战后恢复攻城，以及 PM 编辑字段、快照导出、Godot 读取和无效值回退。分类：玩法/怪物建筑目标；架构/波次配置；工具/项目参数管理。关联：TS-049、TS-050、TS-051、ADR-016、ADR-018、ADR-019。决策记录：更新 temp-02/docs/decisions/adr_019_building_health_and_repair.md，并新增 temp-02/docs/decisions/adr_020_monster_wave_configuration.md。\", \"status\": \"done\", \"owner\": \"codex_ts050\", \"scopes\": [\"monster_building_targeting\", \"runtime_building_damage\", \"monster_wave_config\", \"pm_wave_config\"], \"delivery_commit\": \"68656246ecfe2e8fd50040dccc3a28456d481437\", \"delivery_tests\": \"Godot TS-053: test_unit_purchase 0 failures; test_monster_wave_controller 0 failures; assault/troop/runtime-collision/occlusion/production regressions passed. Resource regressions unchanged from accepted baseline. PM: monster-wave tests 5/5, node syntax and server check passed; full suite 76/77 with pre-existing building_0004 rally_radius 200 vs legacy test expected 96.\", \"updated_at\": \"2026-09-12T07:25:25+00:00\", \"continues_from\": [\"TS-050\"]}, {\"id\": \"TS-054\", \"project_key\": \"project_0001\", \"title\": \"战士战斗 MVP：独立地图与战斗基础\", \"description\": \"用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段1/5。独立平铺测试地图，通过 F6 运行，不改变正式地图/启动场景。1名战士、5只共用模板且固定原地反击的小怪。左键选中，右键地面移动，右键怪物靠近持续攻击，新指令打断旧任务。双方伤害 max(1,攻击-防御)，无随机。战士死亡显示重新挑战，重置全部角色和本局；清怪显示挑战完成及重试。头顶血条。验收完整胜败重试、距离/取消/单次死亡、UI输入拦截及现有资源回归。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。\", \"status\": \"done\", \"owner\": \"codex_warrior_mvp\", \"scopes\": [\"mvp_arena\", \"mvp_combat\", \"mvp_hud\"], \"delivery_commit\": \"3c4d51132b00336bc581f77d60ee50c0a141c7e5\", \"delivery_tests\": \"Implementation 5c06f7d50ce03ceb4d5e36baac98a7b61e7f0c47. Godot 4.7.2 import exit0; MVP32 checks0 failures incl viewport input, movement, stationary retaliation, win/death/retry; OpenGL screenshot inspected; diff-check PASS. Unmodified same-commit baseline matches: collisions1/mining10/food8/wood9 failures; HUD missing BodyScroll and35s timeout. Sheep43 assertions0 failures, technology/purchase/troop-combat exit0. Some old suites report DummyRenderer RID leaks; not all-regressions-pass. See docs/warrior_mvp.md. Await user stage1 acceptance; TS-055..058 not started.\", \"updated_at\": \"2026-09-09T08:25:34+00:00\", \"continues_from\": []}, {\"id\": \"TS-055\", \"project_key\": \"project_0001\", \"title\": \"战士战斗 MVP：经验等级与属性成长\", \"description\": \"用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段2/5。依赖阶段1验收。击杀一次结算怪物经验，命中不加；上限3级，5怪经验使1级升至3级；逐级经验表递增、保留溢出、满级提示。生命/攻击/防御/攻击间隔/移动速度/每秒回复支持基础与等级成长及上下限。升级只补生命上限增量，持续回血包括战斗、不超上限。单选右栏显示等级经验及六属性，升级提示。不做跨局存档，重试重置。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-054，仅前置验收后开工。\", \"status\": \"done\", \"owner\": \"codex_warrior_mvp\", \"scopes\": [\"mvp_progression\", \"mvp_combat\", \"mvp_hud\"], \"delivery_commit\": \"fb834ddba22cb2f5aa66b158359b83f79e8698fe\", \"delivery_tests\": \"Implementation0f725470f90842ca41dc4f79bed08c7b8b12e275. Godot4.7.2 import exit0; growth37 and MVP32 checks all pass including actual speed/damage/interval, regen/pause, XP/cap/retry. OpenGL1152x648 and864x486 screenshots inspected. Post-merge6865624 retest: same69 pass; sheep/technology/purchase/troop/wave assertions pass. Existing failures retained collisions1/mining10/food8/wood9; HUD BodyScroll null35s timeout; old RID leaks and wave resource-exit warning. diff-check pass. See docs/warrior_mvp.md. Await stage2 acceptance; stage3 not started.\", \"updated_at\": \"2026-09-12T07:56:14+00:00\", \"continues_from\": []}, {\"id\": \"TS-056\", \"project_key\": \"project_0001\", \"title\": \"战士战斗 MVP：编辑器右侧成长插件\", \"description\": \"用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段3/5。依赖阶段2验收。Godot编辑器右侧停靠面板，运行前配置，保存后运行生效。三页：战士六属性及等级预览；等级上限与严格递增经验梯度；小怪生命攻击防御攻击间隔攻击范围击杀经验，5怪共模板。校验、保存、放弃未保存修改；配置长期保留，停用插件游戏仍运行。独立MVP配置，不覆盖PM基础参数；TS-052正式兵种整合另行协调。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-055，仅前置验收后开工。\", \"status\": \"done\", \"owner\": \"codex_warrior_mvp\", \"scopes\": [\"mvp_editor_plugin\", \"mvp_progression_config\"], \"delivery_commit\": \"d9c567e11363509ee7f360bf13977a8b40680c33\", \"delivery_tests\": \"Code8a3bf45e790b894f10bf3506e85561f6866647d1. Godot4.7.2 editor plugin import exit0 noERROR. Dock23+growth37+MVP32 checks all pass (92), including real controls, atomic replace, external-edit rejection and runtime consumption. Three tabs and320px dock rendered/inspected. Existing regressions unchanged: collisions1/mining10/food8/wood9 failures, HUD BodyScroll error35s timeout; sheep/technology/purchase/troop assertions pass with old RID leaks. diff-check pass. TS-055 remains review under user deferral; TS-056 also awaits acceptance. See addons/warrior_growth/README.md.\", \"updated_at\": \"2026-09-12T07:57:54+00:00\", \"continues_from\": [\"TS-055\"]}, {\"id\": \"TS-057\", \"project_key\": \"project_0001\", \"title\": \"战士战斗 MVP：剧情与新手引导\", \"description\": \"用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段4/5。依赖阶段3验收。开场对白→选择战士→移动→攻击小怪→首次升级说明→全部击杀结束对白。对白暂停移动攻击回血，继续恢复；操作目标提示不暂停。UI拦截地图输入，事件驱动推进，重复触发不重复结算，重试清理引导状态。配置和逻辑分离，不扩展经营序章。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-056，仅前置验收后开工。\", \"status\": \"done\", \"owner\": \"codex_warrior_mvp\", \"scopes\": [\"mvp_dialogue\", \"mvp_tutorial\", \"mvp_hud\"], \"delivery_commit\": \"a8d321b8b462f33181fe7cadf5c007269441770b\", \"delivery_tests\": \"Code04cb21b4be03a309677317ee6e18075d1b945eea. Godot4.7.2 tutorial30+dock23+growth37+MVP32=122 checks pass, incl real mouse/combat, pause clocks, last-kill dialogue queue, skip/retry and zero-XP. OpenGL opening/move/upgrade/small-victory inspected. After merge6089fea initial missing global class fixed by editor import; final production-cooldown and unit-production integration pass. Existing collisions1/mining10/food8/wood9 failures and HUD35s timeout retained; old RID leaks retained. diff-check pass. Stages2-4 remain review, no automatic acceptance.\", \"updated_at\": \"2026-09-12T07:59:01+00:00\", \"continues_from\": [\"TS-055\", \"TS-056\"]}, {\"id\": \"TS-058\", \"project_key\": \"project_0001\", \"title\": \"战士战斗 MVP：整体回归与使用说明\", \"description\": \"用户于2026-09-09逐项确认并授权登记、普通提交推送；每阶段交付等验收再推进下一阶段。阶段5/5。依赖阶段4验收。完整胜败试玩、两次升级、配置修改生效、异常配置/连续升级/暂停恢复/重试/UI布局检查；回归碰撞采矿羊群食物伐木科技训练，区分旧失败与新增失败。交付F6路径、插件说明、配置规则、测试报告与提交号，等用户验收，不自动done。 分类：玩法/独立战斗MVP；架构/成长与剧情；工具/编辑器。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。关联TS-052但不认领或改动其正式兵种/PM接口。 前置任务：TS-057，仅前置验收后开工。\", \"status\": \"ready\", \"owner\": null, \"scopes\": [\"mvp_acceptance\"], \"delivery_commit\": null, \"delivery_tests\": null, \"updated_at\": \"2026-09-09T07:09:24+00:00\", \"continues_from\": []}, {\"id\": \"TS-059\", \"project_key\": \"project_0001\", \"title\": \"启动器测试探针适配 restart 参数，修复打开项目解析错误\", \"description\": \"用户报告打开MVP工程时probe_pm_launcher.gd Parse error。Godot --check-only复现第7行父类签名为(String,String,bool=false)，测试覆盖仍为两个参数。仅修复测试探针签名并转发restart，验证解析及相关隔离测试；不修改服务行为、不进入MVP第二阶段。关联TS-019、TS-034、TS-054。分类：缺陷/测试接口兼容。修复记录temp-02/docs/pm_service_launcher.md。用户此前已授权任务及代码普通提交推送，本次为第一阶段验收反馈修复。\", \"status\": \"done\", \"owner\": \"codex_warrior_mvp\", \"scopes\": [\"pm_service_launcher\", \"pm_launcher_restart\"], \"delivery_commit\": \"a28dfe7cf1086e80464a8ec4c4865322ab1405f3\", \"delivery_tests\": \"Godot4.7.2 probe --check-only before exit1 signature mismatch line7; after exit0 no script error. Existing test_missing_directory,test_helper_error_is_shown,test_startup_timeout:3 passed. git diff --check passed. Only probe signature and super restart forwarding changed; no actual service start/restart tests run. MVP remains stage1 review.\", \"updated_at\": \"2026-09-12T08:00:39+00:00\", \"continues_from\": []}, {\"id\": \"TS-060\", \"project_key\": \"project_0001\", \"title\": \"生产按钮改为英雄联盟式径向冷却反馈\", \"description\": \"用户于 2026-09-09 审核并确认径向冷却方案，授权登记、认领及普通推送后实施。训练队列头项生产期间，购买按钮显示覆盖完整图标的灰蓝径向冷却遮罩；每生产一个单位都按该单位自己的完整训练时间连续扫掠一圈，该单位出场后若仍有待产项目，下一单位从零开始新的一圈，不按整数秒重置，不再使用旋转鼠标指针。右上角只显示该兵种尚未生成的数量，不显示剩余时间；剩余大于 1 秒使用稳定深灰蓝遮罩，最后 1 秒降低遮罩透明度但扫掠连续不中断。冷却完成时播放约 0.3～0.45 秒金色双亮边后恢复可点击视觉。保留串行生产、资源与人口结算、阻塞出生点等待及现有命令格素材；视觉状态不能改变生产时序。需为逐单位径向进度、待产数量、末秒透明度、完成反馈和清空队列补充测试。分类：UI/生产反馈；交互/冷却状态。关联：TS-013、TS-014、TS-026。决策记录：temp-02/docs/decisions/adr_022_production_cooldown_ui.md。\", \"status\": \"done\", \"owner\": \"codex_ui_cooldown\", \"scopes\": [\"production_cooldown_ui\", \"production_queue_hud\", \"game_hud\"], \"delivery_commit\": \"6089feaaf938eff7a0c2fda9bfffeb0d04ccbcbe\", \"delivery_tests\": \"Godot 4.7.2: production_cooldown_ui 11/11 passed; unit_production_integration 18/18 passed; production_queue 17/17 passed; unit_purchase 0 failures; real graphical renderer previews inspected for deep and final-second overlays; git diff --check passed. Final behavior: upper-right shows per-kind pending quantity only; each unit production duration maps to one full radial circle, next queued unit restarts from zero; final second uses lighter opacity. Existing unrelated baseline failures remain: worker_collisions 1, mining/food/wood timing suites, game_hud obsolete BodyScroll assertion.\", \"updated_at\": \"2026-09-09T13:26:13+00:00\", \"continues_from\": []}, {\"id\": \"TS-061\", \"project_key\": \"project_0001\", \"title\": \"素材库增加兵种进化前后对照\", \"description\": \"用户于 2026-09-09 至 2026-09-10 确认：新版素材库中 Free Pack 与 Update 010 各有一套工人、弓箭手、战士素材，应登记为同兵种的基础形态与进化形态并提供升级前后对照。基础形态分别为 free/character/pawn、free/character/archer、free/character/warrior；进化形态分别为 update010/character/knights/pawn、update010/character/knights/archer、update010/character/knights/warrior。蓝、紫、红、黄可一一对应；Free Pack 独有黑色且 Update 010 无对应黑色，页面必须明确显示缺少进化变体，不得擅自改色或生成素材。素材详情增加“基础形态 → Lv.5 且对应科技完成后可进化”的关系展示，进化等级仅为可配置默认值的说明，不在素材库实现游戏逻辑。保留角色/素材组与全部文件视图，不移动、覆盖或复制原始素材。验收覆盖三组映射、四种共同颜色、黑色缺失提示、前后详情跳转、搜索筛选及现有 841 文件/102 组一致性。分类：素材管理/进化关系；UI/前后对照。关联：TS-052、TS-062。决策记录：godot-game-learn/docs/decisions/adr_002_unit_evolution_asset_pairs.md。用户已明确授权本次登记、普通提交推送及认领实施。 【验收退回 2026-09-12】用户判定验收不通过：交付提交 8e6357707e8e547e1ab2b9a8b7c19951d16d6317 不在 godot-game-learn-main 历史；8766 assets-view 仅有换色、无 Free Pack↔Update 010 形态对照/黑色缺失提示/详情跳转。退回 ready 供返工认领。\", \"status\": \"done\", \"owner\": \"sasaki\", \"scopes\": [\"asset_evolution_mapping\", \"asset_group_comparison\", \"asset_index_ui\"], \"delivery_commit\": \"feb1d966774a484576cf21ede7e4b466f031a573\", \"delivery_tests\": \"ACCEPTED by user 2026-09-12. Branch task/TS-061-unit-evolution-asset-pairs @ d2f55ce44300bb99f7f989458c87d98663931a88. Await merge-to-main vs next-acceptance (ADR-035); done after main merge. Evolution UI retained as-is per independent-unit product note; Update 010 knight sheet rows named idle/run/attack1-5; UI cleanup (no duplicate row-hint bar; advanced slicer collapsed). PASS verify_asset_catalog.cjs; browser ?v=ts061-5.\", \"updated_at\": \"2026-09-12T12:20:23+00:00\", \"continues_from\": []}, {\"id\": \"TS-062\", \"project_key\": \"project_0001\", \"title\": \"可配置等级与科技双条件单位进化\", \"description\": \"用户于 2026-09-10 确认采用单位个体培养与科技资格共同控制进化：每个单位独立登记等级和进化状态，默认 required_level=5，可配置；同时必须完成该兵种配置的 required_technology，才将该个体从 Free Pack 基础素材替换为 Update 010 进化素材。未达到等级的单位不得因科技完成而提前进化，新生产单位仍从基础形态开始；达到等级但科技未完成时保持待进化，科技完成后立即重新判定。工人、弓箭手、战士分别配置素材组和对应科技；已有单位与新单位共用同一判定且进化只执行一次。科技继续提供按兵种限定的全军百分比增幅，个体等级与外观进化状态独立，禁止重复叠加属性。第一阶段只实现可配置判定、素材替换、运行时状态登记与测试；跨局持久化、工人劳动经验来源和死亡继承规则另行确认，不在本任务擅自扩展。依赖 TS-052 的军事科技接口与通用单位属性配置；素材映射来自 TS-061。验收覆盖阈值边界、科技先后顺序、单个单位独立进化、重复判定、三兵种素材切换、颜色映射缺失回退及新旧单位并存。分类：玩法/单位进化；配置/成长条件；视觉/素材替换。决策记录：temp-02/docs/decisions/adr_023_configurable_unit_evolution.md。用户已明确授权本次登记及普通提交推送；实施应在依赖满足且无 scope 冲突后认领。\", \"status\": \"claimed\", \"owner\": \"sasaki\", \"scopes\": [\"unit_evolution\", \"unit_visual_progression\", \"evolution_config\", \"unit_progression_state\", \"combat_technology_evolution\"], \"delivery_commit\": null, \"delivery_tests\": null, \"updated_at\": \"2026-09-13T14:47:54+00:00\", \"continues_from\": []}, {\"id\": \"TS-063\", \"project_key\": \"project_0001\", \"title\": \"MVP哥布林死亡烟尘与骷髅消散\", \"description\": \"2026-09-10用户确认取消模拟受击停顿和位移，致命一击立即播放Dust_01烟尘遮挡哥布林，再衔接Dead骷髅消散。死亡立即关闭碰撞、仅结算一次经验；特效独立清理，覆盖升级/胜利对话和重试。仅实施死亡表现，三关与通用角色配置插件待后续确认。分类：视觉/死亡反馈。决策：temp-02/docs/decisions/adr_021_warrior_mvp.md。用户本轮明确允许登记认领及测试后代码普通提交推送；接续TS-055/057并保留待验收。\", \"status\": \"done\", \"owner\": \"codex_warrior_mvp\", \"scopes\": [\"mvp_combat\", \"mvp_death_fx\"], \"delivery_commit\": \"3f15004f1210f6c138f23413a5e4c6f8985b1dfd\", \"delivery_tests\": \"Implementation b8f3f52ed966743a4d3ee97e9af5d4954b6e1320. Godot4.7.2 import exit0; death13 + MVP32 + growth37 + dock23 + tutorial30 =135 checks passed. Real OpenGL 4-stage death frames inspected. New test initial WeakRef inference parse error fixed with explicit type; rerun13 passed. Existing resource failures unchanged: collisions1/mining10/food8/wood9; HUD missing BodyScroll timeout35s; old RID exit leaks. Sheep43 and tech/purchase/troop/production assertions passed. diff-check passed. Death cosmetic runs during dialogue pause, clears on retry/exit, immediate single XP reward; no three-stage or plugin changes. 用户 2026-09-13 确认此前验收已通过。\", \"updated_at\": \"2026-09-13T08:40:00+00:00\", \"continues_from\": [\"TS-055\", \"TS-057\"]}, {\"id\": \"TS-064\", \"project_key\": \"project_0001\", \"title\": \"MVP三关成长循环与角色配置下拉插件\", \"description\": \"用户确认方案并明确授予本次登记认领与普通提交推送权限。三关各5怪，刷新本关或进入下一关保留等级经验当前血量属性；安全出生点，结算不回血；第三关刷新或从第一关重置，失败重置。上限6级，经验40/60/90/130/180，怪物生命55/85/120攻击10/14/18防御1/3/5经验20/35/50。插件更名角色配置，当前编辑场景及待生成角色目录扫描、唯一ID下拉，战士与哥布林可配，未接入类型只读，未保存切换提示。分类：玩法/关卡成长；工具/角色配置。决策temp-02/docs/decisions/adr_021_warrior_mvp.md追加。接续55/56/57/63，不自动验收前序。\", \"status\": \"done\", \"owner\": \"codex_warrior_mvp\", \"scopes\": [\"mvp_combat\", \"mvp_progression\", \"mvp_hud\", \"mvp_editor_plugin\", \"mvp_progression_config\"], \"delivery_commit\": \"a439fb070c585f9b25b385450fa94e04efa2b14c\", \"delivery_tests\": \"Implementation6c9b43c77c6e550ee4bff8a88d3b8c59e1f348f8. Godot4.7.2 campaign39+character15+death13+combat32+growth37+dock23+tutorial30=189 checks passed. Final tier whitelist change retested campaign39 and character15 passed. Headless editor import exit0; real renderer campaign and character dock including narrow layout inspected. Full three-stage live combat reaches level6; HP/XP retained, repeat rewards, failure/reset, readonly roles and dirty switch protected. Existing regressions unchanged: collisions1/mining10/food8/wood9 failures; HUD missing BodyScroll timeout35s; old RID leaks. Other sheep/tech/purchase/troop/production assertions passed. FF synced documentation-only61e449a; diff-check passed. Await user acceptance; formal roles remain readonly as agreed.\", \"updated_at\": \"2026-09-10T12:57:51+00:00\", \"continues_from\": [\"TS-055\", \"TS-056\", \"TS-057\", \"TS-063\"]}, {\"id\": \"TS-065\", \"project_key\": \"project_0001\", \"title\": \"建筑物图层遮罩与碰撞体积优化\", \"description\": \"用户于 2026-09-11 提出新增需求：优化建筑物的图层遮罩与碰撞体积。现状基线：TS-038 遮罩多边形作视觉遮挡（clip/Y 排序相关已迭代）、TS-039 控制台碰撞在游戏内作阻挡、TS-010 曾验收底部占地与前后遮挡。本任务聚焦观感与站位体验优化：遮罩范围/顶点与建筑贴图对齐、单位被错误裁切或踩屋顶问题；碰撞体积与真实墙脚占地一致，工人/兵种通行与停靠不被过大或错位的阻挡卡住。不擅自改动 PM 控制台编辑器交互（TS-031/035）；改碰撞/遮罩数据须经快照加载验证。待确认：优先建筑清单（城堡/房/兵营/箭塔/靶场/金矿等）、验收截图或对照标准、是否允许改 PM 默认碰撞与 mask_polygon。实施前在 temp-02/docs/decisions/ 建 ADR 并回填；更新 gameplay_interaction_rules 与 visual_occlusion/runtime_collision 相关测试。分类：玩法/建筑视觉与碰撞；关联 TS-010、TS-038、TS-039。仅登记待确认，不认领不实施。\", \"status\": \"claimed\", \"owner\": \"sasaki\", \"scopes\": [\"building_visual_mask_opt\", \"building_collision_volume_opt\"], \"delivery_commit\": null, \"delivery_tests\": null, \"updated_at\": \"2026-09-14T01:45:33+00:00\", \"continues_from\": []}, {\"id\": \"TS-066\", \"project_key\": \"project_0001\", \"title\": \"建筑物受击燃烧效果优化\", \"description\": \"用户于 2026-09-11 提出新增需求：优化建筑物受击后的燃烧效果。现状基线：TS-051 修缮链路中 `_update_building_damage_fx` 按生命比例切换 Fire_01/Fire_02 静态贴图；满血移除、重伤加深透明度；城堡与 runtime 建筑位置偏移不同。本任务仅优化燃烧表现（动画/层级/贴合建筑/轻重档过渡），不改生命结算、修缮扣木、怪物索敌与血条规则。范围协调：TS-051（sasaki，claimed：building_repair 等）交付或交接前勿改同一修缮主路径；本任务 scope 独立为 building_damage_fire_fx，认领前须确认与 TS-051 无文件冲突。待确认：期望素材（现有 Fire 帧动画或 Particle）、是否跟随生命阈值动画、是否含主城与全部可修缮建筑、可接受的 z/Y 排序表现。实施前扩展 adr_019 或新建 ADR；补充燃烧显隐与层级专项/真实渲染对照。分类：视觉/建筑受损反馈；关联 TS-050、TS-051、TS-053。仅登记待确认，不认领不实施。\", \"status\": \"claimed\", \"owner\": \"codex_ts066\", \"scopes\": [\"building_damage_fire_fx\"], \"delivery_commit\": null, \"delivery_tests\": null, \"updated_at\": \"2026-09-14T02:21:50+00:00\", \"continues_from\": []}, {\"id\": \"TS-067\", \"project_key\": \"project_0002\", \"title\": \"map-build 接入 TinySwordsPM（项目维度 + 插件扫描基线）\", \"description\": \"在 TinySwordsPM 登记 project_0002/key=map-build；Godot 工程启用 tiny_swords_pm 插件（PROJECT_KEY=map-build）；能扫描 reference_valley 并写入 data/tiny_swords_pm.json 快照。不改玩法逻辑。验收：管理页可见该项目与任务；编辑器扫描/拉取成功。\", \"status\": \"done\", \"owner\": \"sasaki\", \"scopes\": [\"pm_integration\", \"godot_plugin\"], \"delivery_commit\": \"93121518d4bbb7e23b1c188f96e0a4c8f302157b\", \"delivery_tests\": \"PASS: python tools/validate_pm_bridge.py --start-server (scan entities=532 resources=10, pull project_0002/map-build snapshot, tasks TS-067..077 visible); PASS: Godot 4.7.2 headless --script res://tools/validate_pm_bridge_godot.gd prints TS067_PM_BRIDGE_OK; plugin enabled in project.godot with PROJECT_KEY=map-build; no gameplay/map overwrite. Mount unmatched_count=10 expected until asset catalog alignment (TS-070).\", \"updated_at\": \"2026-09-11T08:28:47+00:00\", \"continues_from\": []}, {\"id\": \"TS-068\", \"project_key\": \"project_0002\", \"title\": \"道路与桥梁可行走区域生成\", \"description\": \"从 Terrain_基础地形 识别 custom_data=road 的黄色道路格，以及 Bridges_桥梁 下桥面 TileMap（custom_data=bridge），生成可行走 mask / Navigation 或等效碰撞数据。输出可重复运行的 tools 脚本，不覆盖用户已保存摆放。验收：主路与两座桥面可查询为可行走；报告格数。\", \"status\": \"review\", \"owner\": \"sasaki\", \"scopes\": [\"walkability\", \"roads\", \"bridges\"], \"delivery_commit\": \"97bb1a485c71751a30fd53446bbb1d36abc99f76\", \"delivery_tests\": \"PASS: Godot 4.7.2 headless tools/build_walkability_roads.gd -> WALKABILITY_ROADS_OK roads=473 bridges=2 deck_cells=18 walkable_union=487 (road+bridge overlap=4); PASS: --validate-only roundtrip WALKABILITY_ROADS_VALIDATE_OK; outputs data/maps/reference_valley_walkability.json and previews/reference_valley_walkability_mask.png; reference_valley.tscn unchanged.\", \"updated_at\": \"2026-09-11T08:30:49+00:00\", \"continues_from\": []}, {\"id\": \"TS-069\", \"project_key\": \"project_0002\", \"title\": \"水体与岩壁不可走阻挡层\", \"description\": \"基于同一基础地形层将水面、岩壁（及必要时越界外区）标为不可走，与 TS-068 道路/桥面合并为完整通行图。禁止多层覆盖伪造阻挡。验收：水中/立面不可走，道路与桥头连通；有校验报告。\", \"status\": \"review\", \"owner\": \"sasaki\", \"scopes\": [\"walkability\", \"terrain_blockers\"], \"delivery_commit\": \"8ad54aca43fec5eb97e9577311b1da1c87c8dc7e\", \"delivery_tests\": \"PASS: Godot 4.7.2 headless tools/build_terrain_blockers.gd -> TERRAIN_BLOCKERS_OK water=472 cliff=127 empty=0 path=487 surface=2514; PASS: --validate-only TERRAIN_BLOCKERS_VALIDATE_OK; outputs data/maps/reference_valley_passability.json and preview mask; reference_valley.tscn unchanged; depends on TS-068 walkability json.\", \"updated_at\": \"2026-09-11T09:12:32+00:00\", \"continues_from\": [\"TS-068\"]}, {\"id\": \"TS-070\", \"p